// on every page that has one (withTripNav), including the homepage and
// /browse, whose source file is frozen.
const TRIP_NAV_SNIPPET = `<style id="trip-nav">
html.trip-nav-on #tripTrayToggle { display: none !important; }
html.trip-nav-on #tripTray { top: 70px; bottom: auto; right: 16px; left: auto; }
html.trip-nav-on #tripTrayPanel { position: static; width: min(320px, calc(100vw - 32px)); max-height: min(70vh, 520px); }
#tripTrayPanel { position: relative; }
#tripTrayPanel .trip-tray-close { position: absolute; top: 8px; right: 8px; width: 34px; height: 34px; border-radius: 999px; border: 0; background: rgba(27,43,58,0.08); font-size: 1.3rem; line-height: 1; cursor: pointer; color: inherit; }
#tripTrayPanel .trip-item a { color: inherit; font-weight: 700; }
#tripTrayPanel .trip-tray-full { display: block; margin: 10px 0 4px; text-align: center; font-weight: 800; font-size: 0.9rem; }
#tripTrayPanel .trip-tray-full[hidden] { display: none; }
.nav-links-mytrip { list-style: none; }
.nav-mytrip-btn { display: inline-flex; align-items: center; gap: 6px; background: none; border: 0; padding: 0; margin: 0; font: inherit; color: inherit; cursor: pointer; white-space: nowrap; }
.nav-mytrip-btn:focus-visible { outline: 2px solid var(--ref-gold, #E0A94E); outline-offset: 3px; border-radius: 6px; }
.nav-mytrip-count, .nav-hamburger-count { display: inline-flex; align-items: center; justify-content: center; min-width: 20px; height: 20px; padding: 0 6px; box-sizing: border-box; border-radius: 999px; background: var(--ref-gold, #E0A94E); color: var(--ref-navy, #1B2B3A); font-size: 0.72rem; font-weight: 800; line-height: 1; }
.nav-mytrip-fr { display: none; }
html[lang="fr"] .nav-mytrip-fr { display: inline; }
html[lang="fr"] .nav-mytrip-en { display: none; }
#navHamburger { position: relative; }
#navHamburger .nav-hamburger-count { position: absolute; top: -2px; right: -8px; left: auto; bottom: auto; display: inline-flex; width: auto; min-width: 18px; height: 18px; margin: 0; padding: 0 5px; transform: none; opacity: 1; font-style: normal; font-size: 0.66rem; pointer-events: none; }
#navHamburger .nav-hamburger-count[hidden] { display: none; }
@media (max-width: 940px) {
  .nav-links .nav-links-mytrip { order: -1; border-top: 0; padding: 4px 20px 6px; }
  .nav-links .nav-mytrip-btn { width: 100%; justify-content: space-between; min-height: 48px; padding: 0 18px; border: 1px solid rgba(27,43,58,0.2); border-radius: 12px; font-weight: 800; color: var(--ref-navy, #1B2B3A); }
  .nav-links .nav-mytrip-label { margin-right: auto; }
}
.nav-hamburger-count[hidden] { display: none; }
@media (min-width: 941px) { #navHamburger .nav-hamburger-count { display: none; } }
@media (min-width: 941px) and (max-width: 1099px) { .nav-mytrip-label { display: none; } }
</style>
<script>
(function(){
  function init(){
    var tray = document.getElementById('tripTray'), toggle = document.getElementById('tripTrayToggle'), panel = document.getElementById('tripTrayPanel');
    var count = document.getElementById('tripTrayCount'), links = document.getElementById('navLinks'), burger = document.getElementById('navHamburger');
    if (!tray || !toggle || !panel || !links || document.querySelector('.nav-links-mytrip')) return;
    document.documentElement.classList.add('trip-nav-on');
    var li = document.createElement('li');
    li.className = 'nav-links-mytrip';
    li.innerHTML = '<button type="button" class="nav-mytrip-btn" aria-controls="tripTrayPanel" aria-expanded="false"><span aria-hidden="true">\u{1F9F3}</span> <span class="nav-mytrip-label"><span class="nav-mytrip-en">My Trip</span><span class="nav-mytrip-fr" lang="fr">Mon voyage</span></span> <span class="nav-mytrip-count">0</span></button>';
    // Right after Build My Trip: on phones that pair leads the menu.
    var tripLi = links.querySelector('.nav-links-trip');
    links.insertBefore(li, tripLi ? tripLi.nextSibling : null);
    var btn = li.querySelector('button'), navCount = li.querySelector('.nav-mytrip-count');
    var badge = null;
    if (burger) { badge = document.createElement('b'); badge.className = 'nav-hamburger-count'; badge.setAttribute('aria-hidden', 'true'); badge.hidden = true; burger.appendChild(badge); }
    function sync(){
      var n = count ? (parseInt(count.textContent, 10) || 0) : 0;
      navCount.textContent = String(n);
      btn.setAttribute('aria-label', (document.documentElement.lang === 'fr' ? 'Mon voyage : ' : 'My Trip: ') + n + (document.documentElement.lang === 'fr' ? (n === 1 ? ' arr\u00eat' : ' arr\u00eats') : (n === 1 ? ' stop' : ' stops')));
      btn.setAttribute('aria-expanded', panel.classList.contains('open') ? 'true' : 'false');
      if (badge) { badge.textContent = String(n); badge.hidden = n === 0; }
    }
    btn.addEventListener('click', function(e){
      // The tray's own outside-click rule would close it again as this click
      // bubbles, so it stops here; pressing the hidden toggle opens or closes
      // the tray through app.js exactly as the floating button did.
      e.stopPropagation();
      if (links.classList.contains('open')) { links.classList.remove('open'); if (burger) burger.setAttribute('aria-expanded', 'false'); }
      toggle.click();
      sync();
    });
    if (count && window.MutationObserver) new MutationObserver(sync).observe(count, { childList: true, characterData: true, subtree: true });
    if (window.MutationObserver) new MutationObserver(sync).observe(panel, { attributes: true, attributeFilter: ['class'] });
    sync();
    enhanceTray(panel);
  }
  // Tray extras (2026-10-14): a close button, each stop linked to its page
  // with a small "Restaurant \u00b7 Kelowna" line, and "Open full trip". app.js
  // (frozen) still owns the list; this only decorates what it draws.
  function enhanceTray(panel){
    var list = document.getElementById('tripTrayList'), clear = document.getElementById('tripClearBtn');
    if (!list || panel.getAttribute('data-enhanced')) return;
    panel.setAttribute('data-enhanced', '1');
    var close = document.createElement('button');
    close.type = 'button'; close.className = 'trip-tray-close'; close.setAttribute('aria-label', 'Close My Trip'); close.innerHTML = '&times;';
    close.addEventListener('click', function(e){ e.stopPropagation(); panel.classList.remove('open'); });
    panel.insertBefore(close, panel.firstChild);
    var full = document.createElement('a');
    full.href = '/my-trip'; full.className = 'trip-tray-full'; full.textContent = 'Open full trip: days, map and share link \u2192';
    if (clear) panel.insertBefore(full, clear);
    var info = {}, busy = false;
    function stored(){ try { return JSON.parse(localStorage.getItem('okanaganTrip') || '[]') || []; } catch (e) { return []; } }
    function esc(t){ return String(t).replace(/[&<>"]/g, function(c){ return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
    function decorate(){
      var items = list.querySelectorAll('.trip-item'), trip = stored();
      full.hidden = !items.length;
      Array.prototype.forEach.call(items, function(item, i){
        var t = trip[i], d = t && t.ref && info[t.ref];
        var span = item.querySelector('span');
        if (!d || !span || item.getAttribute('data-linked') === t.ref) return;
        item.setAttribute('data-linked', t.ref);
        span.innerHTML = (i + 1) + '. <a href="' + esc(d.url) + '">' + esc(d.name) + '</a><br><small class="trip-distance">' + esc([d.type, d.regionLabel].filter(Boolean).join(' \u00b7 ')) + '</small>';
      });
    }
    function refresh(){
      var refs = stored().map(function(x){ return x && x.ref; }).filter(function(r){ return r && !info[r]; });
      if (!refs.length || busy || !window.fetch) { decorate(); return; }
      busy = true;
      fetch('/api/trip-stops?refs=' + encodeURIComponent(refs.join(','))).then(function(r){ return r.json(); }).then(function(d){ (d.stops || []).forEach(function(x){ if (!x.missing) info[x.ref] = x; }); }).catch(function(){}).then(function(){ busy = false; decorate(); });
    }
    if (window.MutationObserver) new MutationObserver(function(){ refresh(); }).observe(list, { childList: true });
    refresh();
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init); else init();
})();
</script>
`;
function withTripNav(html) {
  if (!html || !html.includes('<div id="tripTray">') || html.includes('<style id="trip-nav">')) return html;
  return html.replace('<div id="tripTray">', `${TRIP_NAV_SNIPPET}<div id="tripTray">`);
}

// app.js cache busting (2026-10-05): every page loads /scripts/app.js with
// its content hash in the URL (/scripts/app.js?v=<12 hex>). Browsers keep the
// script for up to 4 hours (Cloudflare raises the origin's max-age=3600) and
// Cloudflare's edge for an hour, so an unchanged URL could pair new HTML with
// an old app.js after a deploy. A changed file is a new URL, fetched fresh by
// the browser and the edge. The static route matches the path only, so the
// query is ignored there; the Cache-Control header is unchanged.
const APP_JS_PLAIN_TAG = '<script src="/scripts/app.js"></script>';
function appJsSrcFor(content) {
  return '/scripts/app.js?v=' + crypto.createHash('md5').update(content).digest('hex').slice(0, 12);
}
const APP_JS_SRC = (() => {
  try { return appJsSrcFor(fs.readFileSync(path.join(__dirname, 'public', 'scripts', 'app.js'))); } catch (e) { return '/scripts/app.js'; }
})();
const APP_JS_SCRIPT_TAG = `<script src="${APP_JS_SRC}"></script>`;
// okanagan.html (frozen; served for / and /browse) keeps its plain tag on
// disk; the served copy gets the versioned one.
function withVersionedAppJs(html) {
  return html.replace(APP_JS_PLAIN_TAG, APP_JS_SCRIPT_TAG);
}
const GOLF_APP_SCRIPT_TAG = APP_JS_SCRIPT_TAG;

// Body class for themed pages. Golf keeps exactly its deployed
// `class="golf-page"`; Beach pages carry the same theme class (the
// body.golf-page rules ARE the design system these pages share) plus a
// `beach-page` marker for beach-specific tests/styling. Non-themed pages
// get no class attribute at all, exactly as before.
function themedBodyClassAttr(type, themed = usesThemedCategoryLayout(type)) {
  if (type === 'golf') return ' class="golf-page"';
  if (themed) return ` class="golf-page ${type}-page"`;
  return '';
}

// Beach variants of every Golf card/CTA rule that is keyed on the
// data-venue-category="golf" attribute selector (in SEO_PAGE_CSS and the
// theme block). Derived mechanically from the Golf rules at request time
// rather than copied, so the two categories can never drift apart in
// styling, and the Golf CSS text itself is untouched. The selector
// regex matches a complete rule (selector list + declaration block)
// whose selector list mentions the golf attribute.
function deriveBeachRulesFromGolfCss(cssText, type = 'beach') {
  const ruleRe = /[^{}]*\[data-venue-category="golf"\][^{}]*\{[^{}]*\}/g;
  return (cssText.match(ruleRe) || [])
    .map((rule) => rule.replace(/\[data-venue-category="golf"\]/g, `[data-venue-category="${type}"]`).trim())
    .join('\n  ');
}
// Batch A (2026-09-27, P-004 / K-003): the derived theme blocks are pure
// functions of constant CSS (SEO_PAGE_CSS and the Golf theme text), so each
// is built once per process on first use and the same string is returned on
