function golfAtAGlanceHtml(venue) {
  if (venue.type !== 'golf' || venue.redirect_to) return '';
  const facts = GOLF_AT_A_GLANCE_FACTS[`${venue.region}/${venue.slug}`];
  if (!facts || !facts.length) return '';
  const items = facts
    .map(([lbl, val]) => `<div class="golf-glance-item"><dt>${escapeHtml(lbl)}</dt><dd>${escapeHtml(val)}</dd></div>`)
    .join('\n      ');
  return `<div class="venue-section golf-glance">
    <h2>At a glance</h2>
    <dl>
      ${items}
    </dl>
  </div>`;
}

// Category-page behaviour for Golf cards: the clamp class is applied only
// once JS runs (so no-JS readers always see the full text), the Read more
// control is revealed only when the text is actually truncated, the
// toggle is inline with aria-expanded/aria-controls, and impressions
// (>=50% visible, once per card per page view) plus expand/collapse are
// reported through window.trackEvent.
// Outdoor surfaces (2026-09-22) list every OUTDOOR_ACTIVITY_VENUE_TYPES
// record (a beach-type activity member renders as a beach card there), so
// on those pages the card selector covers each allowlisted type -- the
// clamp / Read more, impressions and favourite/trip mirroring then apply
// to every card on the page and the reported venue_category is the
// card's own. Golf and Beach pages' scripts are byte-identical to before.
function themedCardHolderSelector(type) {
  // 'fd' is the Food & Drink hub, whose one list mixes all five Food & Drink
  // types; without this its non-restaurant cards got no engagement wiring at
  // all, so their Favorite / Add to Trip buttons did nothing.
  if (type === 'fd') return `:is(${FOOD_DRINK_TYPES.map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  // 'dog' is the Dog Friendly Finds hub, whose one list mixes the five Food &
  // Drink types, wineries and the curated dog beaches.
  if (type === 'dog') return `:is(${DOG_HUB_VENUE_TYPES.map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  // 'lf' is the Local Favourites page, whose one list can hold any venue type.
  if (type === 'lf') return `:is(${Object.keys(CATEGORY_SLUGS).map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  // 'guide' (Stage 5B) is a guide page, whose one list can hold any venue
  // type -- the same set as 'lf', but its events report each card's own
  // venue_category (see golfCardEngagementScriptHtml).
  if (type === 'guide') return `:is(${Object.keys(CATEGORY_SLUGS).map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  // 'indoor': the /indoor hub also lists the indoor golf simulators (type golf)
  // and, in "Also good on a rainy day", tagged venues of any other type (an
  // arena, a brewery with bowling, a board-game cafe), so it wires every type
  // -- otherwise those cards got no Read more clamp and dead Favorite / Trip
  // buttons.
  if (type === 'indoor') return `:is(${Object.keys(CATEGORY_SLUGS).map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  // 'tour': the /tours hub's "More experiences to book" lists tagged
  // operators of any other type (mostly outdoor), so it wires every type too.
  if (type === 'tour') return `:is(${Object.keys(CATEGORY_SLUGS).map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  // 'sport': the /sports hub's "More places to play" too (2026-10-12).
  if (type === 'sport') return `:is(${Object.keys(CATEGORY_SLUGS).map((t) => `[data-venue-category="${t}"]`).join(',')})`;
  if (type !== 'outdoor') return `[data-venue-category="${type}"]`;
  return `:is(${OUTDOOR_ACTIVITY_VENUE_TYPES.map((t) => `[data-venue-category="${t}"]`).join(',')})`;
}
// opts.impressionCards (Stage 5B, optional): a selector limiting which cards
// report venue_impression. Guide pages pass golf cards only, so the impression
// stream stays exactly as it was when only golf guide cards were wired. Without
// it (every other caller) the script is byte-identical to before.
function golfCardEngagementScriptHtml(type, themed = usesThemedCategoryLayout(type), opts = {}) {
  if (!themed) return '';
  const observe = opts.impressionCards
    ? `if (c.matches(${JSON.stringify(opts.impressionCards)})) io.observe(c);`
    : 'io.observe(c);';
  return `<script>
(function(){
  var cards = Array.prototype.slice.call(document.querySelectorAll('.venue-card${themedCardHolderSelector(type)}'));
  if (!cards.length) return;
  function ctx(card){
    return {
      venue_id: Number(card.dataset.venueId),
      venue_name: card.dataset.venueName,
      venue_region: card.dataset.venueRegion,
      venue_category: ${(type === 'outdoor' || type === 'fd' || type === 'guide' || type === 'indoor' || type === 'tour' || type === 'sport') ? `card.dataset.venueCategory || '${type}'` : `'${type}'`},
      surface: card.dataset.surface || 'category_card',
      // Not "page_path": gtag treats page_path as its own field (sent as the
      // hit's dp), so it never reached GA4 as an event parameter (2026-10-05).
      card_page_path: location.pathname
    };
  }
  function track(name, params){ if (window.trackEvent) window.trackEvent(name, params); }
  var MORE = 'Read more \\u2192', LESS = 'Read less \\u2191';
  function isTruncated(p){ return p.scrollHeight > p.clientHeight + 1; }
  // Mobile performance (2026-10-03): asking whether a clamped description
  // overflows makes the browser lay out its full text, so doing it for every
  // card at load froze large hubs for seconds on phones. As on /browse
  // (Stage 3.4.1), the clamp is applied at once but each description is
  // measured when its card comes within 400px of the viewport; the rest are
  // then measured in the background in ~8ms slices (never a long task), so a
  // card reached by a fast scroll or a jump is normally already measured and
  // its Read more never pops in under the reader. A card hidden by a filter
  // is left until it is shown. Its Read more stays hidden, as served, until
  // measured. Within one batch every height is read before any button
  // changes, so a batch costs one layout.
  var pending = [], drainTimer = null, scrollWatching = false;
  function measure(list){
    list = list.filter(function(x){ return !x.measured; });
    var over = list.map(function(x){ return isTruncated(x.p); });
    list.forEach(function(x, i){ x.measured = true; x.btn.hidden = !over[i]; if (measureIo) measureIo.unobserve(x.card); });
  }
  var measureIo = ('IntersectionObserver' in window) ? new IntersectionObserver(function(entries){
    var due = [];
    entries.forEach(function(en){
      var x = en.target.__ogReadMore;
      if (en.isIntersecting && x && due.indexOf(x) === -1) due.push(x);
    });
    measure(due);
  }, { rootMargin: '400px 0px' }) : null;
  function drain(){
    drainTimer = null;
    var start = Date.now(), batch = [], over = [];
    while (pending.length && Date.now() - start < 8) {
      var x = pending.shift();
      x.queued = false;
      // Hidden by a filter (or not in the page): measured when shown instead.
      if (x.measured || x.card.offsetParent === null) continue;
      batch.push(x); over.push(isTruncated(x.p));
    }
    batch.forEach(function(x, i){ x.measured = true; x.btn.hidden = !over[i]; measureIo.unobserve(x.card); });
    if (pending.length) drainTimer = setTimeout(drain, 16); else stopScrollWatch();
  }
  function watch(x){
    if (!measureIo) { measure([x]); return; }
    x.measured = false;
    x.card.__ogReadMore = x;
    measureIo.observe(x.card);
    if (!x.queued) { x.queued = true; pending.push(x); }
    if (!drainTimer) drainTimer = setTimeout(drain, 300);
    startScrollWatch();
  }
  function setup(card){
    var desc = card.querySelector('.golf-desc');
    var btn = card.querySelector('.desc-toggle');
    if (!desc || !btn) return;
    var p = desc.querySelector('p');
    if (!p) return;
    desc.classList.add('is-clamped');
    var x = { card: card, btn: btn, p: p };
    btn.addEventListener('click', function(){
      var expanded = btn.getAttribute('aria-expanded') === 'true';
      desc.classList.toggle('is-clamped', expanded);
      btn.setAttribute('aria-expanded', expanded ? 'false' : 'true');
      btn.textContent = expanded ? MORE : LESS;
      track(expanded ? 'description_collapse' : 'description_expand', ctx(card));
    });
    card._golfRecheck = function(){
      if (btn.getAttribute('aria-expanded') === 'true') return;
      watch(x);
    };
    watch(x);
  }
  cards.forEach(setup);
  // These cards are wired now, so __ogWireVenueCards (below) must never wire
  // them again when a filter re-inserts one: that added a second Read more
  // listener (one tap expanded and collapsed it) and re-observed impressions.
  cards.forEach(function(card){ card.__ogWired = true; });
  // Cards already on screen are measured now, in the same task as their clamp,
  // so the clamp and Read more appear together (no second shift). Until the
  // background pass has measured every shown card, a passive scroll listener
  // measures cards entering the screen -- scroll events run before the browser
  // draws the frame, so a jump or fast scroll never shows a card whose Read
  // more then pops in. It detaches when the pass is done.
  function onScreen(){
    var h = window.innerHeight || document.documentElement.clientHeight;
    return pending.filter(function(x){
      if (x.measured || x.card.offsetParent === null) return false;
      var r = x.card.getBoundingClientRect();
      return r.bottom > 0 && r.top < h;
    });
  }
  function measureOnScreen(){ measure(onScreen()); }
  function startScrollWatch(){
    if (scrollWatching) return;
    scrollWatching = true;
    window.addEventListener('scroll', measureOnScreen, { passive: true });
  }
  function stopScrollWatch(){
    if (!scrollWatching) return;
    scrollWatching = false;
    window.removeEventListener('scroll', measureOnScreen, { passive: true });
  }
  if (measureIo) measureOnScreen();
  var resizeTimer;
  window.addEventListener('resize', function(){
    clearTimeout(resizeTimer);
    resizeTimer = setTimeout(function(){
      cards.forEach(function(c){ if (c._golfRecheck) c._golfRecheck(); });
    }, 150);
  });
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if (!en.isIntersecting || en.intersectionRatio < 0.5) return;
        io.unobserve(en.target);
        track('venue_impression', ctx(en.target));
      });
    }, { threshold: 0.5 });
    cards.forEach(function(c){ ${observe} });
  }

  // ---- Favorite + Add to Trip: same localStorage keys, item shape and
  // name-keyed de-duplication as the homepage app (okanaganFavorites is an
  // array of venue names; okanaganTrip is [{name, query, region}], capped
  // at MAX_STOPS), so the existing Trip Planner and favourites filter see
  // exactly what was chosen here.
  // Additive hook (2026-09-24): a page that reveals more venue cards after
  // load -- the Food & Drink hub's "Show more" -- calls this so those cards
  // get exactly this wiring (description clamp / Read more, impression
  // tracking, Favorite / Add to Trip state) rather than a divergent copy.
  // Click handling already works for them without this, because the
  // Favorite/Trip listeners are delegated on document. Nothing here runs
  // unless a page calls it, so every other page is unaffected.
  //
  // This sits ABOVE golfFavTripScriptBody on purpose: that body returns out
  // of this IIFE when app.js is present, so anything after it is dead code.
  // syncAll is a hoisted function declaration in the same scope, so calling
  // it from here still works.
  window.__ogWireVenueCards = function(list){
    (list || []).forEach(function(card){
      if (!card || card.__ogWired) return;
      card.__ogWired = true;
      cards.push(card);
      setup(card);
      ${opts.impressionCards ? `if (typeof io !== 'undefined' && io && card.matches(${JSON.stringify(opts.impressionCards)})) io.observe(card);` : `if (typeof io !== 'undefined' && io) io.observe(card);`}
    });
    if (typeof syncAll === 'function') syncAll();
  };
${golfFavTripScriptBody(type)}
})();
</script>`;
}

// Venue-page behaviour for a Golf venue: one delegated click listener on
// the existing Visit Website / Get Directions / Call links (and the
// matching Good-to-Know and map links), reporting the established
// outbound_click event with link_type plus venue identity, and one
// venue_view on load so page-level impressions carry venue_id too.
//
// Measurement Phase C (2026-09-27): the other venue types (restaurant, cafe,
// pub, brewery, cocktail lounge, distillery) get the same venue_view +
// outbound_click reporting, but NOT the Favorite / Add to Trip module --
// their pages have no such controls, so there is nothing else to report.
function golfVenueEngagementScriptHtml(venue) {
  const favTrip = venuePageUsesEngagement(venue.type);
  const pageCtx = JSON.stringify({
    venue_id: venue.id,
    venue_name: venue.name,
    venue_region: venue.region,
    venue_category: venue.type,
    surface: 'venue_page',
  }).replace(/</g, '\\u003c');
  return `<script>
(function(){
  var pageCtx = ${pageCtx};
  function ctx(){ var c = {}; for (var k in pageCtx) c[k] = pageCtx[k]; return c; }
  function track(name, params){ if (window.trackEvent) window.trackEvent(name, params); }
  track('venue_view', ctx());
  document.addEventListener('click', function(e){
    var link = e.target.closest('a[data-track]');
    if (!link) return;
    var params = ctx();
    params.link_type = link.getAttribute('data-track');
    track('outbound_click', params);
  });
${favTrip ? golfFavTripScriptBody(venue.type) : ''}
})();
</script>`;
}

// Save to home screen (2026-10-14): a web app manifest and an Apple touch
// icon, so a phone that adds Okanagan Roam to its home screen shows the
// logo and opens the site full screen.
const HOME_SCREEN_HEAD_LINKS = '<link rel="manifest" href="/site.webmanifest">\n<link rel="apple-touch-icon" href="/images/icons/okanagan-roam-apple-touch-180.png">\n<meta name="theme-color" content="#1F5C5C">';
const SITE_WEBMANIFEST = JSON.stringify({
  name: 'Okanagan Roam',
  short_name: 'Okanagan Roam',
  description: 'A free, local guide to the Okanagan Valley: places to eat, drink and explore, events and trip plans.',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  background_color: '#F5EDDD',
  theme_color: '#1F5C5C',
  icons: [
    { src: '/images/icons/okanagan-roam-icon-192.png', sizes: '192x192', type: 'image/png' },
    { src: '/images/icons/okanagan-roam-icon-512.png', sizes: '512x512', type: 'image/png' },
  ],
  // Long-press the home-screen icon (Android): straight to what's open nearby.
  shortcuts: [
    { name: 'Roam Now: what’s open near me', short_name: 'Roam Now', url: '/map#near-me', icons: [{ src: '/images/icons/okanagan-roam-icon-192.png', sizes: '192x192' }] },
    { name: 'What’s on this week', short_name: 'What’s on', url: '/map#events', icons: [{ src: '/images/icons/okanagan-roam-icon-192.png', sizes: '192x192' }] },
  ],
});
function pageHead(title, description, canonical, jsonLdBlocks, opts = {}) {
  // golfTheme (2026-09-19): Golf pages also load the homepage stylesheet
  // (before the inline SEO CSS, so existing SEO rules still win ties) and
  // the body.golf-page overrides. Every other page's head is unchanged.
  // beachTheme (2026-09-19): Beach pages reuse the Golf theme unchanged and
  // add only the beach-attribute variants of its card rules (derived from
  // the Golf rules, see renderBeachThemeStyles) plus, when the page
  // carries one, the advisory-notice styles. Golf pages' head is
  // byte-identical to before.
  // savedSidecar (Stage 4.3): pages that render Favorite controls opt in to
  // the hidden saved-item capture script; every other page's head is unchanged.
  // shareImage (SEO audit, 2026-10-10): a site-relative path to a category,
  // region or guide photo, so shared links stop all showing the same
  // og-image.png. Never set it on single-venue pages: decision #8 forbids
  // a photo that reads as a specific business. Pages that don't pass it
  // keep the exact previous head. No twitter:image is added: X falls back
  // to og:image, and other hubs' heads are pinned to have none.
  const { noindex = false, golfTheme = false, beachTheme = false, outdoorTheme = false, indoorTheme = false, tourTheme = false, sportTheme = false, advisoryStyles = false, golfDataStyles = false, savedSidecar = false, shareImage = null, alternates = null, locale = null } = opts;
  const ogImage = shareImage ? (/^https?:\/\//.test(shareImage) ? shareImage : `https://okanaganroam.com${shareImage}`) : 'https://okanaganroam.com/og-image.png';
  return `<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
${HOME_SCREEN_HEAD_LINKS}
<title>${escapeHtml(title)}</title>
<meta name="description" content="${escapeHtml(description)}">
${canonical === null ? '' : `<link rel="canonical" href="${canonical}">\n`}${alternates ? alternates.map((a) => `<link rel="alternate" hreflang="${a.hreflang}" href="${a.href}">\n`).join('') : ''}${noindex ? '<meta name="robots" content="noindex">\n' : ''}<meta property="og:type" content="website">${locale ? `\n<meta property="og:locale" content="${locale}">` : ''}
<meta property="og:title" content="${escapeHtml(title)}">
<meta property="og:description" content="${escapeHtml(description)}">
<meta property="og:image" content="${ogImage}">
${canonical === null ? '' : `<meta property="og:url" content="${canonical}">\n`}<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${escapeHtml(title)}">
<meta name="twitter:description" content="${escapeHtml(description)}">
${jsonLdBlocks.map((block) => `<script type="application/ld+json">\n${JSON.stringify(block)}\n</script>`).join('\n')}
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Fraunces:ital,wght@0,500;0,600;0,700;1,500;1,600&family=Nunito:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<link rel="stylesheet" href="/styles/tokens.css">
${golfTheme ? '<link rel="stylesheet" href="/styles/app.css">\n' : ''}<style>${SEO_PAGE_CSS}</style>${golfTheme ? '\n' + renderGolfThemeStyles() : ''}${beachTheme ? '\n' + renderBeachThemeStyles() : ''}${outdoorTheme ? '\n' + renderOutdoorThemeStyles() : ''}${indoorTheme ? '\n' + renderIndoorThemeStyles() : ''}${tourTheme ? '\n' + renderTourThemeStyles() : ''}${sportTheme ? '\n' + renderSportThemeStyles() : ''}${advisoryStyles ? '\n' + renderAdvisoryStyles() : ''}${golfDataStyles && golfData ? '\n' + golfData.GOLF_DATA_CSS : ''}${savedSidecar ? '\n' + renderSavedSidecarScriptHtml() : ''}`;
}

function siteHeader(rightLinkHref, rightLinkText) {
  return `<header class="top">
    <a class="brand" href="https://okanaganroam.com/">Okanagan Roam</a>
    <a href="${rightLinkHref}">${escapeHtml(rightLinkText)}</a>
  </header>`;
}

// No longer called anywhere (footer canonicalization, 2026-09-19): every
// page that used to render this minimal one-liner now renders the same
// renderHomeFooterHTML(true) as the homepage instead. Left defined,
// unused, rather than deleted, to keep this change strictly additive/
// substitutive -- the matching `footer.site-footer` CSS rule in
// SEO_PAGE_CSS is similarly harmless now that nothing emits that class.
function siteFooter() {
  return `<footer class="site-footer">Okanagan Roam &middot; <a href="https://okanaganroam.com/">okanaganroam.com</a></footer>`;
}

// ---------- Phase 5 Sprint 1 — shared presentation components ----------
// Small, reusable functions extending the pageHead/siteHeader/siteFooter
// pattern already established above. Each one replaces markup that was
// previously duplicated (in slightly different shapes) across two or more
// of the four render*Page functions below. Nothing here changes any URL,
// slug, canonical, JSON-LD, or metadata behavior — these only produce the
// human-visible HTML fragments that sit inside the unchanged page shells.

// Visible breadcrumb <nav>, as opposed to breadcrumbListSchema() above
// (which produces the separate, JSON-LD structured-data version of the
// same information). items: [{ name, href }], in order from Home to the
// current page. The current/last item is rendered as plain text, not a
// link, matching every existing call site's behavior.
function breadcrumbNavHtml(items) {
  const parts = items.map((item, i) => {
    const isLast = i === items.length - 1;
    return isLast || !item.href
      ? escapeHtml(item.name)
      : `<a href="${item.href}">${escapeHtml(item.name)}</a>`;
  });
  return `<nav class="breadcrumb">${parts.join(' &rsaquo; ')}</nav>`;
}

// The `<span class="chip">` badge row used on venue/category/guide pages —
// one chip per true boolean amenity flag on the venue. Identical output to
// what all three call sites built inline before this extraction.
// skipDogFriendly (2026-10-11): a venue on the official dog-beach list already
// shows the richer "🐾 Dog Friendly" collection badge (with its leash-rule
// tooltip), so the plain Dog-Friendly amenity chip is dropped beside it
// rather than showing the same fact twice.
// Keeps at most `max` chips on a listing card and folds the rest into one
// "+N more" chip (its title lists them); the venue page shows every badge.
// max 0 = no cap (unthemed cards keep their markup unchanged).
function capChips(html, max) {
  const chips = html.match(/<span class="chip[^"]*"[^>]*>.*?<\/span>/g) || [];
  if (!max || chips.length <= max) return html;
  const kept = chips.slice(0, max - 1);
  const rest = chips.slice(max - 1).map((c) => c.replace(/<[^>]+>/g, '').trim());
  return `${kept.join(' ')} <span class="chip chip-more" title="${escapeHtml(rest.join(', '))}">+${rest.length} more</span>`;
}

function badgeChipsHtml(venue, { skipDogFriendly = false } = {}) {
  return BOOL_FIELDS.filter((f) => venue[f] && !(skipDogFriendly && f === 'dog_friendly'))
    .map((f) => `<span class="chip">${escapeHtml(BADGE_LABELS[f].title)}</span>`)
    .join(' ');
}

// The `<li class="venue-card">` list-item used on category and guide
// pages. The two previous call sites differed only in whether the venue
// type itself appears in the meta line (guide pages, which mix
// categories, show it; category pages, which are already scoped to one
// category, don't) and in how defensively the name needs to be linked
// (guide pages tolerate a venue with no slug/category mapping yet by
// falling back to plain text; category pages always have both). Both
// behaviors are preserved exactly via the options below.
function venueCardHtml(venue, opts = {}) {
  // advisoryNote (2026-09-19): the venue's current temporary-condition
  // note from the 'advisory' collection, or undefined/null for none. When
  // absent nothing extra is rendered, so cards without an advisory are
  // byte-identical to before.
  // dogFriendlyNote (2026-09-19): undefined/null = not a member; a string
  // (possibly '') = member of the 'dog_friendly' collection, note = official restriction.
  // showRegion (2026-09-20): on the Okanagan-wide category listing the card
  // leads its meta line with the venue's own community (REGION_LABELS of
  // venue.region -- the same canonical value the venue page, breadcrumb
  // and URL use), so identically named venues in different communities
  // are distinguishable without opening them. Off by default, so every
  // other surface's card markup is unchanged.
  // dogNoteInline (2026-09-24): the Dog Friendly Finds hub renders the
  // official restriction that comes with a dog-beach membership as a VISIBLE
  // line on the card instead of leaving it in the badge's title= tooltip --
  // "off-leash only inside the fence" or "not on the swimming beach" is the
  // single most important thing on that card and a tooltip does not exist on
  // a phone. Off by default, so /beaches, /outdoors, region, category and
  // venue pages keep byte-identical markup.
  // showTypeLabel (2026-09-24): the Local Favourites page mixes every venue
  // type in one list, so its cards name the category ("Restaurant",
  // "Outdoor Destination") in the meta line. Off by default, so every other
  // surface's card markup is unchanged.
  const { showType = false, showTypeLabel = false, isHiddenGem = false, isLocalFavourite = false, advisoryNote = null, dogFriendlyNote = null, dogNoteInline = false, showRegion = false, themed = usesThemedCategoryLayout(venue.type), actions = themed, golfFeeHtml = '', appLabels = false, savedId = false, cardNotes = null, cardNoteLabel = 'Rainy day:', seasonTag = null, maxChips = 5, hideDogBadges = false, hideHiddenGemBadge = false, hideLocalFavouriteBadge = false } = opts;
  const catSlug = CATEGORY_SLUGS[venue.type];
  const href = (venue.slug && catSlug) ? `/${venue.region}/${catSlug}/${venue.slug}` : null;
  // Golf-only: the name stays the single link to the venue page, but it
  // becomes a block-level tap target carrying a small "View details"
  // cue (aria-hidden, so the accessible link name is still just the venue
  // name). Styled by the golf theme; every other category's title markup
  // is unchanged.
  const nameHtml = href
    ? (themed
      ? `<a class="venue-card-link" href="${href}"><span class="venue-card-name">${escapeHtml(venue.name)}</span><span class="venue-card-cue" aria-hidden="true">View details &rarr;</span></a>`
      : `<a href="${href}">${escapeHtml(venue.name)}</a>`)
    : escapeHtml(venue.name);
  const meta = [
    showRegion && REGION_LABELS[venue.region] ? escapeHtml(REGION_LABELS[venue.region]) : null,
    showType && venue.type ? escapeHtml(venue.type) : null,
    showTypeLabel && CATEGORY_LABELS[venue.type] ? escapeHtml(CATEGORY_LABELS[venue.type].singular) : null,
    venue.cuisine ? escapeHtml(venue.cuisine) : null,
    venue.rating ? `${venue.rating}\u2605` : null,
  ].filter(Boolean).join(' &middot; ');
  // Golf-only (2026-09-19): the description is wrapped so the page script
  // can clamp it to ~4 lines and toggle it inline; the button ships hidden
  // and is revealed only when the text is actually truncated. Every other
  // category renders exactly what it did before.
  // `isGolf` now means "uses the themed (Golf-style) card": Golf and, since
  // 2026-09-19, Beaches (THEMED_CATEGORY_TYPES). Golf output is unchanged.
  const isGolf = themed;
  const descId = `golf-desc-${venue.id}`;
  const descEn = opts.excerpt ? descExcerpt(venue.description) : venue.description;
  const descFr = opts.excerpt && venue.description_fr ? descExcerpt(venue.description_fr) : venue.description_fr;
  const desc = !venue.description ? '' : isGolf
    ? `<div class="golf-desc" id="${descId}"><p>${bilingualDescHtml(descEn, descFr)}</p></div>
        <button type="button" class="desc-toggle" aria-expanded="false" aria-controls="${descId}" hidden>Read more &rarr;</button>`
    : `<p>${bilingualDescHtml(descEn, descFr)}</p>`;
  // Emitted for themed cards and for ENGAGEMENT_ONLY_TYPES cards alike: the
  // shared engagement script locates a card by data-venue-category, so an
  // unthemed card carrying the controls needs these attributes too. They are
  // data attributes only -- no themed CSS rule matches a non-golf category.
  // savedId (Stage 4.3): a card whose Favorite button app.js adds client-side
  // (guide pages) carries just its venue id, for the saved-item capture
  // script -- no category, so no engagement script or themed rule binds to it.
  const liAttrs = (isGolf || actions)
    ? ` data-venue-id="${venue.id}" data-venue-region="${escapeHtml(venue.region)}" data-venue-category="${escapeHtml(venue.type)}" data-venue-name="${escapeHtml(venue.name)}" data-surface="category_card"`
    : (savedId ? ` data-venue-id="${venue.id}"` : '');
  // Golf-only (2026-09-19): the listing card's only actions are Favorite
  // and Add to Trip (golfFavTripButtonsHtml). Website / phone / directions
  // live on the venue page instead -- the data is untouched, only where it
  // is shown. Rendered inline after the chips line, so non-Golf cards stay
  // byte-identical to their pre-feature markup (no stray blank line).
  const cardActions = actions
    ? `
        <div class="card-actions">
          ${golfFavTripButtonsHtml(venue, { appLabels })}
        </div>`
    : '';
  // Defensive: never show the badge for a retired/redirected venue, even
  // if a caller ever passed isHiddenGem=true for one by mistake — the
  // bulk/targeted lookups already exclude these, but this keeps the
  // guarantee local to the render function itself, not just its callers.
  // hideHiddenGemBadge / hideLocalFavouriteBadge (2026-10-14): /secret-spots
  // and /local-favorites leave off the badge every card on them would carry.
  const showBadge = isHiddenGem && !venue.redirect_to && !hideHiddenGemBadge;
  const showLocalFavourite = isLocalFavourite && !venue.redirect_to && !hideLocalFavouriteBadge;
  const showDogFriendly = dogFriendlyNote !== null && dogFriendlyNote !== undefined && !venue.redirect_to;
  const editorialChips = (showBadge ? hiddenGemBadgeHtml() + ' ' : '') + (showLocalFavourite ? localFavouriteBadgeHtml() + ' ' : '') + (showDogFriendly && !hideDogBadges ? dogFriendlyBadgeHtml(dogFriendlyNote) + ' ' : '');
  const dogNoteHtml = (dogNoteInline && showDogFriendly && String(dogFriendlyNote || '').trim())
    ? `\n        <p class="dog-note"><span class="dog-note-label">Dogs:</span> ${escapeHtml(String(dogFriendlyNote).trim())}</p>`
    : '';
  // cardNotes (2026-10-11): an optional Map of venue id -> a short visible
  // line, used by the /indoor hub's "Also good on a rainy day" section to say
  // why an arena or a brewery is there ("Indoor ice: public skating"). No map,
  // or no entry for this venue, renders nothing, so every other card is
  // byte-identical. cardNoteLabel (2026-10-11) names the line: 'Rainy day:'
  // by default, 'Experience:' on the /tours hub's "More experiences to book".
  const cardNote = cardNotes && cardNotes.get(venue.id) ? String(cardNotes.get(venue.id)).trim() : '';
  const cardNoteHtml = cardNote ? `\n        <p class="card-note"><span class="card-note-label">${escapeHtml(cardNoteLabel)}</span> ${escapeHtml(cardNote)}</p>` : '';
  const advisoryHtml = (advisoryNote !== null && advisoryNote !== undefined && !venue.redirect_to)
    ? `\n        ${seasonTag ? seasonTagHtml(seasonTag) : advisoryNoticeHtml(advisoryNote)}`
    : '';
  const chipsHtml = `<p class="chips">${capChips(editorialChips + badgeChipsHtml(venue, { skipDogFriendly: showDogFriendly || hideDogBadges }), themed ? maxChips : 0)}</p>`;
  // Themed listing cards (2026-10-12) always have the same eight parts in the
  // same order -- name, meta, fee slot, description slot, notice slot, notes
  // slot, badges, buttons -- with empty slots rendered as empty elements, so
  // the grid can line each part up across a row (CSS subgrid). A slot only
  // takes space when a card in that row fills it.
  if (themed) {
    return `
      <li class="venue-card"${liAttrs}>
        <h2>${nameHtml}</h2>
        <p class="venue-meta">${meta}</p>
        <div class="card-slot card-slot-fee">${golfFeeHtml ? '\n        ' + golfFeeHtml + '\n        ' : ''}</div>
        <div class="card-slot card-slot-desc">${desc ? '\n        ' + desc + '\n        ' : ''}</div>
        <div class="card-slot card-slot-notice">${advisoryHtml ? advisoryHtml + '\n        ' : ''}</div>
        <div class="card-slot card-slot-notes">${dogNoteHtml || cardNoteHtml ? dogNoteHtml + cardNoteHtml + '\n        ' : ''}</div>
        ${chipsHtml}${cardActions || '\n        <div class="card-actions card-actions-empty"></div>'}
      </li>`;
  }
  return `
      <li class="venue-card"${liAttrs}>
        <h2>${nameHtml}</h2>
        <p class="venue-meta">${meta}</p>${golfFeeHtml ? '\n        ' + golfFeeHtml : ''}
        ${desc}${advisoryHtml}${dogNoteHtml}${cardNoteHtml}
        ${chipsHtml}${cardActions}
      </li>`;
}

// GET /:region — region hub page
// Town page structured data (2026-10-13): the town as a TouristDestination in the Okanagan Valley, and an ItemList of the
// category pages it links to that have listings (a summary-page list: each item is its own page). Filtered views (query-string
// links such as Dog Friendly or What's On) are left out, since their canonical is another page.
function regionPageSchemas(region, regionLabel, description, canonical, categories) {
  const items = categories.filter((c) => c.href && c.count > 0 && !c.href.includes('?'));
  const destination = {
    '@context': 'https://schema.org',
    '@type': 'TouristDestination',
    name: `${regionLabel}, BC`,
    description,
    url: canonical,
    containedInPlace: { '@type': 'Place', name: 'Okanagan Valley, British Columbia' },
  };
  const list = items.length ? {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: `Things to do in ${regionLabel}`,
    url: canonical,
    numberOfItems: items.length,
    itemListElement: items.map((c, i) => ({ '@type': 'ListItem', position: i + 1, name: `${c.label} in ${regionLabel}`, url: `https://okanaganroam.com${c.href}` })),
  } : null;
  return [destination, list].filter(Boolean);
}

// Region page photos and cards (2026-10-14). Every town page opens with its
// own photo: the wide region photo where there is one, the ski photos for the
// resorts, otherwise the town's /destinations photo (800px, so it gets a
// shorter banner). Below the guide, "Places to start" shows the places the
// guide itself names as photo cards -- the guide's own picks, never a paid or
// ranked slot -- and the categories become one photo grid with the empty
// ones left out.
function regionBannerPhoto(region) {
  const label = REGION_LABELS[region];
  if (region === 'big-white') return { src: '/images/ski-snow/big-white-sunset.jpg', alt: 'Sunset over snow-covered firs and mountain ridges at Big White', pos: 55, small: false };
  if (SKI_RESORT_REGIONS.has(region)) return { src: SKI_SNOW_BANNER.src, alt: SKI_SNOW_BANNER.alt, pos: SKI_SNOW_BANNER.pos, small: false };
  if (REGION_SHARE_IMAGES[region]) return { src: REGION_SHARE_IMAGES[region], alt: `${label} in the Okanagan Valley`, pos: 50, small: false };
  const card = destinationCardPhoto(region);
  return card && !card.map ? { src: card.src, alt: `${label} in the Okanagan Valley`, pos: 50, small: true } : null;
}
function regionBannerHtml(region) {
  const b = regionBannerPhoto(region);
  if (!b) return '';
  return `<div class="category-banner${b.small ? ' region-banner-small' : ''}"><img src="${b.src}" alt="${escapeHtml(b.alt)}" width="${b.small ? 800 : 1600}" height="${b.small ? 533 : 667}" style="object-position: 50% ${b.pos}%" fetchpriority="high"></div>`;
}
// Ski hills are named as resorts ("Big White Ski Resort"), towns as "Kelowna, BC".
function regionHeading(region) {
  const ski = SKI_RESORT_REGIONS.has(region) && SKI_SNOW_REGION_CONTENT[region];
  return ski ? ski.heading : `${REGION_LABELS[region]}, BC`;
}
// The URL of a card's example photo key ("cafe-1", "noodle", "indoorall-0").
function cardPhotoKeyUrl(key) {
  if (key === 'noodle') return '/images/trip-v3/stops/stop-restaurant-noodle-480.jpg';
  const m = /^([a-z]+)-(\d+|dog)$/.exec(key || '');
  if (!m) return null;
  if (m[2] === 'dog') return FD_CARD_DOG_PHOTOS[m[1]] || null;
  return (FD_CARD_PHOTOS[m[1]] || [])[Number(m[2])] || null;
}
function regionStartVenues(region, max = 6) {
  const intro = REGION_INTROS[region];
  if (!intro) return [];
  const html = intro.paragraphs.map((p) => p[1]).join(' ');
  const seen = new Set(), out = [];
  const find = db.prepare('SELECT * FROM venues WHERE region = ? AND slug = ? AND redirect_to IS NULL');
  for (const m of html.matchAll(/href="\/([a-z-]+)\/([a-z-]+)\/([a-z0-9-]+)"/g)) {
    const [, r, catSlug, slug] = m;
    if (r !== region || !SLUG_TO_TYPE[catSlug] || seen.has(slug)) continue;
    seen.add(slug);
    const row = find.get(r, slug);
    if (row) out.push(rowToVenue(row));
    if (out.length >= max) break;
  }
  return out;
}
function regionPlacesToStartHtml(region) {
  const venues = regionStartVenues(region);
  if (venues.length < 3) return '';
  const cards = venues.map((v) => {
    const own = String(v.image_url || '').trim();
    // Ski hills: their trails, tube parks and tours get winter photos.
    const set = SKI_RESORT_REGIONS.has(region) && ['outdoor', 'tour', 'sport', 'beach'].includes(v.type) ? 'winter' : null;
    const src = /^(?:https:\/\/|\/images\/)[^'"()\s<>]+$/.test(own) ? own : cardPhotoKeyUrl(curatedPhotoKey(v, set));
    const type = CATEGORY_LABELS[v.type] ? CATEGORY_LABELS[v.type].singular : '';
    return `
      <li class="category-card region-start-card">
        <h3><a href="/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}">${escapeHtml(v.name)}</a></h3>
        <p class="venue-meta">${escapeHtml(type)}</p>${src ? `
        <div class="region-card-photo"><img src="${escapeHtml(src)}" alt="" width="480" height="320" loading="lazy" decoding="async"></div>` : ''}
      </li>`;
  }).join('');
  return `<section class="region-start" aria-labelledby="regionStartHeading">
  <h2 class="category-subsection-heading" id="regionStartHeading">Places to start in ${escapeHtml(REGION_LABELS[region])}</h2>
  <ul class="card-grid region-photo-grid">${cards}
  </ul>
  </section>`;
}
const REGION_DISCOVERY_IMAGES = Object.freeze({
  'whats-on': '/images/whats-on/thumbs/whats-on.jpg',
  'dog-friendly': '/images/dog-friendly/thumbs/dog-friendly.jpg',
  'local-favourites': '/images/local-favourites/thumbs/local-favourites.jpg',
  'hidden-gems': '/images/hidden-gems-banner/thumbs/hidden-gems.jpg',
});
function regionCategoryImage(c) {
  if (c.type && CATEGORY_BANNER_IMAGES[c.type]) return categoryCardImage(CATEGORY_BANNER_IMAGES[c.type]).src;
  return REGION_DISCOVERY_IMAGES[c.key] || null;
}
// The categories as photo cards, grouped as before, with empty categories
// (and a group left with none) not shown at all.
function regionCategoryGridHtml(region, categories) {
  const label = REGION_LABELS[region];
  const byKey = new Map(categories.map((c) => [c.key, c]));
  // A small place (six categories or fewer) gets one grid, not three short rows.
  const groups = categories.filter((c) => c.href).length <= 6
    ? [{ label: `Explore ${label}`, keys: DESTINATION_CATEGORY_ORDER }]
    : DESTINATION_CATEGORY_GROUPS;
  return groups.map((g) => {
    const live = g.keys.map((k) => byKey.get(k)).filter((c) => c && c.href);
    if (!live.length) return '';
    return `<h2 class="category-subsection-heading">${escapeHtml(g.label === 'Discovery' ? 'More ways to explore' : g.label)}</h2>
  <ul class="card-grid region-photo-grid">
    ${live.map((c) => {
      const img = regionCategoryImage(c);
      return `
      <li class="category-card">
        <h3><a href="${escapeHtml(c.href)}">${escapeHtml(c.label)}</a></h3>
        <p class="venue-meta">${c.count} ${escapeHtml(c.count === 1 ? c.nounOne : c.nounMany)} in ${escapeHtml(label)}</p>${img ? `
        <div class="region-card-photo"><img src="${img}" alt="" width="480" height="320" loading="lazy" decoding="async"></div>` : ''}
      </li>`;
    }).join('\n')}
  </ul>`;
  }).filter(Boolean).join('\n  ');
}
const REGION_PAGE_STYLE = `<style id="region-page">
  body.region-page .region-banner-small { max-height: min(34vh, 300px); }
  @media (min-width: 900px) { body.region-page .region-banner-small { aspect-ratio: 3 / 1; } }
  body.region-page .region-category-tabs { margin: 0 0 22px; }
  body.region-page .region-start { margin: 6px 0 8px; }
  body.region-page .region-photo-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin: 0 0 28px; padding: 0; }
  @media (min-width: 900px) { body.region-page .region-photo-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 18px; } }
  body.region-page .region-photo-grid .category-card { position: relative; display: flex; flex-direction: column; margin: 0; padding: 0 0 12px; overflow: hidden; border-radius: 14px; }
  body.region-page .region-photo-grid .category-card:hover { transform: translateY(-3px); box-shadow: 0 18px 32px -22px rgba(74,52,40,0.55); }
  body.region-page .region-photo-grid .region-card-photo { order: -1; aspect-ratio: 3 / 2; overflow: hidden; background: #2A6B67; margin-bottom: 10px; }
  body.region-page .region-photo-grid .region-card-photo img { width: 100%; height: 100%; object-fit: cover; display: block; transition: transform 0.35s ease; }
  body.region-page .region-photo-grid .category-card:hover .region-card-photo img { transform: scale(1.04); }
  body.region-page .region-photo-grid h3 { font-family: 'Fraunces', serif; font-weight: 600; font-size: 1.02rem; line-height: 1.25; margin: 0 12px 3px; }
  body.region-page .region-photo-grid h3 a { color: var(--ink); text-decoration: none; }
  body.region-page .region-photo-grid h3 a::after { content: ''; position: absolute; inset: 0; }
  body.region-page .region-photo-grid h3 a:focus-visible { outline: none; }
  body.region-page .region-photo-grid .category-card:focus-within { outline: 2px solid var(--teal-deep); outline-offset: 2px; }
  body.region-page .region-photo-grid .venue-meta { margin: 0 12px; font-size: 0.82rem; }
  body.region-page .region-more { margin: 24px 0 8px; font-weight: 700; }
  /* Wide screens (2026-10-14): the guide on the left, Places to start beside
     it in two columns, instead of the guide alone in the left half. */
  @media (min-width: 1100px) {
    body.region-page .region-lead-split { display: grid; grid-template-columns: minmax(0, 64ch) minmax(0, 1fr); gap: 40px; align-items: start; }
    body.region-page .region-lead-split .region-start { margin-top: 2px; position: sticky; top: 96px; }
    body.region-page .region-lead-split .region-start .category-subsection-heading { margin-top: 0; }
    body.region-page .region-lead-split .region-start .region-photo-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; margin-bottom: 0; }
    body.region-page .region-lead-split .region-intro { max-width: none; }
  }
</style>`;
function renderRegionPage(region, categoryCounts, regionGuidePages) {
  const regionLabel = REGION_LABELS[region];
  const totalVenues = Object.values(categoryCounts).reduce((a, b) => a + b, 0);
  // Ski resorts (SEO audit, 2026-10-10): the generic "Wineries ... golf
  // courses" wording doesn't match what people search for on a ski hill.
  const isSkiResort = SKI_RESORT_REGIONS.has(region);
  const intro = REGION_INTROS[region];
  const title = intro && intro.titleTail
    ? `Things to Do in ${regionLabel}: ${intro.titleTail} | Okanagan Roam`
    : isSkiResort
      ? `${regionLabel} Restaurants, Bars & Après-Ski, BC | Okanagan Roam`
      : `${regionLabel} Restaurants, Wineries & More, BC | Okanagan Roam`;
  const description = intro && intro.describe
    ? intro.describe(totalVenues)
    : isSkiResort
      ? `${totalVenues} verified spots at ${regionLabel}, BC: restaurants, bars, cafés and après-ski, all reviewed and badge-checked by Okanagan Roam.`
      : `${totalVenues} verified venues in ${regionLabel}, BC — restaurants, wineries, breweries, golf courses, and more, all reviewed and badge-checked by Okanagan Roam.`;
  const canonical = `https://okanaganroam.com/${region}`;
  // Ski resorts share the real ski photos (SEO, 2026-10-13): Big White its
  // sunset, the others the Ski & Snow skier.
  const shareImage = isSkiResort ? (region === 'big-white' ? '/images/ski-snow/big-white-sunset.jpg' : SKI_SNOW_BANNER.src) : (REGION_SHARE_IMAGES[region] || null);

  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: regionLabel, url: canonical },
  ]);

  const categories = destinationCategories(region, categoryCounts);
  // Distinct places: a sports_also brewery is one place, though it shows
  // under both Breweries and Sports.
  const placeCount = totalVenues;
  const categorySections = regionCategoryGridHtml(region, categories);
  const startHtml = regionPlacesToStartHtml(region);
  // H1 Step 2 (2026-09-22): a short "Upcoming events in {Region}" block, built
  // from the same live predicate as the sitemap and the event-page block, so
  // links vanish by themselves as events expire. Direct canonical event URLs
  // only; the filtered What's On view is the secondary "see all" link. Reuses
  // the .related-section/.related-grid/.related-card styles this page already
  // loads, so no new CSS. Renders nothing for a region below the threshold.
  const upcomingEvents = listUpcomingEventsForRegion(region, { limit: 3 });
  const eventLinks = upcomingEvents.length
    ? `<div class="related-section">
        <h2>Upcoming events in ${escapeHtml(regionLabel)}</h2>
        <div class="related-grid">
${upcomingEvents.map((e) => {
      const when = upcomingEventDateLabel(e.nextDate, e.nextEndDate);
      const cat = e.primaryCategory && WHATSON_CATEGORY_BY_KEY[e.primaryCategory] ? WHATSON_CATEGORY_BY_KEY[e.primaryCategory].label : '';
      const meta = [when, cat].filter(Boolean).map(escapeHtml).join(' &middot; ');
      return `          <div class="related-card"><a href="/${e.region}/events/${e.slug}">${escapeHtml(e.name)}</a>${meta ? `<p class="related-meta">${meta}</p>` : ''}</div>`;
    }).join('\n')}
        </div>
        <p><a href="/${encodeURIComponent(region)}/events">See what&rsquo;s on in ${escapeHtml(regionLabel)} &rarr;</a></p>
      </div>`
    : '';

  const guideLinks = regionGuidePages.length
    ? `<div class="related-section">
        <h2>Browse ${escapeHtml(regionLabel)} by what matters to you</h2>
        <p>${regionGuidePages
          .map((c) => `<a href="/guide/${c.region}/${c.badge}">${escapeHtml(BADGE_LABELS[c.badge].title)} (${c.count})</a>`)
          .join(', ')}</p>
      </div>`
    : '';

  // Destination mini-directory (2026-09-25): the same themed shell as
  // /food-drink and /local-favorites (homepage header, Trip tray, footer),
  // with the destination's categories as pill tabs above the existing
  // category cards. Every tab and card is a category with at least one
  // active venue, linking to its /{region}/{category} page.
  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, ...regionPageSchemas(region, regionLabel, description, canonical, categories)], { golfTheme: true, shareImage })}
${renderOutdoorThemeStyles()}
${renderDestinationCategoryStyles()}
${intro ? REGION_INTRO_STYLE : ''}
${CATEGORY_BANNER_STYLE}
${REGION_PAGE_STYLE}
${golfEngagementHeadHtml('fd', true, 'region')}
</head>
<body class="golf-page outdoor-page region-page">
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([
    { name: 'Home', href: '/' },
    { name: regionLabel },
  ])}
  ${categoryHeroHtml(regionBannerHtml(region), `<h1>${escapeHtml(regionHeading(region))}</h1>
  <p class="subtitle">${placeCount} place${placeCount === 1 ? '' : 's'} to eat, drink and explore in ${escapeHtml(regionLabel)}</p>`)}
  ${regionCategoryTabsHtml(region, categoryCounts, null, categories.filter((c) => c.href))}
  <div class="region-lead${intro && startHtml ? ' region-lead-split' : ''}">
  <div class="region-lead-text">
  ${intro ? `${regionIntroHtml(region)}\n  ` : ''}${SKI_GUIDE.resorts.some((r) => r.region === region) ? `<p class="subtitle"><a href="${SKI_GUIDE_PATH}#${region}">Read our ski season guide: where to eat, drink and play this winter &rarr;</a></p>\n  ` : ''}</div>
  ${startHtml}
  </div>
  ${categorySections}
  ${eventLinks ? `${eventLinks}\n  ` : ''}${guideLinks}
  <p class="region-more"><a href="/destinations">See all Okanagan destinations &rarr;</a></p>
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
</body>
</html>`;
}

// Destination categories (2026-09-25): every destination page lists the
// same 14 categories in one fixed order -- Food & Drink, then Experiences,
// then Discovery. A category with results links to the page that shows
// exactly them; a category with none stays visible but is not a link, so a
// visitor is never sent to a page we know is empty. Counts come only from
// existing data:
//   venue types      -> active venues of that primary type (the same count
//                       and the same /{region}/{category} page as before)
//   What's On        -> the destination page's own upcoming-events rule
//                       (listUpcomingEventsForRegion, incl. its minimum),
//                       linked to What's On over the next year so every
//                       counted event is on the page
//   Dog-Friendly     -> the /dog-friendly hub list for the region
//   Local Favourites -> the local_favorite collection for the region
//   Hidden Gems      -> the hidden_gem collection for the region
const DESTINATION_CATEGORY_GROUPS = [
  { label: 'Food & Drink', keys: ['restaurant', 'cafe', 'pub', 'winery', 'brewery', 'distillery', 'cocktail'] },
  { label: 'Experiences', keys: ['golf', 'beach', 'outdoor', 'indoor', 'tour', 'sport'] },
  { label: 'Discovery', keys: ['whats-on', 'dog-friendly', 'local-favourites', 'hidden-gems'] },
];
const DESTINATION_CATEGORY_ORDER = DESTINATION_CATEGORY_GROUPS.flatMap((g) => g.keys);
const DESTINATION_DISCOVERY_LABELS = {
  'whats-on': { plural: 'What\u2019s On', nounOne: 'upcoming event', nounMany: 'upcoming events' },
  'dog-friendly': { plural: 'Dog-Friendly Finds', nounOne: 'dog-friendly find', nounMany: 'dog-friendly finds' },
  'local-favourites': { plural: 'Local Favourites', nounOne: 'local favourite', nounMany: 'local favourites' },
  'hidden-gems': { plural: 'Hidden Gems', nounOne: 'hidden gem', nounMany: 'hidden gems' },
};

// Batch A (2026-09-27, P-003): counts for the destination tabs and the
// /categories directory, which only ever needed a number but loaded whole
// venue / event lists (with per-row enrichment) to take .length. Each
// function below is the COUNT(*) form of the list function named beside it,
// with exactly the same WHERE clause and filters, and an optional region
// (the old callers filtered the full list by v.region === region). The list
// functions themselves are unchanged for their other callers.
function countVenueRows(where, params, region) {
  const regionClause = region == null ? '' : ' AND v.region = ?';
  return db.prepare(`SELECT COUNT(*) AS n FROM venues v WHERE ${where}${regionClause}`)
    .get(...params, ...(region == null ? [] : [region])).n;
}
// = listUpcomingEventsForRegion(region, { limit: MAX }).length (same
// predicate; that function returns [] below MIN_REGION_EVENTS).
function countUpcomingEventsForRegion(region, now = new Date()) {
  const today = todayLocal(now);
  const n = db.prepare(`SELECT COUNT(*) AS n FROM events e
      WHERE e.region = ?
        AND e.status = 'scheduled'
        AND EXISTS (SELECT 1 FROM event_occurrences o WHERE o.event_id = e.id AND o.status = 'scheduled')
        AND ${ACTIVE_EVENT_DATE_SQL.replace(/\bend_datetime\b/, 'e.end_datetime').replace(/\bstart_datetime\b/, 'e.start_datetime')}`)
    .get(region, today).n;
  return n < MIN_REGION_EVENTS ? 0 : n;
}
// = getDogFriendlyHubVenues()
function countDogFriendlyHubVenues(region = null) {
  return countVenueRows(`v.redirect_to IS NULL AND (
      v.dog_friendly = 1
      OR EXISTS (
        SELECT 1 FROM collection_items ci
        JOIN collections c ON c.id = ci.collection_id
        WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = ?
      )
    )`, [DOG_FRIENDLY_COLLECTION_KIND], region);
}
// = getLocalFavouriteVenues()
function countLocalFavouriteVenues(region = null) {
  return countVenueRows(`v.redirect_to IS NULL AND EXISTS (
      SELECT 1 FROM collection_items ci
      JOIN collections c ON c.id = ci.collection_id
      WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = 'local_favorite'
    )`, [], region);
}
// = getHiddenGemCollectionVenues() (no feature): hidden_gem members, not
// redirected, whose region and type are known (REGION_LABELS / CATEGORY_SLUGS).
function countHiddenGemCollectionVenues(region = null) {
  const regions = Object.keys(REGION_LABELS), types = Object.keys(CATEGORY_SLUGS);
  return countVenueRows(`v.redirect_to IS NULL
      AND v.region IN (${regions.map(() => '?').join(', ')})
      AND v.type IN (${types.map(() => '?').join(', ')})
      AND EXISTS (
        SELECT 1 FROM collection_items ci
        JOIN collections c ON c.id = ci.collection_id
        WHERE c.kind = 'hidden_gem' AND ci.content_type = 'venue' AND ci.content_id = v.id
      )`, [...regions, ...types], region);
}
// = getSecretSpotVenues()
function countSecretSpotVenues() {
  return countVenueRows(`v.redirect_to IS NULL AND v.type IN (${SECRET_SPOT_TYPES.map(() => '?').join(', ')}) AND EXISTS (
      SELECT 1 FROM collection_items ci
      JOIN collections c ON c.id = ci.collection_id
      WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = 'hidden_gem'
    )`, [...SECRET_SPOT_TYPES], null);
}
// = getFoodDrinkHubVenues()
function countFoodDrinkHubVenues() {
  return countVenueRows(`v.redirect_to IS NULL AND (
      v.type IN (${FOOD_DRINK_TYPES.map(() => '?').join(', ')})
      OR EXISTS (
        SELECT 1 FROM collection_items ci
        JOIN collections c ON c.id = ci.collection_id
        WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind IN (${FD_CATEGORY_COLLECTION_KINDS.map(() => '?').join(', ')})
      )
    )`, [...FOOD_DRINK_TYPES, ...FD_CATEGORY_COLLECTION_KINDS], null);
}
// = getVenuesByCategory(type)
function countVenuesByCategory(type) {
  return countVenueRows('v.type = ? AND v.redirect_to IS NULL', [type], null);
}
// = getOutdoorLandingVenues()
function countOutdoorLandingVenues() {
  const liveKinds = listLiveOutdoorActivities().map((a) => a.kind);
  const others = OUTDOOR_ACTIVITY_VENUE_TYPES.filter((t) => t !== 'outdoor');
  if (!liveKinds.length || !others.length) return countVenuesByCategory('outdoor');
  return countVenueRows(`v.redirect_to IS NULL AND (
      v.type = 'outdoor'
      OR (v.type IN (${others.map(() => '?').join(', ')}) AND v.id IN (
        SELECT ci.content_id FROM collection_items ci
        JOIN collections c ON c.id = ci.collection_id
        WHERE ci.content_type = 'venue' AND c.kind IN (${liveKinds.map(() => '?').join(', ')})
      ))
    )`, [...others, ...liveKinds], null);
}

function destinationCategories(region, categoryCounts, now = new Date()) {
  const discovery = {
    'whats-on': {
      count: countUpcomingEventsForRegion(region, now),
      // The region's own events page (2026-10-14), so the link carries no
      // dates that go stale in a cached copy.
      href: `/${encodeURIComponent(region)}/events`,
    },
    'dog-friendly': { count: countDogFriendlyHubVenues(region), href: `/dog-friendly?regions=${encodeURIComponent(region)}` },
    'local-favourites': { count: countLocalFavouriteVenues(region), href: `/local-favorites?regions=${encodeURIComponent(region)}` },
    'hidden-gems': { count: countHiddenGemCollectionVenues(region), href: `/hidden-gems?regions=${encodeURIComponent(region)}` },
  };
  return DESTINATION_CATEGORY_ORDER.map((key) => {
    if (CATEGORY_SLUGS[key]) {
      // Sports (2026-10-14): /:region/sports also lists the region's
      // sports_also venues, so its count does too.
      const also = key === 'sport' ? getSportsAlsoVenues().filter((v) => v.region === region && v.type !== 'sport').length : 0;
      const count = (categoryCounts[key] || 0) + also;
      const l = CATEGORY_LABELS[key];
      return { key, type: key, label: l.plural, nounOne: l.singular.toLowerCase(), nounMany: l.plural.toLowerCase(), count, href: count >= MIN_CATEGORY_VENUES || also > 0 ? `/${region}/${CATEGORY_SLUGS[key]}` : null };
    }
    const l = DESTINATION_DISCOVERY_LABELS[key];
    const d = discovery[key];
    return { key, type: null, label: l.plural, nounOne: l.nounOne, nounMany: l.nounMany, count: d.count, href: d.count > 0 ? d.href : null };
  });
}
// The destination's category tabs: the existing pill selector
// (.category-region-selector, the same control the Okanagan-wide category
// pages and Outdoors use) with every category's count, in the fixed order.
// On a destination category page the current category is the static active
// pill; an empty category is a non-link pill marked aria-disabled.
function regionCategoryTabsHtml(region, categoryCounts, currentType, categories = null) {
  const cats = categories || destinationCategories(region, categoryCounts);
  const pills = cats.map((c) => {
    const label = escapeHtml(c.label);
    const count = `<span class="outdoor-activity-count">${c.count}</span>`;
    if (c.type && c.type === currentType) return `<span class="category-region-selector-active" aria-current="page">${label}${count}</span>`;
    if (!c.href) return `<span class="category-region-selector-empty" aria-disabled="true" title="None listed in ${escapeHtml(REGION_LABELS[region])} yet">${label}${count}</span>`;
    return `<a href="${escapeHtml(c.href)}">${label}${count}</a>`;
  }).join('\n      ');
  return `<nav class="category-region-selector region-category-tabs" aria-label="${escapeHtml(REGION_LABELS[region])} categories">
      ${pills}
    </nav>`;
}
// ---------- /destinations (2026-09-25) ----------
// "Choose Your Okanagan Destination": every destination whose /{region}
// page renders, exactly once, grouped by the site's existing
// FOOTER_REGION_GROUPS (Central / South / North / Ski resorts, then any
// region not in a group). Each card links to the region's existing page.
// Same shell and card styles as the destination pages; no search, no
// filters, no venue listings.
function destinationRegionEntries() {
  const entries = [];
  const placed = new Set();
  const groups = FOOTER_REGION_GROUPS.map((g) => ({ label: g.label, regions: g.regions.filter((r) => REGION_LABELS[r]) }));
  groups.forEach((g) => g.regions.forEach((r) => placed.add(r)));
  const other = Object.keys(REGION_LABELS).filter((r) => !placed.has(r));
  if (other.length) groups.push({ label: 'Other', regions: other });
  for (const g of groups) {
    const regions = g.regions.map((r) => {
      const counts = getRegionCategoryCounts(r);
      return { region: r, label: REGION_LABELS[r], venues: Object.values(counts).reduce((a, b) => a + b, 0), categories: Object.keys(counts).length };
    }).filter((x) => x.categories > 0);
    if (regions.length) entries.push({ label: g.label, regions });
  }
  return entries;
}
// Destination photos (2026-10-13): each /destinations card shows its town's photo, 3:2 (up to 800x533), from
