  const tourActivity = type === 'tour' && TOUR_ACTIVITIES.some((a) => a.slug === opts.tourActivity) ? opts.tourActivity : '';
  const tourUniverse = type === 'tour' ? [...venues, ...(opts.toursAlso || [])] : [];
