function renderFoodDrinkScopedPage(venues, filter, scope) {
  const { region, type, categoryCounts, categoryGuidePages = [] } = scope;
  // Valley-wide type pages (SEO, 2026-10-13): with no region, the same page
  // renders /restaurants, /cafes, /pubs, /cocktail-lounges, /breweries and
  // /distilleries -- the type's heading, intro and photo, region links down
  // to /<region>/<type>, breadcrumb Home > Food & Drink > <type>.
  const valleyWide = !region;
  const regionLabel = valleyWide ? null : REGION_LABELS[region];
  const catSlug = CATEGORY_SLUGS[type];
  const label = CATEGORY_LABELS[type];
  const valleyText = FD_HUB_HEADINGS[type];
  const path = valleyWide ? `/${catSlug}` : `/${region}/${catSlug}`;

  // Only primary type counts: every card answers to this page's category.
  const catsById = new Map(venues.map((v) => [v.id, [v.type]]));
  const featsById = foodDrinkFeaturesByVenue(venues);
  // Features offered = the ones at least one venue here actually has.
  const present = new Set();
  for (const feats of featsById.values()) for (const k of feats) present.add(k);
  const scopeFeatures = FD_HUB_FEATURES.map((x) => x.key).filter((k) => present.has(k));
  const q = filter || { features: [] };
  const f = { types: [], regions: [], features: (q.features || []).filter((k) => present.has(k)) };
  const matching = filterFoodDrinkVenues(venues, f, catsById, featsById);
  const matchIds = new Set(matching.map((v) => v.id));
  const counts = foodDrinkChipCounts(venues, f, catsById, featsById);
  const filtered = f.features.length > 0;
  const state = { types: [], features: f.features, regions: [], counts };

  const title = valleyWide ? `${valleyText.heading} | Okanagan Roam` : `${label.plural} in ${regionLabel}, BC | Okanagan Roam`;
  const description = valleyWide ? valleyText.intro : venues.length === 0
    ? `No ${label.plural.toLowerCase()} are currently listed in ${regionLabel}, BC. Browse everything else Okanagan Roam covers in ${regionLabel}.`
    : `${venues.length} verified ${label.plural.toLowerCase()} in ${regionLabel}, BC — real listings with hours, ratings, and attributes, reviewed and badge-checked by Okanagan Roam.`;
  const canonical = `https://okanaganroam.com${path}`;
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    valleyWide ? { name: 'Food & Drink', url: 'https://okanaganroam.com/food-drink' } : { name: regionLabel, url: `https://okanaganroam.com/${region}` },
    { name: label.plural, url: canonical },
  ]);
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: title,
    description,
    itemListElement: venues.map((v, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      url: `https://okanaganroam.com/${v.region}/${catSlug}/${v.slug}`,
      item: {
        '@type': SCHEMA_TYPE_MAP[v.type] || 'LocalBusiness',
        name: v.name,
      },
    })),
  };
  const payload = {};
  for (const v of venues) payload[String(v.id)] = { c: catsById.get(v.id) || [], f: featsById.get(v.id) || [], r: v.region, k: descSearchWords(v.description) };

  const advisoryNotes = getAdvisoryNotes();
  const cardsHtml = venues.length ? foodDrinkBatchedCardsHtml(venues, matchIds, matching.length, advisoryNotes, false) : '';
  const emptyHtml = venues.length === 0
    ? `<p class="fd-no-results" id="fdNoResults">No ${escapeHtml(label.plural.toLowerCase())} are listed in ${escapeHtml(regionLabel || 'the Okanagan')} right now.</p>`
    : `<p class="fd-no-results" id="fdNoResults"${matching.length === 0 ? '' : ' hidden'}>No ${escapeHtml(label.plural.toLowerCase())} here match that combination yet. <a href="${path}" id="fdNoResultsClear">Clear the filters</a> to see all of them.</p>`;
  const guideLinks = categoryGuidePages.length
    ? `<div class="related-section">
        <h2>Filter ${escapeHtml(label.plural)} in ${escapeHtml(regionLabel)}</h2>
        <p>${categoryGuidePages
          .map((c) => `<a href="/guide/${c.region}/${c.badge}">${escapeHtml(BADGE_LABELS[c.badge].title)}</a>`)
          .join(', ')}</p>
      </div>`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, itemList], { shareImage: CATEGORY_BANNER_IMAGES[type] ? CATEGORY_BANNER_IMAGES[type].src : null, golfTheme: true, advisoryStyles: venues.some((v) => advisoryNotes.has(v.id)), noindex: venues.length === 0, savedSidecar: true })}
${renderOutdoorThemeStyles()}
${renderFoodDrinkHubStyles()}
${renderDestinationCategoryStyles()}
${golfEngagementHeadHtml('fd', true, 'category')}
</head>
<body class="golf-page outdoor-page fd-page fd-scoped-page">
${CATEGORY_BANNER_IMAGES[type] ? CATEGORY_BANNER_STYLE : ''}
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([
    { name: 'Home', href: '/' },
    valleyWide ? { name: 'Food & Drink', href: '/food-drink' } : { name: regionLabel, href: `/${region}` },
    { name: label.plural },
  ])}
  ${valleyWide
    ? categoryHeroHtml(categoryBannerHtml(type), `<h1>${escapeHtml(valleyText.heading)}</h1>\n  <p class="outdoor-intro fd-intro">${escapeHtml(valleyText.intro)}</p>`)
    : categoryHeroHtml(categoryBannerHtml(type), `<h1>${escapeHtml(label.plural)} in ${escapeHtml(regionLabel)}, BC</h1>${region === 'kelowna' && (type === 'restaurant' || type === 'cafe') ? `\n  <p class="subtitle"><a href="${BRUNCH_GUIDE_PATH}">Guide: the best brunch in Kelowna &rarr;</a></p>` : ''}`)}
  ${valleyWide ? renderCategoryRegionSelector(catSlug, venues) : regionCategoryTabsHtml(region, categoryCounts, type)}
  ${venues.length ? foodDrinkSearchHtml() : ''}
  ${venues.length ? foodDrinkFilterBarHtml(venues, state, scopeFeatures) : ''}
  <section class="outdoor-step outdoor-step-results fd-results-step" aria-labelledby="fdResultsTop">
  <h2 class="visually-hidden" id="fdResultsTop">Results</h2>
  ${foodDrinkResultBarHtml(foodDrinkSummaryText(matching.length, venues.length, filtered), state)}
  ${emptyHtml}
  ${cardsHtml}
  <script type="application/json" id="fdVenueData">${JSON.stringify(payload).replace(/</g, '\\u003c')}</script>
  </section>
  ${guideLinks}
  ${valleyWide ? '<a class="cta" href="/food-drink">Back to all Food &amp; Drink</a>' : `<a class="cta" href="/${region}">Back to all of ${escapeHtml(regionLabel)}</a>`}
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
  ${golfCardEngagementScriptHtml('fd', true)}
  ${renderFoodDrinkHubScriptHtml({ surface: 'food_drink_category' })}
</body>
</html>`;
}

// The page. Same themed shell as the /wineries hub (homepage header, Trip
// tray, app.css, name-as-link cards with the "View details" cue, Favorite /
// Add to Trip) so the engagement contract is identical -- list cards carry
// ONLY Favorite and Add to Trip; Website / Directions / Call stay on the
// venue detail pages, which are untouched.
// Page weight (2026-10-14): the hours in the page payload as one short string
// -- seven "|"-separated days, Monday first, each "x" (closed), "?" (not
// listed) or "11:00-23:00[,..]" -- or one day's value when all seven match.
// The page script expands it back to the stored object (FD_HOURS_CLIENT_SRC)
// before hours.js reads it. Anything unusual ships unchanged.
const FD_HOURS_DAYS = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'];
function compactFoodDrinkHours(h) {
  if (!h || typeof h !== 'object' || Array.isArray(h)) return h;
  if (Object.keys(h).some((k) => !FD_HOURS_DAYS.includes(k))) return h;
  const days = [];
  for (const d of FD_HOURS_DAYS) {
    if (!Object.prototype.hasOwnProperty.call(h, d)) { days.push('?'); continue; }
    const value = h[d];
    if (value === null || (Array.isArray(value) && value.length === 0)) { days.push('x'); continue; }
    if (!Array.isArray(value)) return h;
    const ranges = [];
    for (const r of value) {
      if (!Array.isArray(r) || r.length !== 2 || r.some((t) => typeof t !== 'string' || !/^\d{1,2}:\d{2}$/.test(t))) return h;
      ranges.push(`${r[0]}-${r[1]}`);
    }
    days.push(ranges.join(','));
  }
  return days.every((d) => d === days[0]) ? days[0] : days.join('|');
}
function expandFoodDrinkHours(h) {
  if (typeof h !== 'string') return h;
  var parts = h.split('|');
  if (parts.length === 1) parts = FD_HOURS_DAYS.map(function () { return parts[0]; });
  var out = {};
  FD_HOURS_DAYS.forEach(function (d, i) {
    var t = parts[i];
    if (t === undefined || t === '?') return;
    out[d] = t === 'x' ? [] : t.split(',').map(function (r) { return r.split('-'); });
  });
  return out;
}
const FD_HOURS_CLIENT_SRC = `var FD_HOURS_DAYS = ${JSON.stringify(FD_HOURS_DAYS)};
  ${expandFoodDrinkHours.toString()}`;
function renderFoodDrinkHubPage(venues, filter = null, scope = null, now = new Date()) {
  if (scope) return renderFoodDrinkScopedPage(venues, filter, scope);
  const f = filter || { types: [], features: [], regions: [] };
  // Sort (2026-10-14): the cards, the ItemList and data-fd-i all follow the
  // chosen order; the payload carries each venue's Recommended rank so the
  // page can switch order without a reload.
  const sort = FD_SORT_KEYS.has(f.sort) ? f.sort : 'recommended';
  const recommendedRank = new Map(sortFoodDrinkVenues(venues, 'recommended').map((v, i) => [v.id, i]));
  venues = sortFoodDrinkVenues(venues, sort);
  const openNow = !!f.openNow;
  const catsById = foodDrinkCategoriesByVenue(venues);
  const featsById = foodDrinkFeaturesByVenue(venues);
  const advisoryNotes = getAdvisoryNotes();
  // Open Now: an extra AND group over stored hours (no provenance requirement).
  // Venues with no hours, or under an advisory, are never "open" and drop out
  // when it is on; the chip counts are taken over the same set.
  const openInfo = foodDrinkOpenNowInfo(venues, advisoryNotes, now, { requireVerified: false });
  const pool = openNow ? venues.filter((v) => openInfo.openIds.has(v.id)) : venues;
  const matching = filterFoodDrinkVenues(pool, f, catsById, featsById);
  const matchIds = new Set(matching.map((v) => v.id));
  const counts = foodDrinkChipCounts(pool, f, catsById, featsById);
  const openCount = filterFoodDrinkVenues(venues.filter((v) => openInfo.openIds.has(v.id)), f, catsById, featsById).length;
  const filtered = f.types.length > 0 || f.features.length > 0 || f.regions.length > 0 || openNow;
  const state = { types: f.types, features: f.features, regions: f.regions, counts, openNow };

  const heading = 'Food & Drink in the Okanagan';
  const hubText = (f.types.length === 1 && FD_HUB_HEADINGS[f.types[0]]) || FD_HUB_HEADINGS.all;
  const title = `${heading} | Okanagan Roam`;
  const description = `${venues.length} restaurants, cafés, pubs and breweries across the Okanagan Valley. Filter by patio, dog-friendly, vegan or gluten-free.`;
  const canonical = 'https://okanaganroam.com/food-drink';
  // One type chosen (?types=brewery): the canonical is that type's own page
  // (SEO, 2026-10-13), so Google indexes /breweries rather than a filter view.
  const pageCanonical = f.types.length === 1 && !f.features.length && !f.regions.length && !openNow ? `https://okanaganroam.com/${CATEGORY_SLUGS[f.types[0]]}` : canonical;
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: 'Food & Drink', url: canonical },
  ]);
  // Page weight (2026-10-10): ItemList entries carry position, url, type and
  // name only, here and on every listing page. The full description used to
  // be repeated for every venue (~466 KB of /food-drink's 2.9 MB) although
  // it is already in each card and on each venue's own page.
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: title,
    description,
    itemListElement: venues.map((v, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      url: `https://okanaganroam.com/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}`,
      item: { '@type': SCHEMA_TYPE_MAP[v.type] || 'LocalBusiness', name: v.name },
    })),
  };
  // id -> { c: categories, f: features, r: region } for the client script,
  // plus h: the verified weekly hours of Open Now-eligible venues only.
  const payload = {};
  for (const v of venues) {
    payload[String(v.id)] = { c: catsById.get(v.id) || [], f: featsById.get(v.id) || [], r: v.region, k: descSearchWords(v.description), o: recommendedRank.get(v.id) };
    if (Number(v.rating)) payload[String(v.id)].g = Number(v.rating);
    if (Number(v.reviews)) payload[String(v.id)].n = Number(v.reviews);
    const st = openInfo.byId.get(v.id);
    if (st && st.eligible) payload[String(v.id)].h = compactFoodDrinkHours(st.hours);
  }
  // Incremental rendering (2026-09-24). Putting all 850 cards in the render
  // tree cost ~2.0-3.2s of style+layout before the page was interactive
  // (measured: domInteractive 2054ms local / 3157ms live, 18,024-23,855 DOM
  // nodes) -- parsing and the scripts were never the bottleneck. So only the
  // first FD_PAGE_SIZE MATCHING cards go into the list; every other card is
  // parsed into an inert <template>, which the browser does not style, lay
  // out or paint. "Show more" moves the next batch across.
  //
  // The card HTML is byte-for-byte the SAME markup either way -- it is the
  // same renderCategoryCardsHtml() output, just split -- so there is no
  // second, client-side card renderer to drift out of sync.
  //
  // Search and filtering still run over the FULL set: the client reads the
  // data attributes and text of the template's cards without instantiating
  // them, so every venue stays searchable and filterable and the count is
  // always "N of 850". data-fd-i keeps the canonical order stable no matter
  // which subset happens to be live.
  const cardsHtml = foodDrinkBatchedCardsHtml(venues, matchIds, matching.length, advisoryNotes, true, openInfo.byId);

  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, pageCanonical, [breadcrumb, itemList], { shareImage: FOOD_DRINK_HUB_BANNER.src, golfTheme: true, advisoryStyles: venues.some((v) => advisoryNotes.has(v.id)), savedSidecar: true })}
${renderOutdoorThemeStyles()}
${renderFoodDrinkHubStyles()}
${renderFoodDrinkOpenNowStyles()}
${golfEngagementHeadHtml('fd', true, 'hub')}
</head>
<body class="golf-page outdoor-page fd-page">
${CATEGORY_BANNER_STYLE}
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([{ name: 'Home', href: '/' }, { name: 'Food & Drink' }])}
  ${categoryHeroHtml(foodDrinkHubBannerHtml(f.types), `<h1 id="fdHeading">${escapeHtml(hubText.heading)}</h1>
  <p class="outdoor-intro fd-intro" id="fdIntro">${escapeHtml(hubText.intro)}</p>
  <p class="fd-type-page-link"><a href="${PATIO_GUIDE_PATH}">Guide: the best patios in Kelowna &rarr;</a></p>
  <p class="fd-type-page-link" id="fdTypePageLink"${f.types.length === 1 ? '' : ' hidden'}><a href="${f.types.length === 1 ? `/${CATEGORY_SLUGS[f.types[0]]}` : '#'}">See the ${escapeHtml(f.types.length === 1 ? CATEGORY_LABELS[f.types[0]].plural.toLowerCase() : '')} page &rarr;</a></p>`)}
  ${foodDrinkSearchHtml()}
  ${foodDrinkTypeChipsHtml(state)}
  ${foodDrinkFilterBarHtml(venues, state).replace(/\n  <\/div>$/, `\n    ${foodDrinkOpenNowToggleHtml(openNow, openCount)}\n  </div>`)}
  <p class="fd-open-note">${escapeHtml(FD_OPEN_NOTE)}</p>
  <section class="outdoor-step outdoor-step-results fd-results-step" aria-labelledby="fdResultsTop">
  <h2 class="visually-hidden" id="fdResultsTop">Results</h2>
  ${foodDrinkResultBarHtml(foodDrinkSummaryText(matching.length, venues.length, filtered), state, sort)}
  <p class="fd-search-note" id="fdSearchNote" hidden></p>
  <div class="fd-no-results" id="fdNoResults"${matching.length === 0 ? '' : ' hidden'}><p><span id="fdNoResultsText">No places match that combination yet.</span> <a href="/food-drink" id="fdNoResultsClear">Clear the filters</a> to see everything.</p>
  <p class="fd-no-results-try">Try one word, like <a href="/food-drink?types=cafe">caf\u00e9s</a>, <a href="/food-drink?features=patio">patio</a> or <a href="/food-drink?features=dog_friendly">dog friendly</a>.</p></div>
  ${cardsHtml}
  <p class="fd-open-note fd-open-note-end">${escapeHtml(FD_OPEN_NOTE)}</p>
  <script type="application/json" id="fdVenueData">${JSON.stringify(payload).replace(/</g, '\\u003c')}</script>
  </section>
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
  ${golfCardEngagementScriptHtml('fd', true)}
  ${renderFoodDrinkHubScriptHtml({ openNow: true })}
</body>
</html>`;
}

// ---------- Wineries hub (2026-10-14): /wineries on the Food & Drink engine ----------
// The Wineries page listed all 201 wineries at once, A-Z by town (so the
// first cards were Armstrong's and Enderby's single wineries and Oliver's 49
// sat halfway down), with only a row of town links to narrow it. It now
// uses the same building blocks as /food-drink -- search, Recommended / Top
// rated / A-Z, the Regions popover, "What are you looking for?" with the
// features wineries actually carry, Open now from stored hours, 48 cards at
// a time and an example wine photo per card -- with no venue-type chips.
// The town pages (/oliver/wineries ...) stay linked from a "Wineries by
// town" row under the list.
const WINE_HUB_MIN_FEATURE = 5;
function renderWineriesHubPage(venues, filter = null, now = new Date()) {
  const f = { types: [], features: [], regions: [], ...(filter || {}), types: [] };
  const sort = FD_SORT_KEYS.has(f.sort) ? f.sort : 'recommended';
  const recommendedRank = new Map(sortFoodDrinkVenues(venues, 'recommended').map((v, i) => [v.id, i]));
  venues = sortFoodDrinkVenues(venues, sort);
  const openNow = !!f.openNow;
  const catsById = new Map(venues.map((v) => [v.id, ['winery']]));
  const featsById = foodDrinkFeaturesByVenue(venues);
  // Only the features at least a handful of wineries carry.
  const featureTally = {};
  for (const list of featsById.values()) for (const k of list) featureTally[k] = (featureTally[k] || 0) + 1;
  const featureKeys = FD_HUB_FEATURES.map((x) => x.key).filter((k) => (featureTally[k] || 0) >= WINE_HUB_MIN_FEATURE);
  f.features = f.features.filter((k) => featureKeys.includes(k));
  const advisoryNotes = getAdvisoryNotes();
  const openInfo = foodDrinkOpenNowInfo(venues, advisoryNotes, now, { requireVerified: false });
  const pool = openNow ? venues.filter((v) => openInfo.openIds.has(v.id)) : venues;
  const matching = filterFoodDrinkVenues(pool, f, catsById, featsById);
  const matchIds = new Set(matching.map((v) => v.id));
  const counts = foodDrinkChipCounts(pool, f, catsById, featsById);
  const openCount = filterFoodDrinkVenues(venues.filter((v) => openInfo.openIds.has(v.id)), f, catsById, featsById).length;
  const filtered = f.features.length > 0 || f.regions.length > 0 || openNow;
  const state = { types: [], features: f.features, regions: f.regions, counts, openNow };

  const heading = 'Wineries in the Okanagan';
  const title = `${heading} | Okanagan Roam`;
  const description = `${venues.length} verified wineries across the Okanagan Valley \u2014 search, see which are open now, and filter by town, patio, dog-friendly and lake view.`;
  const canonical = 'https://okanaganroam.com/wineries';
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: 'Wineries', url: canonical },
  ]);
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: title,
    description,
    itemListElement: venues.map((v, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      url: `https://okanaganroam.com/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}`,
      item: { '@type': SCHEMA_TYPE_MAP[v.type] || 'LocalBusiness', name: v.name },
    })),
  };
  const payload = {};
  for (const v of venues) {
    payload[String(v.id)] = { c: ['winery'], f: featsById.get(v.id) || [], r: v.region, k: descSearchWords(v.description), o: recommendedRank.get(v.id) };
    if (Number(v.rating)) payload[String(v.id)].g = Number(v.rating);
    if (Number(v.reviews)) payload[String(v.id)].n = Number(v.reviews);
    const st = openInfo.byId.get(v.id);
    if (st && st.eligible) payload[String(v.id)].h = compactFoodDrinkHours(st.hours);
  }
  const cardsHtml = foodDrinkBatchedCardsHtml(venues, matchIds, matching.length, advisoryNotes, true, openInfo.byId);
  const nF = f.features.length, nR = f.regions.length;
  const pop = (id, labelHtml, icon, badge, panel) => `<div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="${id}Btn" aria-expanded="false" aria-controls="${id}Panel"><span class="fd-pop-icon" aria-hidden="true">${icon}</span> ${labelHtml}<span class="fd-pop-count" id="${id}Count"${badge ? '' : ' hidden'}>${badge ? ` \u00b7 ${escapeHtml(String(badge))}` : ''}</span></button>
      <div class="fd-pop-panel" id="${id}Panel" hidden>${panel}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-fd-apply>Show results</button></div>
      </div>
    </div>`;
  const controlsHtml = `<div class="fd-controls">
    ${pop('fdRegions', 'Regions', '\u{1F4CD}', nR || '', renderOutdoorRegionFilterChips(venues, { selectedRegions: f.regions, counts }))}
    ${pop('fdFeatures', '<span class="fd-pop-long">What are you looking for?</span><span class="fd-pop-short">Filters</span>', '\u2728', nF || '', foodDrinkFeatureChipsHtml(state, featureKeys))}
    ${foodDrinkOpenNowToggleHtml(openNow, openCount)}
  </div>`;
  // The town pages, busiest first, for visitors and crawlers alike.
  const townCounts = {};
  for (const v of venues) townCounts[v.region] = (townCounts[v.region] || 0) + 1;
  const townLinks = Object.entries(townCounts).filter(([r]) => REGION_LABELS[r])
    .sort((a, b) => b[1] - a[1] || REGION_LABELS[a[0]].localeCompare(REGION_LABELS[b[0]]))
    .map(([r, n]) => `<a href="/${r}/wineries">${escapeHtml(REGION_LABELS[r])} <span>${n}</span></a>`).join('\n      ');
  const wineTry = featureKeys.includes('patio') ? `<a href="/wineries?features=patio">patio</a>, ` : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, itemList], { shareImage: CATEGORY_BANNER_IMAGES.winery.src, golfTheme: true, advisoryStyles: venues.some((v) => advisoryNotes.has(v.id)), savedSidecar: true })}
${renderOutdoorThemeStyles()}
${renderFoodDrinkHubStyles()}
${renderFoodDrinkOpenNowStyles()}
${golfEngagementHeadHtml('winery', true, 'hub')}
<style id="wine-hub">
  body.wine-hub-page .wine-guide-link { margin: 0 0 14px; font-weight: 700; }
  body.wine-hub-page .wine-guide-link a { color: var(--teal); }
  body.wine-hub-page .wine-towns { margin: 26px 0 8px; }
  body.wine-hub-page .wine-towns h2 { font-family: 'Fraunces', serif; font-weight: 600; font-size: 1.15rem; margin: 0 0 10px; }
  body.wine-hub-page .wine-towns nav { display: flex; flex-wrap: wrap; gap: 8px; }
  body.wine-hub-page .wine-towns a { display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; min-height: 40px; box-sizing: border-box; border: 1px solid rgba(27,43,58,0.18); border-radius: 999px; font-family: 'Nunito', sans-serif; font-size: 0.86rem; font-weight: 700; color: var(--ref-navy); text-decoration: none; background: var(--paper); }
  body.wine-hub-page .wine-towns a:hover { background: rgba(27,43,58,0.06); }
  body.wine-hub-page .wine-towns a span { font-size: 0.74rem; opacity: 0.6; }
</style>
</head>
<body class="golf-page outdoor-page fd-page winery-page wine-hub-page">
${CATEGORY_BANNER_STYLE}
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([{ name: 'Home', href: '/' }, { name: 'Wineries' }])}
  ${categoryHeroHtml(categoryBannerHtml('winery'), `<h1>${escapeHtml(heading)}</h1>
  <p class="outdoor-intro fd-intro">${escapeHtml(HUB_INTRO_TEXT.winery)}</p>
  <p class="wine-guide-link"><a href="${WINE_GUIDE_PATH}">New to wine country? Start with our first-timer\u2019s guide &rarr;</a></p>`)}
  ${foodDrinkSearchHtml().replace('Search food and drink', 'Search wineries').replace('Search by name, place or dish...', 'Search by name, town or wine...')}
  ${controlsHtml}
  <p class="fd-open-note">${escapeHtml(FD_OPEN_NOTE)}</p>
  <section class="outdoor-step outdoor-step-results fd-results-step" aria-labelledby="fdResultsTop">
  <h2 class="visually-hidden" id="fdResultsTop">Results</h2>
  ${foodDrinkResultBarHtml(foodDrinkSummaryText(matching.length, venues.length, filtered).replace(/places?$/, (m) => (m === 'place' ? 'winery' : 'wineries')), state, sort)}
  <p class="fd-search-note" id="fdSearchNote" hidden></p>
  <div class="fd-no-results" id="fdNoResults"${matching.length === 0 ? '' : ' hidden'}><p><span id="fdNoResultsText">No wineries match that combination yet.</span> <a href="/wineries" id="fdNoResultsClear">Clear the filters</a> to see everything.</p>
  <p class="fd-no-results-try">Try one word, like ${wineTry}<a href="/wineries?regions=oliver">Oliver</a> or <a href="/wineries?regions=naramata">Naramata</a>.</p></div>
  ${cardsHtml}
  <p class="fd-open-note fd-open-note-end">${escapeHtml(FD_OPEN_NOTE)}</p>
  <section class="wine-towns" aria-labelledby="wineTownsHeading">
    <h2 id="wineTownsHeading">Wineries by town</h2>
    <nav aria-label="Wineries by town">
      ${townLinks}
    </nav>
  </section>
  <script type="application/json" id="fdVenueData">${JSON.stringify(payload).replace(/</g, '\\u003c')}</script>
  </section>
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
  ${golfCardEngagementScriptHtml('winery', true)}
  ${renderFoodDrinkHubScriptHtml({ openNow: true, surface: 'wineries', noun: ['winery', 'wineries'] })}
</body>
</html>`;
}

// ---------- Indoor & Rainy Day hub (2026-10-14): /indoor on the Food & Drink engine ----------
// /indoor listed 125 indoor places A-Z by town, then "Indoor golf &
// simulators" and "Also good on a rainy day" as two more lists (156 in all,
// while the top said 125), with no way to see what is open and the "Family
// Fun" choice matching every kid-friendly place (102 of 156). It is now one
// list on the shared directory engine: experience chips (Museums &
// Galleries, Family Fun, Games & Escape Rooms, Spas, Theatre, Indoor Golf)
// as the type filter, Open now from stored hours, search, Regions, features,
// 48 at a time and an experience photo per card. Family Fun now means places
// built for active or hands-on family time (play centres, climbing,
// trampolines, pools, arenas, bowling, the science centre), not every
// kid-friendly listing. Few of these places carry a rating, so Recommended
// prefers the listings a visitor can act on (stored hours, a fuller
// description), never an editorial flag. The experience pages
// (/indoor/arts ...) and the town pages stay linked under the list.
const INDOOR_HUB_EXPERIENCES = [
  ...INDOOR_EXPERIENCES.map((e) => ({ slug: e.slug, label: e.label, pattern: e.pattern || null })),
  { slug: 'golf', label: 'Indoor Golf', pattern: null },
];
const INDOOR_FAMILY_NAME_RE = /trampolin|bounce|play ?(?:ground|centre|center|land|zone|space|place|house)|indoor play|climb|boulder|aquatic|pool|swim|splash|water ?park|science|discovery|arcade|laser|bowl|mini[- ]?golf|ninja|parkour|airhouse|energyplex|kids|kidz|children|petting|family fun|fun ?zone|funspace|go[- ]?kart|karting|roller|skating|arena|gymnastics|sportszone/i;
function indoorExperiencesOf(v, note) {
  const text = `${v.name || ''} ${note || ''}`;
  const out = [];
  for (const e of INDOOR_HUB_EXPERIENCES) {
    if (e.slug === 'golf') { if (v.type === 'golf') out.push('golf'); continue; }
    if (e.slug === 'family') {
      const desc = String(v.description || '');
      const familyish = INDOOR_FAMILY_NAME_RE.test(text)
        || (v.kid_friendly && /\bkids\b|children|families|family-friendly|toddlers|birthday/i.test(desc) && INDOOR_FAMILY_NAME_RE.test(desc));
      if (familyish && !['brewery', 'pub', 'cocktail', 'distillery', 'winery'].includes(v.type)) out.push('family');
      continue;
    }
    if (e.pattern && e.pattern.test(text)) out.push(e.slug);
  }
  return out;
}
const INDOOR_SORTS = [
  { key: 'recommended', label: 'Recommended' },
  { key: 'town', label: 'By town' },
  { key: 'az', label: 'A\u2013Z' },
];
const INDOOR_SORT_KEYS = new Set(INDOOR_SORTS.map((x) => x.key));
// Few of these places carry a rating (and the ones that do are mostly the
// breweries and pubs listed for their bowling or games), so ratings are not
// used: places that are indoor attractions first, then the ones a visitor
// can plan around (stored hours, a fuller description).
function indoorRecommendedScore(v) {
  let score = v.type === 'indoor' || v.type === 'golf' ? 1 : 0;
  if (v.hours) score += 1;
  score += Math.min(String(v.description || '').split(/\s+/).length, 80) / 80;
  if (v.kid_friendly) score += 0.2;
  if (v.great_groups) score += 0.2;
  return score;
}
function renderIndoorHubPage(indoorVenues, golfVenues, alsoVenues, notes, filter = null, now = new Date()) {
  const f = { types: [], features: [], regions: [], ...(filter || {}) };
  const sort = INDOOR_SORT_KEYS.has(f.sort) ? f.sort : 'recommended';
  const openNow = !!f.openNow;
  const seen = new Set();
  const all = [...indoorVenues, ...golfVenues, ...alsoVenues].filter((v) => (seen.has(v.id) ? false : seen.add(v.id)));
  const expById = new Map(all.map((v) => [v.id, indoorExperiencesOf(v, notes.get(v.id))]));
  const byName = (a, b) => String(a.name).localeCompare(String(b.name), 'en', { sensitivity: 'base' });
  const score = new Map(all.map((v) => [v.id, indoorRecommendedScore(v)]));
  const ranked = all.slice().sort((a, b) => score.get(b.id) - score.get(a.id) || byName(a, b));
  // A mixed first screen: the next place is the best-ranked one whose main
  // experience differs from the one before, so golf simulators or museums
  // don't open the list back to back.
  const leadOf = (v) => (v.type === 'golf' ? 'golf' : (expById.get(v.id) || [])[0] || v.type);
  // In the first dozen, at most two of any one kind.
  const recommended = [];
  const rest = ranked.slice();
  const seenLead = {};
  while (rest.length) {
    const prev = recommended.length ? leadOf(recommended[recommended.length - 1]) : null;
    const early = recommended.length < 12;
    let pick = early ? rest.slice(0, 24).findIndex((v) => leadOf(v) !== prev && (seenLead[leadOf(v)] || 0) < 2) : -1;
    if (pick < 0) pick = rest.slice(0, 6).findIndex((v) => leadOf(v) !== prev);
    if (pick < 0) pick = 0;
    const v = rest.splice(pick, 1)[0];
    seenLead[leadOf(v)] = (seenLead[leadOf(v)] || 0) + 1;
    recommended.push(v);
  }
  const recommendedRank = new Map(recommended.map((v, i) => [v.id, i]));
  const venues = sort === 'az' ? all.slice().sort(byName)
    : sort === 'town' ? all.slice().sort((a, b) => String(REGION_LABELS[a.region] || '').localeCompare(String(REGION_LABELS[b.region] || '')) || byName(a, b))
      : recommended;
  const featsById = foodDrinkFeaturesByVenue(venues);
  const featureTally = {};
  for (const list of featsById.values()) for (const k of list) featureTally[k] = (featureTally[k] || 0) + 1;
  // Only the features that mean something indoors.
  const featureKeys = ['kid_friendly', 'great_groups', 'dog_friendly'].filter((k) => (featureTally[k] || 0) >= 5);
  f.features = f.features.filter((k) => featureKeys.includes(k));
  const advisoryNotes = getAdvisoryNotes();
  const openInfo = foodDrinkOpenNowInfo(venues, advisoryNotes, now, { requireVerified: false });
  const pool = openNow ? venues.filter((v) => openInfo.openIds.has(v.id)) : venues;
  const matching = filterFoodDrinkVenues(pool, f, expById, featsById);
  const matchIds = new Set(matching.map((v) => v.id));
  const counts = foodDrinkChipCounts(pool, f, expById, featsById);
  const openCount = filterFoodDrinkVenues(venues.filter((v) => openInfo.openIds.has(v.id)), f, expById, featsById).length;
  const filtered = f.types.length > 0 || f.features.length > 0 || f.regions.length > 0 || openNow;
  const state = { types: f.types, features: f.features, regions: f.regions, counts, openNow };
  const expLabel = Object.fromEntries(INDOOR_HUB_EXPERIENCES.map((e) => [e.slug, e.label]));
  // "Rainy day:" stays on the cards that have a note (a brewery with bowling, an arena).
  const cardNotes = new Map(all.filter((v) => String(notes.get(v.id) || '').trim()).map((v) => [v.id, String(notes.get(v.id)).trim()]));
  const PHOTO_ORDER = ['theatre', 'spas', 'arts', 'games', 'family', 'golf'];
  const photoKeyFor = (v) => {
    const exps = expById.get(v.id) || [];
    const lead = v.type === 'golf' ? 'golf' : PHOTO_ORDER.find((x) => exps.includes(x));
    const key = lead === 'golf' ? 'simgolf' : lead;
    return key ? `${key}-0` : 'indoorall-0';
  };

  const heading = 'Indoor & Rainy Day in the Okanagan';
  const title = `${heading} | Okanagan Roam`;
  const description = `${all.length} indoor things to do in the Okanagan for grey, wet or cold days \u2014 museums, galleries, theatres, escape rooms, bowling, climbing gyms, spas and indoor golf, with what's open now.`;
  const canonical = 'https://okanaganroam.com/indoor';
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: 'Indoor & Rainy Day Spots', url: canonical },
  ]);
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: title,
    description,
    itemListElement: venues.map((v, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      url: `https://okanaganroam.com/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}`,
      item: { '@type': SCHEMA_TYPE_MAP[v.type] || 'LocalBusiness', name: v.name },
    })),
  };
  const payload = {};
  for (const v of venues) {
    payload[String(v.id)] = { c: expById.get(v.id) || [], f: featsById.get(v.id) || [], r: v.region, k: descSearchWords(`${notes.get(v.id) || ''} ${v.description || ''}`), o: recommendedRank.get(v.id) };
    const st = openInfo.byId.get(v.id);
    if (st && st.eligible) payload[String(v.id)].h = compactFoodDrinkHours(st.hours);
  }
  const cardsHtml = foodDrinkBatchedCardsHtml(venues, matchIds, matching.length, advisoryNotes, true, openInfo.byId, { cardNotes, cardNoteLabel: 'Rainy day:', photoKeyFor });
  const selected = new Set(f.types);
  const chips = `<div class="fd-type-row" role="group" aria-label="Choose an indoor experience" data-filter="fd-type"><button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-fd-type-all="1" aria-pressed="${selected.size ? 'false' : 'true'}">All</button>${INDOOR_HUB_EXPERIENCES.map((e) => `<button type="button" class="outdoor-filter-chip fd-type-chip" data-fd-type="${e.slug}" aria-pressed="${selected.has(e.slug) ? 'true' : 'false'}">${escapeHtml(e.label)}<span class="outdoor-activity-count">${counts.types[e.slug] || 0}</span></button>`).join('')}</div>`;
  const nF = f.features.length, nR = f.regions.length;
  const pop = (id, labelHtml, icon, badge, panel) => `<div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="${id}Btn" aria-expanded="false" aria-controls="${id}Panel"><span class="fd-pop-icon" aria-hidden="true">${icon}</span> ${labelHtml}<span class="fd-pop-count" id="${id}Count"${badge ? '' : ' hidden'}>${badge ? ` \u00b7 ${escapeHtml(String(badge))}` : ''}</span></button>
      <div class="fd-pop-panel" id="${id}Panel" hidden>${panel}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-fd-apply>Show results</button></div>
      </div>
    </div>`;
  const controlsHtml = `<div class="fd-controls">
    ${pop('fdRegions', 'Regions', '\u{1F4CD}', nR || '', renderOutdoorRegionFilterChips(venues, { selectedRegions: f.regions, counts }))}
    ${featureKeys.length ? pop('fdFeatures', '<span class="fd-pop-long">What are you looking for?</span><span class="fd-pop-short">Filters</span>', '\u2728', nF || '', foodDrinkFeatureChipsHtml(state, featureKeys)) : ''}
    ${foodDrinkOpenNowToggleHtml(openNow, openCount)}
  </div>`;
  const expLinks = INDOOR_EXPERIENCES.map((e) => `<a href="/indoor/${e.slug}">${escapeHtml(e.label)} <span>${counts.types[e.slug] || 0}</span></a>`).join('\n      ');
  const townCounts = {};
  for (const v of venues) townCounts[v.region] = (townCounts[v.region] || 0) + 1;
  const townLinks = Object.entries(townCounts).filter(([r]) => REGION_LABELS[r])
    .sort((a, b) => b[1] - a[1] || REGION_LABELS[a[0]].localeCompare(REGION_LABELS[b[0]]))
    .map(([r, n]) => `<a href="/${r}/${CATEGORY_SLUGS.indoor}">${escapeHtml(REGION_LABELS[r])} <span>${n}</span></a>`).join('\n      ');

  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, itemList], { shareImage: CATEGORY_BANNER_IMAGES.indoor.src, golfTheme: true, beachTheme: all.some((v) => v.type === 'beach'), advisoryStyles: all.some((v) => advisoryNotes.has(v.id)), savedSidecar: true, noindex: all.length === 0 })}
${renderOutdoorThemeStyles()}
${renderFoodDrinkHubStyles()}
${renderFoodDrinkOpenNowStyles()}
${golfEngagementHeadHtml('indoor', true, 'hub')}
<style id="indoor-hub">
  body.indoor-hub-page .rainy-guide-link { margin: 0 0 14px; font-weight: 700; }
  body.indoor-hub-page .rainy-guide-link a { color: var(--teal); }
  body.indoor-hub-page .hub-links { margin: 26px 0 8px; }
  body.indoor-hub-page .hub-links h2 { font-family: 'Fraunces', serif; font-weight: 600; font-size: 1.15rem; margin: 0 0 10px; }
  body.indoor-hub-page .hub-links nav { display: flex; flex-wrap: wrap; gap: 8px; }
  body.indoor-hub-page .hub-links a { display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; min-height: 40px; box-sizing: border-box; border: 1px solid rgba(27,43,58,0.18); border-radius: 999px; font-family: 'Nunito', sans-serif; font-size: 0.86rem; font-weight: 700; color: var(--ref-navy); text-decoration: none; background: var(--paper); }
  body.indoor-hub-page .hub-links a:hover { background: rgba(27,43,58,0.06); }
  body.indoor-hub-page .hub-links a span { font-size: 0.74rem; opacity: 0.6; }
  body.indoor-hub-page .card-note-label { font-weight: 800; }
</style>
</head>
<body class="golf-page outdoor-page fd-page indoor-page indoor-hub-page">
${CATEGORY_BANNER_STYLE}
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([{ name: 'Home', href: '/' }, { name: 'Indoor & Rainy Day Spots' }])}
  ${categoryHeroHtml(categoryBannerHtml('indoor'), `<h1>${escapeHtml(heading)}</h1>
  <p class="outdoor-intro fd-intro">${escapeHtml(HUB_INTRO_TEXT.indoor)}</p>
  <p class="rainy-guide-link"><a href="${RAINY_GUIDE_PATH}">Guide: a rainy day in the Okanagan &rarr;</a></p>`)}
  ${indoorVenues.length ? '' : '<p class="indoor-coming-soon">More indoor spots are coming soon &mdash; museums, galleries, theatres, escape rooms, bowling and climbing gyms across the valley.</p>'}
  ${foodDrinkSearchHtml().replace('Search food and drink', 'Search indoor things to do').replace('Search by name, place or dish...', 'Search escape room, climbing, a town...')}
  ${chips}
  ${controlsHtml}
  <p class="fd-open-note">${escapeHtml(FD_OPEN_NOTE)}</p>
  <section class="outdoor-step outdoor-step-results fd-results-step" aria-labelledby="fdResultsTop">
  <h2 class="visually-hidden" id="fdResultsTop">Results</h2>
  ${foodDrinkResultBarHtml(foodDrinkSummaryText(matching.length, venues.length, filtered), state, sort, INDOOR_SORTS)}
  <p class="fd-search-note" id="fdSearchNote" hidden></p>
  <div class="fd-no-results" id="fdNoResults"${matching.length === 0 ? '' : ' hidden'}><p><span id="fdNoResultsText">No places match that combination yet.</span> <a href="/indoor" id="fdNoResultsClear">Clear the filters</a> to see everything.</p>
  <p class="fd-no-results-try">Try one word, like <a href="/indoor?types=games">escape rooms</a>, <a href="/indoor?types=family">family fun</a> or <a href="/indoor?types=arts">museums</a>.</p></div>
  ${cardsHtml}
  <p class="fd-open-note fd-open-note-end">${escapeHtml(FD_OPEN_NOTE)}</p>
  <section class="hub-links" aria-labelledby="indoorExperiencesHeading">
    <h2 id="indoorExperiencesHeading">By experience</h2>
    <nav aria-label="Indoor things to do by experience">
      ${expLinks}
    </nav>
  </section>
  <section class="hub-links" aria-labelledby="indoorTownsHeading">
    <h2 id="indoorTownsHeading">By town</h2>
    <nav aria-label="Indoor things to do by town">
      ${townLinks}
    </nav>
  </section>
  <script type="application/json" id="fdVenueData">${JSON.stringify(payload).replace(/</g, '\\u003c')}</script>
  </section>
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
  ${golfCardEngagementScriptHtml('indoor', true)}
  ${renderFoodDrinkHubScriptHtml({ openNow: true, surface: 'indoor', typeLabels: expLabel, searchLabels: { arts: 'museum gallery', family: 'family kids', games: 'games', spas: 'spa', theatre: 'theatre cinema', golf: 'indoor golf simulator' } })}
</body>
</html>`;
}

// ---------- Sports & Recreation hub (2026-10-14): /sports on the Food & Drink engine ----------
// /sports used to show 17 sport-type places first and the 36 "More places to
// play" (the big trail networks, bike parks and court complexes) in a second
// list under them, A-Z by town, with a count of 17 at the top. It is now one
// list of all of them on the shared directory engine: activity chips (Skate
// Parks & BMX, Mountain Biking, Disc Golf, Courts) as the type filter,
// search, Regions, features, 48 at a time, an activity photo per card and a
// "Play:" line on every card. None of these places carries a rating, so
// "Biggest first" ranks by the size the listing itself states -- km of
// trail, number of trails, courts or holes, a lift-served bike park -- and
// never by an editorial flag. The activity pages (/sports/skate ...) and the
// town pages stay linked under the list.
const SPORTS_SORTS = [
  { key: 'recommended', label: 'Biggest first' },
  { key: 'town', label: 'By town' },
  { key: 'az', label: 'A\u2013Z' },
];
const SPORTS_SORT_KEYS = new Set(SPORTS_SORTS.map((x) => x.key));
function sportScaleScore(v, note) {
  // The "Play:" note is always about the sport, so any km or trail count in
  // it counts; the description also talks about drives and ski runs, so
  // there only "N km of trail / singletrack" counts.
  const play = String(note || '').toLowerCase();
  const desc = `${v.name || ''} ${v.description || ''}`.toLowerCase();
  const text = `${play} ${desc}`;
  const nums = (src, re) => [...src.matchAll(re)].map((m) => Number(String(m[1]).replace(/,/g, ''))).filter((n) => Number.isFinite(n));
  const max = (arr) => (arr.length ? Math.max(...arr) : 0);
  let score = 0;
  const km = Math.max(max(nums(play, /(\d[\d,]*(?:\.\d+)?)\+?\s*km\b/g)), max(nums(desc, /(\d[\d,]*(?:\.\d+)?)\+?\s*km(?:\s+of)?(?:\s+[a-z-]+){0,2}?\s+(?:singletrack|trails?|riding)\b/g)));
  score += Math.min(km, 150) / 10;
  score += Math.min(max(nums(text, /(\d{1,3})\+?\s+trails\b/g)), 110) / 10;
  score += Math.min(max(nums(text, /(\d{1,2})\s*(?:-\s*)?(?:outdoor |covered |dedicated |permanently lined |lit )*(?:pickleball |tennis |beach volleyball |volleyball )?courts\b/g)), 20) * 0.5;
  if (/\b18-hole\b/.test(play || text)) score += 2; else if (/\b9-hole\b/.test(play || text)) score += 1;
  if (/lift-served|bike park/.test(play || text)) score += 3;
  if (/pump track/.test(play || text)) score += 1;
  if (/\bbowl\b/.test(play || text)) score += 0.5;
  if (/\blit\b|lights/.test(play || text)) score += 0.5;
  return score + Math.min(String(v.description || '').length, 1200) / 1200;
}
function renderSportsHubPage(sportVenues, alsoVenues, notes, filter = null) {
  const f = { types: [], features: [], regions: [], ...(filter || {}) };
  const sort = SPORTS_SORT_KEYS.has(f.sort) ? f.sort : 'recommended';
  const all = [...sportVenues, ...alsoVenues.filter((v) => !sportVenues.some((s) => s.id === v.id))];
  const actsById = new Map(all.map((v) => [v.id, sportActivitiesOf(v, notes)]));
  const scale = new Map(all.map((v) => [v.id, sportScaleScore(v, notes.get(v.id))]));
  const byName = (a, b) => String(a.name).localeCompare(String(b.name), 'en', { sensitivity: 'base' });
  const recommended = all.slice().sort((a, b) => scale.get(b.id) - scale.get(a.id) || byName(a, b));
  const recommendedRank = new Map(recommended.map((v, i) => [v.id, i]));
  const venues = sort === 'az' ? all.slice().sort(byName)
    : sort === 'town' ? all.slice().sort((a, b) => String(REGION_LABELS[a.region] || '').localeCompare(String(REGION_LABELS[b.region] || '')) || byName(a, b))
      : recommended;
  const featsById = foodDrinkFeaturesByVenue(venues);
  const featureTally = {};
  for (const list of featsById.values()) for (const k of list) featureTally[k] = (featureTally[k] || 0) + 1;
  const featureKeys = FD_HUB_FEATURES.map((x) => x.key).filter((k) => (featureTally[k] || 0) >= 3);
  f.features = f.features.filter((k) => featureKeys.includes(k));
  const advisoryNotes = getAdvisoryNotes();
  const matching = filterFoodDrinkVenues(venues, f, actsById, featsById);
  const matchIds = new Set(matching.map((v) => v.id));
  const counts = foodDrinkChipCounts(venues, f, actsById, featsById);
  const filtered = f.types.length > 0 || f.features.length > 0 || f.regions.length > 0;
  const state = { types: f.types, features: f.features, regions: f.regions, counts, openNow: false };
  const actLabel = Object.fromEntries(SPORT_ACTIVITIES.map((a) => [a.slug, a.label]));
  // "Play:" on every card: the listing's own note, else its activities.
  const cardNotes = new Map(all.map((v) => [v.id, String(notes.get(v.id) || '').trim() || (actsById.get(v.id) || []).map((s) => actLabel[s]).join(' \u00b7 ')]));
  // The photo follows whatever the "Play:" line names first ("Lift-served
  // bike park ..., pump track" is a bike photo, not a skate one).
  const leadActivity = (v) => {
    const acts = actsById.get(v.id) || [];
    const text = String(notes.get(v.id) || v.name || '');
    let best = acts[0], at = Infinity;
    for (const a of SPORT_ACTIVITIES) {
      if (!acts.includes(a.slug)) continue;
      const m = text.search(a.pattern);
      if (m !== -1 && m < at) { at = m; best = a.slug; }
    }
    return best;
  };
  const photoKeyFor = (v) => {
    const a = leadActivity(v);
    const list = a && FD_CARD_PHOTOS[a];
    return list ? `${a}-${(Number(v.id) || 0) % list.length}` : 'bike-0';
  };

  const heading = 'Sports & Recreation in the Okanagan';
  const title = `${heading} | Okanagan Roam`;
  const description = `${all.length} places to play across the Okanagan: skate parks and BMX tracks, mountain bike trail networks and bike parks, disc golf courses, and pickleball, tennis and beach volleyball courts.`;
  const canonical = 'https://okanaganroam.com/sports';
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: 'Sports & Recreation', url: canonical },
  ]);
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: title,
    description,
    itemListElement: venues.map((v, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      url: `https://okanaganroam.com/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}`,
      item: { '@type': SCHEMA_TYPE_MAP[v.type] || 'LocalBusiness', name: v.name },
    })),
  };
  const payload = {};
  for (const v of venues) payload[String(v.id)] = { c: actsById.get(v.id) || [], f: featsById.get(v.id) || [], r: v.region, k: descSearchWords(`${notes.get(v.id) || ''} ${v.description || ''}`), o: recommendedRank.get(v.id) };
  const cardsHtml = foodDrinkBatchedCardsHtml(venues, matchIds, matching.length, advisoryNotes, true, null, { cardNotes, cardNoteLabel: 'Play:', photoKeyFor });
  const selected = new Set(f.types);
  const chips = `<div class="fd-type-row" role="group" aria-label="Choose an activity" data-filter="fd-type"><button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-fd-type-all="1" aria-pressed="${selected.size ? 'false' : 'true'}">All</button>${SPORT_ACTIVITIES.map((a) => `<button type="button" class="outdoor-filter-chip fd-type-chip" data-fd-type="${a.slug}" aria-pressed="${selected.has(a.slug) ? 'true' : 'false'}">${escapeHtml(a.label)}<span class="outdoor-activity-count">${counts.types[a.slug] || 0}</span></button>`).join('')}</div>`;
  const nF = f.features.length, nR = f.regions.length;
  const pop = (id, labelHtml, icon, badge, panel) => `<div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="${id}Btn" aria-expanded="false" aria-controls="${id}Panel"><span class="fd-pop-icon" aria-hidden="true">${icon}</span> ${labelHtml}<span class="fd-pop-count" id="${id}Count"${badge ? '' : ' hidden'}>${badge ? ` \u00b7 ${escapeHtml(String(badge))}` : ''}</span></button>
      <div class="fd-pop-panel" id="${id}Panel" hidden>${panel}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-fd-apply>Show results</button></div>
      </div>
    </div>`;
  const controlsHtml = `<div class="fd-controls">
    ${pop('fdRegions', 'Regions', '\u{1F4CD}', nR || '', renderOutdoorRegionFilterChips(venues, { selectedRegions: f.regions, counts }))}
    ${featureKeys.length ? pop('fdFeatures', '<span class="fd-pop-long">What are you looking for?</span><span class="fd-pop-short">Filters</span>', '\u2728', nF || '', foodDrinkFeatureChipsHtml(state, featureKeys)) : ''}
  </div>`;
  const activityLinks = SPORT_ACTIVITIES.map((a) => `<a href="/sports/${a.slug}">${escapeHtml(a.label)} <span>${counts.types[a.slug] || 0}</span></a>`).join('\n      ');
  const townCounts = {};
  for (const v of venues) townCounts[v.region] = (townCounts[v.region] || 0) + 1;
  const townLinks = Object.entries(townCounts).filter(([r]) => REGION_LABELS[r])
    .sort((a, b) => b[1] - a[1] || REGION_LABELS[a[0]].localeCompare(REGION_LABELS[b[0]]))
    .map(([r, n]) => `<a href="/${r}/sports">${escapeHtml(REGION_LABELS[r])} <span>${n}</span></a>`).join('\n      ');
  const banner = CATEGORY_BANNER_IMAGES.sport;

  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, itemList], { shareImage: banner.src, golfTheme: true, beachTheme: all.some((v) => v.type === 'beach'), advisoryStyles: all.some((v) => advisoryNotes.has(v.id)), savedSidecar: true, noindex: all.length === 0 })}
${renderOutdoorThemeStyles()}
${renderFoodDrinkHubStyles()}
${golfEngagementHeadHtml('sport', true, 'hub')}
<style id="sports-hub">
  body.sports-hub-page .hub-links { margin: 26px 0 8px; }
  body.sports-hub-page .hub-links h2 { font-family: 'Fraunces', serif; font-weight: 600; font-size: 1.15rem; margin: 0 0 10px; }
  body.sports-hub-page .hub-links nav { display: flex; flex-wrap: wrap; gap: 8px; }
  body.sports-hub-page .hub-links a { display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; min-height: 40px; box-sizing: border-box; border: 1px solid rgba(27,43,58,0.18); border-radius: 999px; font-family: 'Nunito', sans-serif; font-size: 0.86rem; font-weight: 700; color: var(--ref-navy); text-decoration: none; background: var(--paper); }
  body.sports-hub-page .hub-links a:hover { background: rgba(27,43,58,0.06); }
  body.sports-hub-page .hub-links a span { font-size: 0.74rem; opacity: 0.6; }
  body.sports-hub-page .card-note-label { font-weight: 800; }
</style>
</head>
<body class="golf-page outdoor-page fd-page sport-page sports-hub-page">
${CATEGORY_BANNER_STYLE}
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([{ name: 'Home', href: '/' }, { name: 'Sports & Recreation' }])}
  ${categoryHeroHtml(categoryBannerHtml('sport'), `<h1>${escapeHtml(heading)}</h1>
  <p class="outdoor-intro fd-intro">${escapeHtml(HUB_INTRO_TEXT.sport)}</p>`)}
  ${foodDrinkSearchHtml().replace('Search food and drink', 'Search places to play').replace('Search by name, place or dish...', 'Search pickleball, pump track, a town...')}
  ${chips}
  ${controlsHtml}
  ${all.length ? '' : '<p class="sport-coming-soon">More sports and recreation spots are coming soon &mdash; skate parks, pump tracks, bike parks, disc golf courses and courts across the valley.</p>'}
  <section class="outdoor-step outdoor-step-results fd-results-step" aria-labelledby="fdResultsTop">
  <h2 class="visually-hidden" id="fdResultsTop">Results</h2>
  ${foodDrinkResultBarHtml(foodDrinkSummaryText(matching.length, venues.length, filtered).replace(/places?$/, (m) => (m === 'place' ? 'place to play' : 'places to play')), state, sort, SPORTS_SORTS)}
  <p class="fd-search-note" id="fdSearchNote" hidden></p>
  <div class="fd-no-results" id="fdNoResults"${matching.length === 0 ? '' : ' hidden'}><p><span id="fdNoResultsText">No places match that combination yet.</span> <a href="/sports" id="fdNoResultsClear">Clear the filters</a> to see everything.</p>
  <p class="fd-no-results-try">Try one word, like <a href="/sports?types=courts">pickleball</a>, <a href="/sports?types=skate">skate park</a> or <a href="/sports?types=bike">bike park</a>.</p></div>
  ${cardsHtml}
  <section class="hub-links" aria-labelledby="sportsActivitiesHeading">
    <h2 id="sportsActivitiesHeading">By activity</h2>
    <nav aria-label="Places to play by activity">
      ${activityLinks}
    </nav>
  </section>
  <section class="hub-links" aria-labelledby="sportsTownsHeading">
    <h2 id="sportsTownsHeading">By town</h2>
    <nav aria-label="Places to play by town">
      ${townLinks}
    </nav>
  </section>
  <script type="application/json" id="fdVenueData">${JSON.stringify(payload).replace(/</g, '\\u003c')}</script>
  </section>
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
  ${golfCardEngagementScriptHtml('sport', true)}
  ${renderFoodDrinkHubScriptHtml({ openNow: false, surface: 'sports', noun: ['place to play', 'places to play'], typeLabels: actLabel })}
</body>
</html>`;
}

// ---------- Dog Friendly Finds (2026-09-24): the directory at /dog-friendly ----------
//
// The homepage has carried a "Dog-Friendly Finds" card under Hidden Gems
// since 2026-09-17, but its href resolved to /browse -- the generic wizard,
// with no dog filter applied -- so the promise on the card ("patios and
// trails where your dog belongs") had no destination. This is that
// destination: a NEW, purely additive server-rendered hub in the same shape
// as /wineries, /outdoors and /food-drink. okanagan.html, app.js, /browse,
// Wine, Golf, Beaches, Outdoors, What's On and Food & Drink are unchanged;
// the only homepage change is that one card's href (see
// HIDDEN_GEM_EDITORIAL_CARDS).
//
// The hub unions the site's TWO dog datasets, which are disjoint in
// production (audited 2026-09-24: 254 + 27, zero overlap):
//
//   venues.dog_friendly = 1          -- 254 places that welcome your dog WITH
//                                       you: restaurants, cafes, pubs,
//                                       cocktail lounges, breweries,
//                                       wineries. Read-only here: the frozen
//                                       homepage embeds per-region counts of
//                                       this column in its hidden SEO block,
//                                       so flipping one would change '/'.
//   the 'dog_friendly' collection    -- 27 curated beaches where the dog
//                                       itself is officially allowed, each
//                                       carrying the exact restriction
//                                       (off-leash, designated area,
//                                       seasonal) in collection_items.note.
//
// Wineries ARE included even though /wineries exists: this directory answers
// "where can I take my dog", and a dog-friendly tasting patio is one of the
// best answers in the valley. /wineries remains the dedicated wine discovery
// directory and is untouched.
const DOG_BEACH_TYPE_KEY = 'dog-beach';
const DOG_HUB_TYPES = [
  { type: 'restaurant', label: 'Restaurants' },
  { type: 'cafe', label: 'Caf\u00e9s' },
  { type: 'pub', label: 'Pubs & Bars' },
  { type: 'cocktail', label: 'Cocktail Lounges' },
  { type: 'brewery', label: 'Breweries' },
  { type: 'distillery', label: 'Distilleries' },
  { type: 'winery', label: 'Wineries' },
  { type: DOG_BEACH_TYPE_KEY, label: 'Dog Beaches' },
  // Parks & Trails (2026-10-14): the dog-friendly parks, trails and other
  // outdoor places, which had no chip of their own.
  { type: 'outdoors', label: 'Parks & Trails' },
];
const DOG_HUB_OUTDOOR_TYPES = new Set(['outdoor', 'beach', 'sport', 'golf', 'tour']);
const DOG_HUB_TYPE_KEYS = new Set(DOG_HUB_TYPES.map((t) => t.type));
// The venues.type values a card on this page can have, for the engagement
// script's holder selector. 'dog-beach' is a hub-only grouping key, not a
// venues.type -- those rows are type 'beach'.
const DOG_HUB_VENUE_TYPES = [...FOOD_DRINK_TYPES, 'winery', 'beach'];
// Only three features, and only ones with real coverage on these records.
// Deliberately NOT offered: off-leash, dog park, water access, parking and
// seasonal restrictions -- no column represents any of them, and the
// off-leash/seasonal detail that DOES exist lives as free text inside the
// beach notes, which is shown on the card rather than pretended into a
// filter. The dog beaches carry none of these three flags (verified), so
// selecting a feature legitimately narrows to the "bring your dog along"
// side; the contextual counts say so rather than promising otherwise.
const DOG_HUB_FEATURES = [
  { key: 'patio', label: 'Patio', icon: '\u2600\uFE0F' },
  { key: 'lake_view', label: 'Lake View', icon: '\uD83C\uDF0A' },
  { key: 'great_groups', label: 'Great for Groups', icon: '\uD83D\uDC65' },
];
const DOG_HUB_FEATURE_KEYS = new Set(DOG_HUB_FEATURES.map((f) => f.key));
const DOG_HUB_LABEL_BY_TYPE = Object.fromEntries(DOG_HUB_TYPES.map((t) => [t.type, t.label]));
const DOG_HUB_LABEL_BY_FEATURE = Object.fromEntries(DOG_HUB_FEATURES.map((f) => [f.key, f.label]));

// The hub's universe: every active venue that is either flagged dog_friendly
// or holds a dog_friendly collection membership. One query, one ORDER BY, so
// a venue that is somehow both appears exactly once.
function getDogFriendlyHubVenues() {
  const rows = db.prepare(`
    SELECT v.* FROM venues v
    WHERE v.redirect_to IS NULL AND (
      v.dog_friendly = 1
      OR EXISTS (
        SELECT 1 FROM collection_items ci
        JOIN collections c ON c.id = ci.collection_id
        WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = ?
      )
    )
    ORDER BY v.name ASC
  `).all(DOG_FRIENDLY_COLLECTION_KIND).map(rowToVenue);
  return attachFoodDrinkCategories(rows);
}
// venue id -> the hub type keys it answers to. A dog beach contributes
// 'dog-beach'; a dog_friendly venue contributes its effective Food & Drink
// categories (so a brewery that is also a restaurant answers to both) or its
// own type for wineries.
function dogHubCategoriesByVenue(venues, beachIds) {
  const map = new Map();
  for (const v of venues) {
    const cats = [];
    if (beachIds.has(v.id)) cats.push(DOG_BEACH_TYPE_KEY);
    if (Number(v.dog_friendly) === 1) {
      const fd = (v.fd_categories && v.fd_categories.length) ? v.fd_categories : [];
      for (const t of fd) if (DOG_HUB_TYPE_KEYS.has(t) && !cats.includes(t)) cats.push(t);
      if (DOG_HUB_TYPE_KEYS.has(v.type) && !cats.includes(v.type)) cats.push(v.type);
      if (DOG_HUB_OUTDOOR_TYPES.has(v.type) && !cats.includes(DOG_BEACH_TYPE_KEY) && !cats.includes('outdoors')) cats.push('outdoors');
    }
    map.set(v.id, cats);
  }
  return map;
}
function dogHubFeaturesByVenue(venues) {
  const map = new Map();
  for (const v of venues) map.set(v.id, DOG_HUB_FEATURES.filter((f) => Number(v[f.key]) === 1).map((f) => f.key));
  return map;
}

// The filter predicate, shared verbatim by the server render and the inline
// client script (see DOG_HUB_FILTER_CLIENT_PREDICATE_SRC). Same three-group
// contract as Food & Drink -- types OR, regions OR, features AND, AND between
// the groups -- but this is the dog hub's OWN copy: /food-drink's predicate
// is untouched.
function dogFilterMatches(selTypes, selFeatures, selRegions, venueCats, venueFeatures, venueRegion) {
  const typeOk = !selTypes.length || selTypes.some((t) => venueCats.includes(t));
  const regionOk = !selRegions.length || selRegions.includes(venueRegion);
  const featureOk = selFeatures.every((f) => venueFeatures.includes(f));
  return typeOk && regionOk && featureOk;
}
const DOG_HUB_FILTER_CLIENT_PREDICATE_SRC = `function dogMatches(types, features, regions, venueCats, venueFeatures, venueRegion){
    var typeOk = !types.length, regionOk = !regions.length || regions.indexOf(venueRegion) !== -1;
    for (var i = 0; i < types.length && !typeOk; i++) { if (venueCats.indexOf(types[i]) !== -1) typeOk = true; }
    var featureOk = true;
    for (var j = 0; j < features.length && featureOk; j++) { if (venueFeatures.indexOf(features[j]) === -1) featureOk = false; }
    return typeOk && regionOk && featureOk;
  }`;
function filterDogVenues(venues, f, catsById, featsById) {
  return venues.filter((v) => dogFilterMatches(f.types, f.features, f.regions, catsById.get(v.id) || [], featsById.get(v.id) || [], v.region));
}
// ?types=a,b&features=x,y&regions=c,d -- unknown values are dropped and
// duplicates collapse, so a hand-edited link degrades to "fewer constraints",
// never an error page.
function parseDogFilterQuery(query) {
  const split = (v) => (typeof v === 'string' ? v : Array.isArray(v) ? v.join(',') : '').split(',').map((x) => x.trim()).filter(Boolean);
  const types = [], features = [], regions = [];
  for (const t of split(query && query.types)) if (DOG_HUB_TYPE_KEYS.has(t) && !types.includes(t)) types.push(t);
  for (const f of split(query && query.features)) if (DOG_HUB_FEATURE_KEYS.has(f) && !features.includes(f)) features.push(f);
  for (const r of split(query && query.regions)) if (REGION_LABELS[r] && !regions.includes(r)) regions.push(r);
  return { types, features, regions };
}
// Contextual counts: each chip shows how many venues it would contribute
// given the OTHER groups' current selection, so a count can never promise
// results a tap won't deliver.
function dogChipCounts(venues, f, catsById, featsById) {
  const types = {}, features = {}, regions = {};
  for (const v of venues) {
    const cats = catsById.get(v.id) || [], feats = featsById.get(v.id) || [];
    if (dogFilterMatches([], f.features, f.regions, cats, feats, v.region)) for (const t of cats) types[t] = (types[t] || 0) + 1;
    if (dogFilterMatches(f.types, f.features, [], cats, feats, v.region)) regions[v.region] = (regions[v.region] || 0) + 1;
    if (dogFilterMatches(f.types, [], f.regions, cats, feats, v.region)) for (const k of feats) features[k] = (features[k] || 0) + 1;
  }
  return { types, features, regions };
}
// The one-line count, shared verbatim by the server and the client twin.
function dogSummaryText(shown, total, filtered) {
  const noun = total === 1 ? 'place' : 'places';
  return filtered ? `${shown} of ${total} ${noun}` : `${total} dog-friendly ${noun}`;
}
const DOG_HUB_SUMMARY_CLIENT_SRC = `function dogSummaryText(shown, total, filtered){
    var noun = total === 1 ? 'place' : 'places';
    return filtered ? (shown + ' of ' + total + ' ' + noun) : (total + ' dog-friendly ' + noun);
  }`;

function dogSearchHtml() {
  return `<div class="fd-search">
    <label class="visually-hidden" for="dogSearch">Search dog friendly places</label>
    <input type="search" id="dogSearch" class="fd-search-input" placeholder="Search by name, place or beach..." autocomplete="off" spellcheck="false">
    <button type="button" class="fd-search-clear" id="dogSearchClear" aria-label="Clear search" hidden>&#215;</button>
  </div>`;
}
// Venue-type chips: "All" plus the seven. "All" is a reset control
// (data-dog-type-all), not an eighth type.
function dogTypeChipsHtml(state = {}) {
  const selected = new Set(state.types || []);
  const counts = state.counts && state.counts.types ? state.counts.types : null;
  const all = `<button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-dog-type-all="1" aria-pressed="${selected.size ? 'false' : 'true'}">All</button>`;
  const chips = DOG_HUB_TYPES.map((t) => {
    const n = counts ? (counts[t.type] || 0) : null;
    return `<button type="button" class="outdoor-filter-chip fd-type-chip" data-dog-type="${t.type}" aria-pressed="${selected.has(t.type) ? 'true' : 'false'}">${escapeHtml(t.label)}${n === null ? '' : `<span class="outdoor-activity-count">${n}</span>`}</button>`;
  }).join('');
  return `<div class="fd-type-row" role="group" aria-label="Choose venue types" data-filter="dog-type">${all}${chips}</div>`;
}
function dogFeatureChipsHtml(state = {}) {
  const selected = new Set(state.features || []);
  const counts = state.counts && state.counts.features ? state.counts.features : null;
  const chips = DOG_HUB_FEATURES.map((f) => {
    const n = counts ? (counts[f.key] || 0) : null;
    return `<button type="button" class="outdoor-filter-chip fd-feature-chip" data-dog-feature="${f.key}" aria-pressed="${selected.has(f.key) ? 'true' : 'false'}"><span class="fd-feature-icon" aria-hidden="true">${f.icon}</span> ${escapeHtml(f.label)}${n === null ? '' : `<span class="outdoor-activity-count">${n}</span>`}</button>`;
  }).join('');
  return `<div class="fd-feature-grid" role="group" aria-label="Choose what you are looking for" data-filter="dog-feature">${chips}</div>`;
}
// The two popovers. Regions reuses renderOutdoorRegionFilterChips() verbatim,
// so the canonical region list and its FOOTER_REGION_GROUPS grouping are
// literally the same code the other directories use -- no second region
// taxonomy, and it cannot drift.
function dogFilterBarHtml(venues, state = {}) {
  const nF = (state.features || []).length, nR = (state.regions || []).length;
  const pop = (id, label, icon, badge, panel) => `<div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="${id}Btn" aria-expanded="false" aria-controls="${id}Panel"><span class="fd-pop-icon" aria-hidden="true">${icon}</span> ${label}<span class="fd-pop-count" id="${id}Count"${badge ? '' : ' hidden'}>${badge ? ` \u00b7 ${escapeHtml(String(badge))}` : ''}</span></button>
      <div class="fd-pop-panel" id="${id}Panel" hidden>${panel}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-dog-apply>Show results</button></div>
      </div>
    </div>`;
  return `<div class="fd-controls">
    ${pop('dogFeatures', 'What are you looking for?', '\u2728', nF || '', dogFeatureChipsHtml(state))}
    ${pop('dogRegions', 'Regions', '\uD83D\uDCCD', nR || '', renderOutdoorRegionFilterChips(venues, { selectedRegions: state.regions || [], counts: state.counts }))}
  </div>`;
}
function dogSelectedTagsHtml(state = {}) {
  const tag = (kind, v, label) => `<button type="button" class="outdoor-selected-tag" data-dog-remove-${kind}="${escapeHtml(v)}" aria-label="Remove ${escapeHtml(label)}">${escapeHtml(label)}<span class="outdoor-selected-x" aria-hidden="true">\u00d7</span></button>`;
  const row = (label, tags) => (tags.length ? `<div class="outdoor-selected-row"><span class="outdoor-selected-label">${label}</span> ${tags.join(' ')}</div>` : '');
  const t = (state.types || []).map((x) => tag('type', x, DOG_HUB_LABEL_BY_TYPE[x] || x));
  const f = (state.features || []).map((x) => tag('feature', x, DOG_HUB_LABEL_BY_FEATURE[x] || x));
  const r = (state.regions || []).map((x) => tag('region', x, REGION_LABELS[x] || x));
  const any = t.length + f.length + r.length > 0;
  return `<div class="outdoor-selected" id="dogSelected"${any ? '' : ' hidden'}>${row('Types', t)}${row('Looking for', f)}${row('Regions', r)}${any ? '<button type="button" class="outdoor-selected-clear" id="dogSelectedClear">Clear all</button>' : ''}</div>`;
}
function dogResultBarHtml(summary, state) {
  return `<div class="fd-resultbar">
    <p class="fd-count" id="dogResultsSummary" aria-live="polite">${escapeHtml(summary)}</p>
  </div>
  ${dogSelectedTagsHtml(state)}`;
}
// The regional /guide/<region>/dog_friendly pages already exist, are indexed
// and are already in the sitemap. Linking them from the hub joins the two up
// instead of competing with them. Built from the same listGuideCombos()
// predicate the sitemap uses, so a link cannot outlive its page.
function dogRegionGuideLinksHtml() {
  const combos = listGuideCombos(MIN_GUIDE_VENUES)
    .filter((c) => c.badge === 'dog_friendly' && REGION_LABELS[c.region])
    .sort((a, b) => b.count - a.count);
  if (!combos.length) return '';
  return `<div class="related-section dog-guides">
        <h2>Dog-friendly guides by community</h2>
        <p>${combos.map((c) => `<a href="/guide/${c.region}/${c.badge}">${escapeHtml(REGION_LABELS[c.region])} (${c.count})</a>`).join(', ')}</p>
      </div>`;
}

// Page-scoped stylesheet. The Food & Drink hub's .fd-* control classes are
// reused verbatim (same controls, same behaviour, no reason for a second
// visual language) and are NOT modified here -- this block only scopes them
// to body.dog-page and adds the one thing this page has that no other
// directory does: the inline dog-beach restriction note.
function renderDogHubStyles() {
  return `<style>
  body.dog-page .visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
  body.dog-page .fd-intro { margin: 0 0 14px; max-width: 70ch; }

  body.dog-page .fd-search { position: relative; margin: 0 0 12px; max-width: 520px; }
  body.dog-page .fd-search-input { width: 100%; box-sizing: border-box; font: inherit; font-family: 'Nunito', sans-serif; font-size: 0.95rem; padding: 10px 36px 10px 14px; min-height: 42px; border-radius: 999px; border: 1px solid rgba(27,43,58,0.18); background: var(--paper); color: var(--ink); }
  body.dog-page .fd-search-input::placeholder { color: rgba(42,32,25,0.55); }
  body.dog-page .fd-search-input:focus-visible { outline: 2px solid var(--ref-gold); outline-offset: 2px; }
  body.dog-page .fd-search-input::-webkit-search-cancel-button, body.dog-page .fd-search-input::-webkit-search-decoration { -webkit-appearance: none; appearance: none; }
  body.dog-page .fd-search-clear { position: absolute; right: 6px; top: 50%; transform: translateY(-50%); border: 0; background: transparent; cursor: pointer; font-size: 1.2rem; line-height: 1; color: var(--ink); opacity: 0.6; padding: 6px 8px; }
  body.dog-page .fd-search-clear[hidden] { display: none; }

  /* flex-wrap: nowrap is explicit so the chips scroll sideways on a phone
     instead of stacking into a tall block; desktop wraps instead. */
  body.dog-page .fd-type-row { display: flex; flex-wrap: nowrap; gap: 8px; overflow-x: auto; overflow-y: hidden; -webkit-overflow-scrolling: touch; scrollbar-width: thin; padding: 2px 0 8px; margin: 0 0 10px; }
  body.dog-page .fd-type-row::-webkit-scrollbar { height: 6px; }
  body.dog-page .fd-type-row::-webkit-scrollbar-thumb { background: rgba(74,52,40,0.2); border-radius: 999px; }
  body.dog-page .fd-type-row .outdoor-filter-chip { flex: 0 0 auto; white-space: nowrap; }
  @media (min-width: 900px) { body.dog-page .fd-type-row { flex-wrap: wrap; overflow: visible; } }

  body.dog-page .fd-controls { display: flex; flex-wrap: wrap; gap: 8px; margin: 0 0 12px; }
  body.dog-page .fd-pop { position: relative; }
  body.dog-page .fd-pop-btn { display: inline-flex; align-items: center; gap: 6px; font-family: 'Nunito', sans-serif; font-size: 0.86rem; font-weight: 800; color: var(--ink); background: var(--paper); border: 1px solid rgba(27,43,58,0.18); border-radius: 999px; padding: 8px 14px; min-height: 40px; cursor: pointer; transition: background .12s ease, color .12s ease, border-color .12s ease; }
  body.dog-page .fd-pop-btn:hover { background: rgba(27,43,58,0.06); color: var(--ref-navy); }
  body.dog-page .fd-pop-btn:focus-visible { outline: 2px solid var(--ref-gold); outline-offset: 2px; }
  body.dog-page .fd-pop-btn[aria-expanded="true"] { background: var(--ref-navy, #1B2B3A); color: var(--paper); border-color: var(--ref-navy, #1B2B3A); }
  body.dog-page .fd-pop-count[hidden] { display: none; }
  body.dog-page .fd-pop-panel { position: absolute; z-index: 40; top: calc(100% + 6px); left: 0; min-width: 280px; max-width: min(92vw, 620px); max-height: 60vh; overflow-y: auto; background: var(--paper); border: 1px solid rgba(27,43,58,0.18); border-radius: 14px; box-shadow: 0 18px 40px -20px var(--shadow, rgba(42,32,25,0.5)); padding: 14px; }
  body.dog-page .fd-pop-panel[hidden] { display: none; }
  /* Without scripting a popover can never be opened, so the panels stay
     visible inline and the page degrades to the full control set. */
  body.dog-page .fd-controls:not(.js) .fd-pop-panel, body.dog-page .fd-controls:not(.js) .fd-pop-panel[hidden] { position: static; display: block; max-width: none; max-height: none; box-shadow: none; border: 0; padding: 10px 0 0; }
  body.dog-page .fd-controls:not(.js) .fd-pop-btn { display: none; }
  /* On phones a panel is a full-width sheet under the controls row; the ROW
     is the positioning context, so the offset resolves against the button. */
  @media (max-width: 640px) {
    body.dog-page .fd-controls { position: relative; }
    body.dog-page .fd-pop { position: static; }
    body.dog-page .fd-pop-panel { left: 0; right: 0; width: auto; min-width: 0; max-width: none; }
  }
  @media (min-width: 900px) { body.dog-page .fd-pop-panel { min-width: 520px; } }
  body.dog-page .fd-pop-panel .outdoor-region-groups { margin: 0; }
  body.dog-page .fd-feature-grid { display: flex; flex-wrap: wrap; gap: 8px; }
  body.dog-page .fd-feature-icon { font-size: 0.95em; }

  body.dog-page .fd-pop-actions { position: sticky; bottom: -14px; margin: 12px -14px -14px; padding: 10px 14px; background: var(--paper); border-top: 1px solid rgba(27,43,58,0.12); border-radius: 0 0 14px 14px; }
  body.dog-page .fd-pop-apply { display: block; width: 100%; font-family: 'Nunito', sans-serif; font-size: 0.86rem; font-weight: 800; color: var(--ref-cream); background: var(--ref-navy); border: 1px solid var(--ref-gold); border-radius: 999px; padding: 10px 16px; min-height: 44px; cursor: pointer; transition: background .12s ease; }
  body.dog-page .fd-pop-apply:hover { background: var(--ref-navy-deep); }
  body.dog-page .fd-pop-apply:focus-visible { outline: 2px solid var(--ref-gold); outline-offset: 2px; }

  body.dog-page .fd-resultbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin: 4px 0 6px; }
  body.dog-page .fd-count { margin: 0; font-family: 'Nunito', sans-serif; font-size: 0.95rem; font-weight: 800; color: var(--ink); }
  body.dog-page .fd-results-step { margin-top: 4px; }
  body.dog-page #dogResults > .venue-card[hidden] { display: none; }
  body.dog-page .fd-no-results { margin: 14px 0 0; font-family: 'Nunito', sans-serif; font-weight: 700; }

  /* The dog-beach restriction, on the card where it is actually read. Teal
     rather than the advisory's amber: this is standing official information,
     not a temporary warning, and the two must not look alike. */
  body.dog-page .dog-note { margin: 8px 0 0; font-family: 'Nunito', sans-serif; font-size: 0.86rem; line-height: 1.45; color: var(--ink); background: rgba(42,107,103,0.08); border-left: 3px solid var(--teal, #2A6B67); border-radius: 0 8px 8px 0; padding: 8px 10px; }
  body.dog-page .dog-note-label { font-weight: 800; color: var(--teal-deep, #1E4F4C); }
  body.dog-page .dog-guides { margin-top: 28px; }
</style>`;
}

// The inline script: the same interaction contract as the Food & Drink hub
// (toggle chips, filter the already-rendered cards, keep the selection in the
// URL, pushState/popstate, Clear all) over this page's three groups. No
// incremental rendering: every card is in the list from the first byte, so
// there is no <template>, no "Show more" and no re-parenting -- at this size
// that machinery would cost more than it saves. No network, no framework.
function renderDogHubScriptHtml() {
  const labels = {
    regions: { ...REGION_LABELS },
    types: { ...DOG_HUB_LABEL_BY_TYPE },
    features: { ...DOG_HUB_LABEL_BY_FEATURE },
  };
  return `<script>
(function(){
  var LABELS = ${JSON.stringify(labels).replace(/</g, '\\u003c')};
  var dataEl = document.getElementById('dogVenueData');
  var DATA = dataEl ? JSON.parse(dataEl.textContent || '{}') : {};
  var typeChips = Array.prototype.slice.call(document.querySelectorAll('[data-dog-type]'));
  var featureChips = Array.prototype.slice.call(document.querySelectorAll('[data-dog-feature]'));
  var regionChips = Array.prototype.slice.call(document.querySelectorAll('[data-region]'));
  var allChip = document.querySelector('[data-dog-type-all]');
  var cards = Array.prototype.slice.call(document.querySelectorAll('#dogResults > .venue-card'));
  if (!cards.length) return;
  var searchInput = document.getElementById('dogSearch');
  var searchClear = document.getElementById('dogSearchClear');
  var summary = document.getElementById('dogResultsSummary');
  var selectedBox = document.getElementById('dogSelected');
  var empty = document.getElementById('dogNoResults');
  var results = document.getElementById('dogResults');
  var featuresCount = document.getElementById('dogFeaturesCount');
  var regionsCount = document.getElementById('dogRegionsCount');
  var searchTerm = '';
  var applyBtns = Array.prototype.slice.call(document.querySelectorAll('[data-dog-apply]'));
  ${renderFilterChangeClientSrc('dog_friendly')}
  function activeFilterCount(){ return pressed(typeChips, 'data-dog-type').length + pressed(featureChips, 'data-dog-feature').length + pressed(regionChips, 'data-region').length; }
  ${DOG_HUB_FILTER_CLIENT_PREDICATE_SRC}
  ${DOG_HUB_SUMMARY_CLIENT_SRC}
  ${OUTDOOR_REGION_GROUP_CLIENT_SRC}
  // Searchable text per card, built once from data already in the markup:
  // name, community label, the labels of its types and features, the
  // meta/description lines and the dog-beach restriction note. No new data is
  // shipped for search.
  cards.forEach(function(card){
    var id = card.getAttribute('data-venue-id');
    var d = DATA[id] || { c: [], f: [], r: '' };
    var meta = card.querySelector('.venue-meta'), desc = card.querySelector('.golf-desc'), note = card.querySelector('.dog-note');
    var parts = [card.getAttribute('data-venue-name') || '', LABELS.regions[d.r] || '',
                 d.c.map(function(t){ return LABELS.types[t] || t; }).join(' '),
                 d.f.map(function(k){ return LABELS.features[k] || k; }).join(' '),
                 meta ? meta.textContent : '', desc ? desc.textContent : '', note ? note.textContent : '', d.k || ''];
    card.__dog = parts.join(' ').toLowerCase();
  });
  function pressed(list, attr){ return list.filter(function(c){ return c.getAttribute('aria-pressed') === 'true'; }).map(function(c){ return c.getAttribute(attr); }); }
  var groupsRoot = document.querySelector('.outdoor-region-groups');
  var groups = Array.prototype.slice.call(document.querySelectorAll('.outdoor-region-group-block'));
  var mobileQuery = window.matchMedia ? window.matchMedia('(max-width: 899px)') : null;
  function setGroupOpen(block, open){ var t = block.querySelector('.outdoor-region-group-toggle'), l = block.querySelector('.outdoor-region-group-chips'); if (!t || !l) return; t.setAttribute('aria-expanded', open ? 'true' : 'false'); l.hidden = !open; }
  function updateGroupHeaders(){
    groups.forEach(function(block){
      var n = block.querySelectorAll('.outdoor-filter-chip[aria-pressed="true"]').length;
      var sel = block.querySelector('.outdoor-region-group-selected');
      if (sel) { sel.textContent = groupSelectedText(n); sel.hidden = n === 0; }
      block.classList.toggle('has-selection', n > 0);
    });
  }
  if (groupsRoot) groupsRoot.classList.add('js');
  groups.forEach(function(block){ var t = block.querySelector('.outdoor-region-group-toggle'); if (t) t.addEventListener('click', function(){ setGroupOpen(block, t.getAttribute('aria-expanded') !== 'true'); }); });
  function updateCounts(types, features, regions){
    var tC = {}, fC = {}, rC = {};
    cards.forEach(function(card){
      var d = DATA[card.getAttribute('data-venue-id')] || { c: [], f: [], r: '' };
      if (dogMatches([], features, regions, d.c, d.f, d.r)) d.c.forEach(function(t){ tC[t] = (tC[t] || 0) + 1; });
      if (dogMatches(types, features, [], d.c, d.f, d.r)) rC[d.r] = (rC[d.r] || 0) + 1;
      if (dogMatches(types, [], regions, d.c, d.f, d.r)) d.f.forEach(function(k){ fC[k] = (fC[k] || 0) + 1; });
    });
    function paint(list, attr, counts){ list.forEach(function(c){ var n = c.querySelector('.outdoor-activity-count'); if (n) n.textContent = String(counts[c.getAttribute(attr)] || 0); }); }
    paint(typeChips, 'data-dog-type', tC); paint(featureChips, 'data-dog-feature', fC); paint(regionChips, 'data-region', rC);
  }
  function renderSelected(types, features, regions){
    if (!selectedBox) return;
    var any = types.length || features.length || regions.length;
    function tag(kind, v, label){ return '<button type="button" class="outdoor-selected-tag" data-dog-remove-' + kind + '="' + v + '" aria-label="Remove ' + label + '">' + label + '<span class="outdoor-selected-x" aria-hidden="true">\\u00d7</span></button>'; }
    function row(label, tags){ return tags.length ? '<div class="outdoor-selected-row"><span class="outdoor-selected-label">' + label + '</span> ' + tags.join(' ') + '</div>' : ''; }
    var html = row('Types', types.map(function(v){ return tag('type', v, LABELS.types[v] || v); }))
      + row('Looking for', features.map(function(v){ return tag('feature', v, LABELS.features[v] || v); }))
      + row('Regions', regions.map(function(v){ return tag('region', v, LABELS.regions[v] || v); }));
    if (any) html += '<button type="button" class="outdoor-selected-clear" id="dogSelectedClear">Clear all</button>';
    selectedBox.innerHTML = html;
    selectedBox.hidden = !any;
  }
  function queryFor(types, features, regions){
    var q = [];
    if (types.length) q.push('types=' + types.join(','));
    if (features.length) q.push('features=' + features.join(','));
    if (regions.length) q.push('regions=' + regions.join(','));
    return q.length ? '?' + q.join('&') : '';
  }
  function apply(historyMode){
    var types = pressed(typeChips, 'data-dog-type'), features = pressed(featureChips, 'data-dog-feature'), regions = pressed(regionChips, 'data-region');
    var shown = 0;
    cards.forEach(function(card){
      var d = DATA[card.getAttribute('data-venue-id')] || { c: [], f: [], r: '' };
      var ok = dogMatches(types, features, regions, d.c, d.f, d.r) && (!searchTerm || (card.__dog || '').indexOf(searchTerm) !== -1);
      card.hidden = !ok;
      if (ok) shown++;
    });
    var total = cards.length, filtered = types.length || features.length || regions.length || !!searchTerm;
    if (allChip) allChip.setAttribute('aria-pressed', types.length ? 'false' : 'true');
    if (featuresCount) { featuresCount.textContent = features.length ? (' \\u00b7 ' + features.length) : ''; featuresCount.hidden = features.length === 0; }
    if (regionsCount) { regionsCount.textContent = regions.length ? (' \\u00b7 ' + regions.length) : ''; regionsCount.hidden = regions.length === 0; }
    if (searchClear) searchClear.hidden = !searchTerm;
    if (summary) summary.textContent = dogSummaryText(shown, total, filtered);
    applyBtns.forEach(function(b){ b.textContent = 'Show ' + shown + ' result' + (shown === 1 ? '' : 's'); });
    updateGroupHeaders(); updateCounts(types, features, regions); renderSelected(types, features, regions);
    if (empty) empty.hidden = shown !== 0;
    if (results) results.hidden = shown === 0;
    var next = window.location.pathname + queryFor(types, features, regions) + window.location.hash;
    if (window.history && historyMode !== 'none') {
      if (historyMode === 'push' && window.history.pushState && next !== window.location.pathname + window.location.search + window.location.hash) window.history.pushState({ dog: true }, '', next);
      else if (window.history.replaceState) window.history.replaceState({ dog: true }, '', next);
    }
  }
  function toggle(chip){ chip.setAttribute('aria-pressed', chip.getAttribute('aria-pressed') === 'true' ? 'false' : 'true'); apply('push'); }
  [typeChips, featureChips, regionChips].forEach(function(list){ list.forEach(function(c){ c.addEventListener('click', function(){
    var on = c.getAttribute('aria-pressed') !== 'true';
    toggle(c);
    var group = c.hasAttribute('data-dog-type') ? 'type' : (c.hasAttribute('data-dog-feature') ? 'feature' : 'region');
    trackFilterChange(group, c.getAttribute(group === 'region' ? 'data-region' : 'data-dog-' + group), on ? 'add' : 'remove');
  }); }); });
  function clearAll(){
    [typeChips, featureChips, regionChips].forEach(function(list){ list.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); });
    searchTerm = ''; if (searchInput) searchInput.value = '';
    apply('push');
  }
  function clearAllByVisitor(){ var had = activeFilterCount(); clearAll(); if (had) trackFilterChange('all', 'all', 'clear_all'); }
  if (allChip) allChip.addEventListener('click', function(){ var had = pressed(typeChips, 'data-dog-type').length; typeChips.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); apply('push'); if (had) trackFilterChange('type', 'all', 'clear_all'); });
  if (searchInput) {
    var timer = null;
    searchInput.addEventListener('input', function(){ clearTimeout(timer); timer = setTimeout(function(){ searchTerm = searchInput.value.trim().toLowerCase(); apply('none'); }, 120); });
  }
  if (searchClear) searchClear.addEventListener('click', function(){ searchTerm = ''; if (searchInput) { searchInput.value = ''; searchInput.focus(); } apply('none'); });
  if (selectedBox) selectedBox.addEventListener('click', function(e){
    var t = e.target.closest ? e.target.closest('button') : null; if (!t) return;
    if (t.id === 'dogSelectedClear') { clearAllByVisitor(); return; }
    var map = [['data-dog-remove-type', typeChips, 'data-dog-type', 'type'], ['data-dog-remove-feature', featureChips, 'data-dog-feature', 'feature'], ['data-dog-remove-region', regionChips, 'data-region', 'region']];
    for (var i = 0; i < map.length; i++) {
      var v = t.getAttribute(map[i][0]);
      if (v) { map[i][1].forEach(function(c){ if (c.getAttribute(map[i][2]) === v) c.setAttribute('aria-pressed', 'false'); }.bind(null)); apply('push'); trackFilterChange(map[i][3], v, 'remove'); return; }
    }
  });
  var emptyClear = document.getElementById('dogNoResultsClear');
  if (emptyClear) emptyClear.addEventListener('click', function(e){ e.preventDefault(); clearAllByVisitor(); });
  var popsRoot = document.querySelector('.fd-controls');
  var pops = Array.prototype.slice.call(document.querySelectorAll('.fd-pop'));
  if (popsRoot) popsRoot.classList.add('js');
  function closePops(except){
    pops.forEach(function(pop){
      if (pop === except) return;
      var b = pop.querySelector('.fd-pop-btn'), pnl = pop.querySelector('.fd-pop-panel');
      if (b) b.setAttribute('aria-expanded', 'false');
      if (pnl) pnl.hidden = true;
    });
  }
  pops.forEach(function(pop){
    var b = pop.querySelector('.fd-pop-btn'), pnl = pop.querySelector('.fd-pop-panel');
    if (!b || !pnl) return;
    b.addEventListener('click', function(e){
      e.stopPropagation();
      var open = b.getAttribute('aria-expanded') === 'true';
      closePops(pop);
      b.setAttribute('aria-expanded', open ? 'false' : 'true');
      pnl.hidden = open;
    });
    pnl.addEventListener('click', function(e){ e.stopPropagation(); });
  });
  applyBtns.forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); closePops(null); }); });
  if (pops.length) {
    document.addEventListener('click', function(){ closePops(null); });
    document.addEventListener('keydown', function(e){ if (e.key === 'Escape') closePops(null); });
  }
  function readUrlIntoChips(){
    try {
      var params = new URLSearchParams(window.location.search);
      var pre = { t: (params.get('types') || '').split(',').filter(Boolean), f: (params.get('features') || '').split(',').filter(Boolean), r: (params.get('regions') || '').split(',').filter(Boolean) };
      typeChips.forEach(function(c){ c.setAttribute('aria-pressed', pre.t.indexOf(c.getAttribute('data-dog-type')) !== -1 ? 'true' : 'false'); });
      featureChips.forEach(function(c){ c.setAttribute('aria-pressed', pre.f.indexOf(c.getAttribute('data-dog-feature')) !== -1 ? 'true' : 'false'); });
      regionChips.forEach(function(c){ c.setAttribute('aria-pressed', pre.r.indexOf(c.getAttribute('data-region')) !== -1 ? 'true' : 'false'); });
    } catch (e) {}
  }
  function openGroupsForSelection(){
    groups.forEach(function(block){
      var isDefault = block.getAttribute('data-region-group') === '${OUTDOOR_REGION_GROUP_DEFAULT_OPEN}';
      var n = block.querySelectorAll('.outdoor-filter-chip[aria-pressed="true"]').length;
      setGroupOpen(block, (mobileQuery && mobileQuery.matches) ? groupShouldOpen(isDefault, n) : true);
    });
  }
  window.addEventListener('popstate', function(){ readUrlIntoChips(); openGroupsForSelection(); apply('none'); });
  readUrlIntoChips();
  openGroupsForSelection();
  apply('replace');
})();
</script>`;
}

// The page. Same themed shell as /food-drink and /wineries (homepage header,
// Trip tray, app.css, name-as-link cards with the "View details" cue,
// Favorite / Add to Trip) so the engagement contract is identical -- list
// cards carry ONLY Favorite and Add to Trip; Website / Directions / Call stay
// on the venue detail pages, which are untouched.
// Dog Friendly Finds (2026-10-14) runs on the shared directory engine, like
// /indoor and /sports: type chips (now with Parks & Trails), search, Regions,
// features, Open now, a sort, 48 at a time and a photo per card -- a dog
// photo for restaurants, cafés, pubs, lounges, breweries and distilleries,
// a beach or trail photo outdoors -- instead of all 421 cards with one
// painted picture. Every card says where dogs can go when we know it: the
// official rule for the dog beaches and, for other places, the venue's own
// stated rule from the 'dog_policy' collection. The "Dog-Friendly" badge is
// left off the cards, since everything on this page is dog-friendly.
// venue id -> the dog rule ("Patio only, on leash") from the dog_policy collection.
function getDogPolicyNotes() {
  const rows = db.prepare(`
    SELECT ci.content_id AS id, ci.note FROM collection_items ci
    JOIN collections c ON c.id = ci.collection_id
    WHERE c.kind = ? AND ci.content_type = 'venue' AND ci.note IS NOT NULL AND trim(ci.note) != ''
  `).all(DOG_POLICY_COLLECTION_KIND);
  return new Map(rows.map((r) => [r.id, r.note]));
}
const DOG_SORTS = [
  { key: 'recommended', label: 'Recommended' },
  { key: 'town', label: 'By town' },
  { key: 'az', label: 'A\u2013Z' },
];
const DOG_SORT_KEYS = new Set(DOG_SORTS.map((x) => x.key));
// Recommended: the Food & Drink ranking (rating weighted by review count),
// with a nudge for places that tell you where your dog can go, since that is
// the question this page answers. Never an editorial flag.
function dogRecommendedScore(v, hasRule) {
  const base = DOG_HUB_OUTDOOR_TYPES.has(v.type) ? 3.95 + (String(v.description || '').length >= 120 ? 0.04 : 0) : foodDrinkRecommendedScore(v);
  return base + (hasRule ? 0.12 : 0);
}
function dogCardPhotoKey(v, isBeach) {
  const id = Number(v.id) || 0;
  if (isBeach) return `dogbeach-${id % FD_CARD_PHOTOS.dogbeach.length}`;
  if (DOG_HUB_OUTDOOR_TYPES.has(v.type)) return v.type === 'beach' ? `dogbeach-${id % FD_CARD_PHOTOS.dogbeach.length}` : `dogoutdoor-${id % FD_CARD_PHOTOS.dogoutdoor.length}`;
  if (v.type === 'winery') return `winery-${id % FD_CARD_PHOTOS.winery.length}`;
  const t = FD_CARD_PHOTOS[v.type] ? v.type : 'restaurant';
  // Every other card shows a dog at a table of that kind, so a run of
  // restaurants does not repeat one picture.
  if (FD_CARD_DOG_PHOTOS[t] && id % 2 === 0) return `${t}-dog`;
  return foodDrinkCardPhotoKey({ ...v, dog_friendly: 0 });
}
function renderDogHubPage(venues, filter = null, now = new Date()) {
  const f = { types: [], features: [], regions: [], ...(filter || {}) };
  const sort = DOG_SORT_KEYS.has(f.sort) ? f.sort : 'recommended';
  const openNow = !!f.openNow;
  const beachIds = getCollectionVenueIds(DOG_FRIENDLY_COLLECTION_KIND);
  const policyNotes = getDogPolicyNotes();
  const catsById = dogHubCategoriesByVenue(venues, beachIds);
  const byName = (a, b) => String(a.name).localeCompare(String(b.name), 'en', { sensitivity: 'base' });
  const score = new Map(venues.map((v) => [v.id, dogRecommendedScore(v, beachIds.has(v.id) || policyNotes.has(v.id))]));
  const ranked = venues.slice().sort((a, b) => score.get(b.id) - score.get(a.id) || byName(a, b));
  // A mixed first screen: in the first dozen, at most two of any one kind and
  // never two of a kind back to back, so it doesn't open on ten wineries.
  const leadOf = (v) => (catsById.get(v.id) || [])[0] || v.type;
  const recommended = [];
  const rest = ranked.slice();
  const seenLead = {};
  while (rest.length) {
    const prev = recommended.length ? leadOf(recommended[recommended.length - 1]) : null;
    let pick = recommended.length < 12 ? rest.slice(0, 30).findIndex((v) => leadOf(v) !== prev && (seenLead[leadOf(v)] || 0) < 2) : -1;
    if (pick < 0) pick = rest.slice(0, 6).findIndex((v) => leadOf(v) !== prev);
    if (pick < 0) pick = 0;
    const v = rest.splice(pick, 1)[0];
    seenLead[leadOf(v)] = (seenLead[leadOf(v)] || 0) + 1;
    recommended.push(v);
  }
  const recommendedRank = new Map(recommended.map((v, i) => [v.id, i]));
  const list = sort === 'az' ? venues.slice().sort(byName)
    : sort === 'town' ? venues.slice().sort((a, b) => String(REGION_LABELS[a.region] || '').localeCompare(String(REGION_LABELS[b.region] || '')) || byName(a, b))
      : recommended;
  const featsById = foodDrinkFeaturesByVenue(list);
  for (const [id, fs] of featsById) featsById.set(id, fs.filter((k) => k !== 'dog_friendly'));
  const featureTally = {};
  for (const fs of featsById.values()) for (const k of fs) featureTally[k] = (featureTally[k] || 0) + 1;
  const featureKeys = ['patio', 'lake_view', 'kid_friendly', 'great_groups', 'live_music', 'vegetarian'].filter((k) => (featureTally[k] || 0) >= 5);
  f.features = f.features.filter((k) => featureKeys.includes(k));
  f.types = f.types.filter((t) => DOG_HUB_TYPE_KEYS.has(t));
  const advisoryNotes = getAdvisoryNotes();
  const openInfo = foodDrinkOpenNowInfo(list, advisoryNotes, now, { requireVerified: false });
  const pool = openNow ? list.filter((v) => openInfo.openIds.has(v.id)) : list;
  const matching = filterFoodDrinkVenues(pool, f, catsById, featsById);
  const matchIds = new Set(matching.map((v) => v.id));
  const counts = foodDrinkChipCounts(pool, f, catsById, featsById);
  const openCount = filterFoodDrinkVenues(list.filter((v) => openInfo.openIds.has(v.id)), f, catsById, featsById).length;
  const filtered = f.types.length > 0 || f.features.length > 0 || f.regions.length > 0 || openNow;
  const state = { types: f.types, features: f.features, regions: f.regions, counts, openNow };
  const beachCount = venues.filter((v) => beachIds.has(v.id)).length;
  const dogContent = (f.types.length === 1 && DOG_CATEGORY_CONTENT[f.types[0]]) || DOG_CATEGORY_CONTENT.all;

  const title = 'Dog Friendly Finds in the Okanagan | Okanagan Roam';
  const description = `${venues.length} dog-friendly places across the Okanagan Valley: patios, caf\u00e9s, taprooms, tasting rooms, parks and trails, plus ${beachCount} designated dog beaches, with where your dog can go.`;
  const canonical = 'https://okanaganroam.com/dog-friendly';
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: 'Dog Friendly Finds', url: canonical },
  ]);
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: title,
    description,
    itemListElement: list.map((v, i) => ({
      '@type': 'ListItem',
      position: i + 1,
      url: `https://okanaganroam.com/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}`,
      item: { '@type': SCHEMA_TYPE_MAP[v.type] || 'LocalBusiness', name: v.name },
    })),
  };
  const payload = {};
  for (const v of list) {
    payload[String(v.id)] = { c: catsById.get(v.id) || [], f: featsById.get(v.id) || [], r: v.region, k: descSearchWords(`${policyNotes.get(v.id) || ''} ${v.description || ''}`), o: recommendedRank.get(v.id) };
    const st = openInfo.byId.get(v.id);
    if (st && st.eligible) payload[String(v.id)].h = compactFoodDrinkHours(st.hours);
  }
  // Beaches carry their rule as the dog-beach note (dogNoteInline); every
  // other place with a stated rule gets the same "Dogs:" line.
  const cardNotes = new Map([...policyNotes].filter(([id]) => !beachIds.has(id)));
  const cardsHtml = foodDrinkBatchedCardsHtml(list, matchIds, matching.length, advisoryNotes, true, openInfo.byId, {
    cardNotes, cardNoteLabel: 'Dogs:', photoKeyFor: (v) => dogCardPhotoKey(v, beachIds.has(v.id)),
    cardOpts: { dogNoteInline: true, hideDogBadges: true },
  });
  const selected = new Set(f.types);
  const chips = `<div class="fd-type-row" role="group" aria-label="Choose a kind of place" data-filter="fd-type"><button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-fd-type-all="1" aria-pressed="${selected.size ? 'false' : 'true'}">All</button>${DOG_HUB_TYPES.map((t) => `<button type="button" class="outdoor-filter-chip fd-type-chip" data-fd-type="${t.type}" aria-pressed="${selected.has(t.type) ? 'true' : 'false'}">${escapeHtml(t.label)}<span class="outdoor-activity-count">${counts.types[t.type] || 0}</span></button>`).join('')}</div>`;
  const nF = f.features.length, nR = f.regions.length;
  const pop = (id, labelHtml, icon, badge, panel) => `<div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="${id}Btn" aria-expanded="false" aria-controls="${id}Panel"><span class="fd-pop-icon" aria-hidden="true">${icon}</span> ${labelHtml}<span class="fd-pop-count" id="${id}Count"${badge ? '' : ' hidden'}>${badge ? ` \u00b7 ${escapeHtml(String(badge))}` : ''}</span></button>
      <div class="fd-pop-panel" id="${id}Panel" hidden>${panel}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-fd-apply>Show results</button></div>
      </div>
    </div>`;
  const controlsHtml = `<div class="fd-controls">
    ${pop('fdRegions', 'Regions', '\u{1F4CD}', nR || '', renderOutdoorRegionFilterChips(list, { selectedRegions: f.regions, counts }))}
    ${featureKeys.length ? pop('fdFeatures', '<span class="fd-pop-long">What are you looking for?</span><span class="fd-pop-short">Filters</span>', '\u2728', nF || '', foodDrinkFeatureChipsHtml(state, featureKeys)) : ''}
    ${foodDrinkOpenNowToggleHtml(openNow, openCount)}
  </div>`;
  const typeLabels = Object.fromEntries(DOG_HUB_TYPES.map((t) => [t.type, t.label]));

  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, itemList], { shareImage: dogContent.banner.src, golfTheme: true, beachTheme: list.some((v) => v.type === 'beach'), advisoryStyles: list.some((v) => advisoryNotes.has(v.id)), savedSidecar: true })}
${renderOutdoorThemeStyles()}
${renderFoodDrinkHubStyles()}
${renderFoodDrinkOpenNowStyles()}
${golfEngagementHeadHtml('dog', true, 'hub')}
<style id="dog-hub">
  body.dog-hub-page .dog-note, body.dog-hub-page .card-note { margin: 2px 0 10px; font-size: 0.9rem; line-height: 1.45; color: var(--teal-deep, #1F5450); }
  body.dog-hub-page .dog-note-label, body.dog-hub-page .card-note-label { font-weight: 800; }
  body.dog-hub-page .dog-rule-intro { margin: 0 0 14px; font-size: 0.9rem; opacity: 0.75; }
  body.dog-hub-page .dog-guides { margin: 26px 0 8px; }
  body.dog-hub-page .dog-guides h2 { font-family: 'Fraunces', serif; font-weight: 600; font-size: 1.15rem; margin: 0 0 10px; }
</style>
</head>
<body class="golf-page outdoor-page fd-page dog-page dog-hub-page">
${CATEGORY_BANNER_STYLE}
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main">
  ${breadcrumbNavHtml([{ name: 'Home', href: '/' }, { name: 'Dog Friendly Finds' }])}
  ${categoryHeroHtml(`<div class="category-banner" id="dogBanner"><img src="${dogContent.banner.src}" alt="${escapeHtml(dogContent.banner.alt)}" width="1600" height="1067" style="object-position: 50% ${dogContent.banner.pos}%" fetchpriority="high"></div>
  <script>
  (function(){
    var c = ${JSON.stringify(DOG_CATEGORY_CONTENT).replace(/</g, '\\u003c')};
    var box = document.getElementById('dogBanner'); if (!box) return;
    var img = box.querySelector('img');
    var sync = function(){
      var on = Array.prototype.slice.call(document.querySelectorAll('.fd-type-chip[data-fd-type][aria-pressed="true"]')).map(function(x){ return x.getAttribute('data-fd-type'); });
      var t = (on.length === 1 && c[on[0]]) || c.all, b = t.banner;
      if (img.getAttribute('src') !== b.src) { img.removeAttribute('srcset'); img.src = b.src; img.alt = b.alt; img.style.objectPosition = '50% ' + b.pos + '%'; }
      var h = document.querySelector('.category-hero-text h1'), p = document.querySelector('.category-hero-text .fd-intro');
      if (h && h.textContent !== t.heading) h.textContent = t.heading;
      if (p && p.textContent !== t.intro) p.textContent = t.intro;
    };
    try { new MutationObserver(sync).observe(document.body, { subtree: true, attributes: true, attributeFilter: ['aria-pressed'] }); } catch (e) {}
  })();
  </script>`, `<h1>${escapeHtml(dogContent.heading)}</h1>
  <p class="outdoor-intro fd-intro">${escapeHtml(dogContent.intro)}</p>
  <p class="subtitle"><a href="${DOG_GUIDE_PATH}">Guide: dog-friendly Kelowna, with the dog rules for each place &rarr;</a></p>`)}
  ${foodDrinkSearchHtml().replace('Search food and drink', 'Search dog friendly places').replace('Search by name, place or dish...', 'Search by name, town, beach or trail...')}
  ${chips}
  ${controlsHtml}
  <p class="fd-open-note">${escapeHtml(FD_OPEN_NOTE)}</p>
  <section class="outdoor-step outdoor-step-results fd-results-step" aria-labelledby="fdResultsTop">
  <h2 class="visually-hidden" id="fdResultsTop">Results</h2>
  ${foodDrinkResultBarHtml(foodDrinkSummaryText(matching.length, list.length, filtered), state, sort, DOG_SORTS)}
  <p class="dog-rule-intro">Where we know the rule, each card says where your dog can go, from the venue's own site or the city's official dog-beach list. Rules can change, so check with the place before you go.</p>
  <p class="fd-search-note" id="fdSearchNote" hidden></p>
  <div class="fd-no-results" id="fdNoResults"${matching.length === 0 ? '' : ' hidden'}><p><span id="fdNoResultsText">No dog-friendly places match that combination yet.</span> <a href="/dog-friendly" id="fdNoResultsClear">Clear the filters</a> to see everything.</p>
  <p class="fd-no-results-try">Try one word, like <a href="/dog-friendly?types=dog-beach">dog beaches</a>, <a href="/dog-friendly?types=brewery">breweries</a> or <a href="/dog-friendly?types=outdoors">trails</a>.</p></div>
  ${cardsHtml}
  <p class="fd-open-note fd-open-note-end">${escapeHtml(FD_OPEN_NOTE)}</p>
  <script type="application/json" id="fdVenueData">${JSON.stringify(payload).replace(/</g, '\\u003c')}</script>
  </section>
  ${dogRegionGuideLinksHtml()}
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
  ${golfCardEngagementScriptHtml('dog', true)}
  ${renderFoodDrinkHubScriptHtml({ openNow: true, surface: 'dog', typeLabels, searchLabels: { 'dog-beach': 'dog beach off-leash', outdoors: 'park trail hike walk' } })}
</body>
</html>`;
}

// ---------- Local Favourites (2026-09-24): the page at /local-favorites ----------
//
// The destination for the homepage's Hidden Gems "Local Favourites" card,
// which until now resolved to /browse. Membership is read live from the
// 'local_favorite' collection -- nothing is hard-coded, so an audited
// membership change through POST /admin/collection-membership is reflected
// here immediately. The per-membership rationale in collection_items.note is
// internal editorial metadata and is deliberately NOT rendered.
//
// Same themed shell and controls as /dog-friendly (homepage header, Trip
// tray, name-as-link cards with the "View details" cue, Favorite / Add to
// Trip only, search, type chips, the canonical grouped region selector),
// reduced to the two filters this collection genuinely supports: category
// (OR) and region (OR), ANDed together. No feature filter: the members carry
// almost no badge flags, so one would offer choices that return nothing.
// The page's styles are derived from renderDogHubStyles() by re-scoping the
// selector, so the two directories share one visual language and
// /dog-friendly's own output is untouched.
// The /indoor hub's "Also good on a rainy day" section: live venues of any
// other type in the indoor_also collection (an `indoor` venue is already in
// the hub's main list, so it is never repeated here).
// venue id -> the membership note ("Indoor ice: public skating sessions")
// for the indoor_also collection.
function getIndoorAlsoNotes() {
  const rows = db.prepare(`
    SELECT ci.content_id AS id, ci.note FROM collection_items ci
    JOIN collections c ON c.id = ci.collection_id
    WHERE c.kind = ? AND ci.content_type = 'venue' AND ci.note IS NOT NULL AND trim(ci.note) != ''
  `).all(INDOOR_ALSO_COLLECTION_KIND);
  return new Map(rows.map((r) => [r.id, r.note]));
}

// The /tours hub's "More experiences to book" (2026-10-11): live venues of
// any other type in the tours_also collection, and their membership notes
// ("Guided ATV tours, May to October"), exactly as for indoor_also.
function getToursAlsoNotes() {
  const rows = db.prepare(`
    SELECT ci.content_id AS id, ci.note FROM collection_items ci
    JOIN collections c ON c.id = ci.collection_id
    WHERE c.kind = ? AND ci.content_type = 'venue' AND ci.note IS NOT NULL AND trim(ci.note) != ''
  `).all(TOURS_ALSO_COLLECTION_KIND);
  return new Map(rows.map((r) => [r.id, r.note]));
}
function getToursAlsoVenues() {
  return db.prepare(`
    SELECT v.* FROM venues v
    WHERE v.redirect_to IS NULL AND v.type != 'tour' AND EXISTS (
      SELECT 1 FROM collection_items ci
      JOIN collections c ON c.id = ci.collection_id
      WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = ?
    )
    ORDER BY v.name ASC
  `).all(TOURS_ALSO_COLLECTION_KIND).map(rowToVenue);
}

// The /sports hub's "More places to play" (2026-10-12): live venues of any
// other type in the sports_also collection, and their membership notes
// ("Skate park and two tennis courts"), exactly as for tours_also.
function getSportsAlsoNotes() {
  const rows = db.prepare(`
    SELECT ci.content_id AS id, ci.note FROM collection_items ci
    JOIN collections c ON c.id = ci.collection_id
    WHERE c.kind = ? AND ci.content_type = 'venue' AND ci.note IS NOT NULL AND trim(ci.note) != ''
  `).all(SPORTS_ALSO_COLLECTION_KIND);
  return new Map(rows.map((r) => [r.id, r.note]));
}
function getSportsAlsoVenues() {
  return db.prepare(`
    SELECT v.* FROM venues v
    WHERE v.redirect_to IS NULL AND v.type != 'sport' AND EXISTS (
      SELECT 1 FROM collection_items ci
      JOIN collections c ON c.id = ci.collection_id
      WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = ?
    )
    ORDER BY v.name ASC
  `).all(SPORTS_ALSO_COLLECTION_KIND).map(rowToVenue);
}

function getIndoorAlsoVenues() {
  return db.prepare(`
    SELECT v.* FROM venues v
    WHERE v.redirect_to IS NULL AND v.type != 'indoor' AND EXISTS (
      SELECT 1 FROM collection_items ci
      JOIN collections c ON c.id = ci.collection_id
      WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = ?
    )
    ORDER BY v.name ASC
  `).all(INDOOR_ALSO_COLLECTION_KIND).map(rowToVenue);
}

// Curated-list card notes (2026-10-11). Most editorial membership notes are
// internal rationale and stay off the page (see the Local Favourites / Secret
// Spots tests), so only notes known to be written for visitors are shown:
// members added in a batch listed in PUBLIC_NOTE_BATCHES (each add's batch_id
// is in venue_enrichment_log as field 'collection:<kind>'), plus the original
// Hidden Gems seeded by db.js (HIDDEN_GEMS_MEMBERS), which have no add row.
const PUBLIC_NOTE_BATCHES = ['gems-favourites-2026-10', 'public-notes-2026-10'];
function getPublicCollectionNotes(kind) {
  const rows = db.prepare(`
    SELECT ci.content_id AS id, ci.note,
      (SELECT l.batch_id FROM venue_enrichment_log l
        WHERE l.venue_id = ci.content_id AND l.field_name = ? AND l.new_value = 'member'
        ORDER BY l.id DESC LIMIT 1) AS batch_id
    FROM collection_items ci
    JOIN collections c ON c.id = ci.collection_id
    WHERE c.kind = ? AND ci.content_type = 'venue' AND ci.note IS NOT NULL AND trim(ci.note) != ''
  `).all(`collection:${kind}`, kind);
  const seeded = kind === 'hidden_gem';
  return new Map(rows
    .filter((r) => (r.batch_id ? PUBLIC_NOTE_BATCHES.includes(r.batch_id) : seeded))
    .map((r) => [r.id, r.note]));
}

function getLocalFavouriteVenues() {
  return db.prepare(`
    SELECT v.* FROM venues v
    WHERE v.redirect_to IS NULL AND EXISTS (
      SELECT 1 FROM collection_items ci
      JOIN collections c ON c.id = ci.collection_id
      WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind = 'local_favorite'
    )
    ORDER BY v.name ASC
  `).all().map(rowToVenue);
}
// The category chips offered: the venue types actually present, in the
// site's canonical CATEGORY_SLUGS order, labelled with CATEGORY_LABELS.
function localFavouriteTypesPresent(venues) {
  const present = new Set(venues.map((v) => v.type));
  return Object.keys(CATEGORY_SLUGS).filter((t) => present.has(t) && CATEGORY_LABELS[t]);
}
function localFavouriteFilterMatches(selTypes, selRegions, venueType, venueRegion) {
  return (!selTypes.length || selTypes.includes(venueType)) && (!selRegions.length || selRegions.includes(venueRegion));
}
const LOCAL_FAVOURITES_FILTER_CLIENT_PREDICATE_SRC = `function lfMatches(types, regions, venueType, venueRegion){
    return (!types.length || types.indexOf(venueType) !== -1) && (!regions.length || regions.indexOf(venueRegion) !== -1);
  }`;
// ?types=a,b&regions=c,d -- unknown values are dropped and duplicates
// collapse, so a hand-edited link degrades to "fewer constraints".
function parseLocalFavouritesFilterQuery(query) {
  const split = (v) => (typeof v === 'string' ? v : Array.isArray(v) ? v.join(',') : '').split(',').map((x) => x.trim()).filter(Boolean);
  const types = [], regions = [];
  for (const t of split(query && query.types)) if (CATEGORY_SLUGS[t] && !types.includes(t)) types.push(t);
  for (const r of split(query && query.regions)) if (REGION_LABELS[r] && !regions.includes(r)) regions.push(r);
  return { types, regions };
}
// Contextual counts: each chip shows what it would contribute given the
// other group's current selection.
function localFavouriteChipCounts(venues, f) {
  const types = {}, regions = {};
  for (const v of venues) {
    if (localFavouriteFilterMatches([], f.regions, v.type, v.region)) types[v.type] = (types[v.type] || 0) + 1;
    if (localFavouriteFilterMatches(f.types, [], v.type, v.region)) regions[v.region] = (regions[v.region] || 0) + 1;
  }
  return { types, regions };
}
function localFavouritesSummaryText(shown, total, filtered, label = 'local favourite') {
  const noun = total === 1 ? 'place' : 'places';
  return filtered ? `${shown} of ${total} ${noun}` : `${total} ${label} ${noun}`;
}
const LOCAL_FAVOURITES_SUMMARY_CLIENT_SRC = `function lfSummaryText(shown, total, filtered){
    var noun = total === 1 ? 'place' : 'places';
    return filtered ? (shown + ' of ' + total + ' ' + noun) : (total + ' local favourite ' + noun);
  }`;
function localFavouritesTypeChipsHtml(types, state = {}) {
  const selected = new Set(state.types || []);
  const counts = state.counts && state.counts.types ? state.counts.types : {};
  const all = `<button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-lf-type-all="1" aria-pressed="${selected.size ? 'false' : 'true'}">All</button>`;
  const chips = types.map((t) => `<button type="button" class="outdoor-filter-chip fd-type-chip" data-lf-type="${t}" aria-pressed="${selected.has(t) ? 'true' : 'false'}">${escapeHtml(CATEGORY_LABELS[t].plural)}<span class="outdoor-activity-count">${counts[t] || 0}</span></button>`).join('');
  return `<div class="fd-type-row" role="group" aria-label="Choose categories" data-filter="lf-type">${all}${chips}</div>`;
}
function localFavouritesFilterBarHtml(venues, state = {}) {
  const nR = (state.regions || []).length;
  return `<div class="fd-controls">
    <div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="lfRegionsBtn" aria-expanded="false" aria-controls="lfRegionsPanel"><span class="fd-pop-icon" aria-hidden="true">\uD83D\uDCCD</span> Regions<span class="fd-pop-count" id="lfRegionsCount"${nR ? '' : ' hidden'}>${nR ? ` \u00b7 ${nR}` : ''}</span></button>
      <div class="fd-pop-panel" id="lfRegionsPanel" hidden>${renderOutdoorRegionFilterChips(venues, { selectedRegions: state.regions || [], counts: state.counts })}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-lf-apply>Show results</button></div>
      </div>
    </div>
  </div>`;
}
function localFavouritesSelectedTagsHtml(state = {}) {
  const tag = (kind, v, label) => `<button type="button" class="outdoor-selected-tag" data-lf-remove-${kind}="${escapeHtml(v)}" aria-label="Remove ${escapeHtml(label)}">${escapeHtml(label)}<span class="outdoor-selected-x" aria-hidden="true">\u00d7</span></button>`;
  const row = (label, tags) => (tags.length ? `<div class="outdoor-selected-row"><span class="outdoor-selected-label">${label}</span> ${tags.join(' ')}</div>` : '');
  const t = (state.types || []).map((x) => tag('type', x, CATEGORY_LABELS[x] ? CATEGORY_LABELS[x].plural : x));
  const r = (state.regions || []).map((x) => tag('region', x, REGION_LABELS[x] || x));
  const any = t.length + r.length > 0;
  return `<div class="outdoor-selected" id="lfSelected"${any ? '' : ' hidden'}>${row('Categories', t)}${row('Regions', r)}${any ? '<button type="button" class="outdoor-selected-clear" id="lfSelectedClear">Clear all</button>' : ''}</div>`;
}
function renderLocalFavouritesStyles() {
  return renderDogHubStyles()
    .split('\n')
    .filter((line) => !/dog-note|dog-guides|The dog-beach restriction|rather than the advisory|not a temporary warning/.test(line))
    .join('\n')
    .replace(/body\.dog-page/g, 'body.lf-page')
    .replace(/#dogResults/g, '#lfResults')
    // Collection notes on the curated pages' cards ("Local pick: …",
    // "Why it's a gem: …"), styled like the /indoor and /tours note line.
    .replace(/<\/style>\s*$/, `  body.lf-page .card-note { margin: 8px 0 0; font-family: 'Nunito', sans-serif; font-size: 0.86rem; line-height: 1.45; color: var(--ink); background: rgba(42,107,103,0.08); border-left: 3px solid var(--teal, #2A6B67); border-radius: 0 8px 8px 0; padding: 8px 10px; }
  body.lf-page .card-note-label { font-weight: 800; color: var(--teal-deep, #1E4F4C); }
</style>`);
}
function renderLocalFavouritesScriptHtml(summaryLabel = 'local favourite', filterSurface = 'local_favourites') {
  const labels = {
    regions: { ...REGION_LABELS },
    types: Object.fromEntries(Object.keys(CATEGORY_LABELS).map((t) => [t, CATEGORY_LABELS[t].plural])),
  };
  return `<script>
(function(){
  var LABELS = ${JSON.stringify(labels).replace(/</g, '\\u003c')};
  var dataEl = document.getElementById('lfVenueData');
  var DATA = dataEl ? JSON.parse(dataEl.textContent || '{}') : {};
  var typeChips = Array.prototype.slice.call(document.querySelectorAll('[data-lf-type]'));
  var regionChips = Array.prototype.slice.call(document.querySelectorAll('[data-region]'));
  var allChip = document.querySelector('[data-lf-type-all]');
  var cards = Array.prototype.slice.call(document.querySelectorAll('#lfResults > .venue-card'));
  if (!cards.length) return;
  var searchInput = document.getElementById('lfSearch');
  var searchClear = document.getElementById('lfSearchClear');
  var summary = document.getElementById('lfResultsSummary');
  var selectedBox = document.getElementById('lfSelected');
  var empty = document.getElementById('lfNoResults');
  var results = document.getElementById('lfResults');
  var regionsCount = document.getElementById('lfRegionsCount');
  var applyBtns = Array.prototype.slice.call(document.querySelectorAll('[data-lf-apply]'));
  var searchTerm = '';
  ${renderFilterChangeClientSrc(filterSurface)}
  function activeFilterCount(){ return pressed(typeChips, 'data-lf-type').length + pressed(regionChips, 'data-region').length; }
  ${LOCAL_FAVOURITES_FILTER_CLIENT_PREDICATE_SRC}
  ${LOCAL_FAVOURITES_SUMMARY_CLIENT_SRC.replace("' local favourite '", `' ${summaryLabel} '`)}
  ${OUTDOOR_REGION_GROUP_CLIENT_SRC}
  cards.forEach(function(card){
    var d = DATA[card.getAttribute('data-venue-id')] || { t: '', r: '' };
    var meta = card.querySelector('.venue-meta'), desc = card.querySelector('.golf-desc');
    card.__lf = [card.getAttribute('data-venue-name') || '', LABELS.regions[d.r] || '', LABELS.types[d.t] || '', meta ? meta.textContent : '', desc ? desc.textContent : ''].join(' ').toLowerCase();
  });
  function pressed(list, attr){ return list.filter(function(c){ return c.getAttribute('aria-pressed') === 'true'; }).map(function(c){ return c.getAttribute(attr); }); }
  var groupsRoot = document.querySelector('.outdoor-region-groups');
  var groups = Array.prototype.slice.call(document.querySelectorAll('.outdoor-region-group-block'));
  var mobileQuery = window.matchMedia ? window.matchMedia('(max-width: 899px)') : null;
  function setGroupOpen(block, open){ var t = block.querySelector('.outdoor-region-group-toggle'), l = block.querySelector('.outdoor-region-group-chips'); if (!t || !l) return; t.setAttribute('aria-expanded', open ? 'true' : 'false'); l.hidden = !open; }
  function updateGroupHeaders(){
    groups.forEach(function(block){
      var n = block.querySelectorAll('.outdoor-filter-chip[aria-pressed="true"]').length;
      var sel = block.querySelector('.outdoor-region-group-selected');
      if (sel) { sel.textContent = groupSelectedText(n); sel.hidden = n === 0; }
      block.classList.toggle('has-selection', n > 0);
    });
  }
  if (groupsRoot) groupsRoot.classList.add('js');
  groups.forEach(function(block){ var t = block.querySelector('.outdoor-region-group-toggle'); if (t) t.addEventListener('click', function(){ setGroupOpen(block, t.getAttribute('aria-expanded') !== 'true'); }); });
  function updateCounts(types, regions){
    var tC = {}, rC = {};
    cards.forEach(function(card){
      var d = DATA[card.getAttribute('data-venue-id')] || { t: '', r: '' };
      if (lfMatches([], regions, d.t, d.r)) tC[d.t] = (tC[d.t] || 0) + 1;
      if (lfMatches(types, [], d.t, d.r)) rC[d.r] = (rC[d.r] || 0) + 1;
    });
    function paint(list, attr, counts){ list.forEach(function(c){ var n = c.querySelector('.outdoor-activity-count'); if (n) n.textContent = String(counts[c.getAttribute(attr)] || 0); }); }
    paint(typeChips, 'data-lf-type', tC); paint(regionChips, 'data-region', rC);
  }
  function renderSelected(types, regions){
    if (!selectedBox) return;
    var any = types.length || regions.length;
    function tag(kind, v, label){ return '<button type="button" class="outdoor-selected-tag" data-lf-remove-' + kind + '="' + v + '" aria-label="Remove ' + label + '">' + label + '<span class="outdoor-selected-x" aria-hidden="true">\\u00d7</span></button>'; }
    function row(label, tags){ return tags.length ? '<div class="outdoor-selected-row"><span class="outdoor-selected-label">' + label + '</span> ' + tags.join(' ') + '</div>' : ''; }
    var html = row('Categories', types.map(function(v){ return tag('type', v, LABELS.types[v] || v); }))
      + row('Regions', regions.map(function(v){ return tag('region', v, LABELS.regions[v] || v); }));
    if (any) html += '<button type="button" class="outdoor-selected-clear" id="lfSelectedClear">Clear all</button>';
    selectedBox.innerHTML = html;
    selectedBox.hidden = !any;
  }
  function queryFor(types, regions){
    var q = [];
    if (types.length) q.push('types=' + types.join(','));
    if (regions.length) q.push('regions=' + regions.join(','));
    return q.length ? '?' + q.join('&') : '';
  }
  function apply(historyMode){
    var types = pressed(typeChips, 'data-lf-type'), regions = pressed(regionChips, 'data-region');
    var shown = 0;
    cards.forEach(function(card){
      var d = DATA[card.getAttribute('data-venue-id')] || { t: '', r: '' };
      var ok = lfMatches(types, regions, d.t, d.r) && (!searchTerm || (card.__lf || '').indexOf(searchTerm) !== -1);
      card.hidden = !ok;
      if (ok) shown++;
    });
    var total = cards.length, filtered = types.length || regions.length || !!searchTerm;
    if (allChip) allChip.setAttribute('aria-pressed', types.length ? 'false' : 'true');
    if (regionsCount) { regionsCount.textContent = regions.length ? (' \\u00b7 ' + regions.length) : ''; regionsCount.hidden = regions.length === 0; }
    if (searchClear) searchClear.hidden = !searchTerm;
    if (summary) summary.textContent = lfSummaryText(shown, total, filtered);
    applyBtns.forEach(function(b){ b.textContent = 'Show ' + shown + ' result' + (shown === 1 ? '' : 's'); });
    updateGroupHeaders(); updateCounts(types, regions); renderSelected(types, regions);
    if (empty) empty.hidden = shown !== 0;
    if (results) results.hidden = shown === 0;
    var next = window.location.pathname + queryFor(types, regions) + window.location.hash;
    if (window.history && historyMode !== 'none') {
      if (historyMode === 'push' && window.history.pushState && next !== window.location.pathname + window.location.search + window.location.hash) window.history.pushState({ lf: true }, '', next);
      else if (window.history.replaceState) window.history.replaceState({ lf: true }, '', next);
    }
  }
  function toggle(chip){ chip.setAttribute('aria-pressed', chip.getAttribute('aria-pressed') === 'true' ? 'false' : 'true'); apply('push'); }
  [typeChips, regionChips].forEach(function(list){ list.forEach(function(c){ c.addEventListener('click', function(){
    var on = c.getAttribute('aria-pressed') !== 'true';
    toggle(c);
    var isType = c.hasAttribute('data-lf-type');
    trackFilterChange(isType ? 'type' : 'region', c.getAttribute(isType ? 'data-lf-type' : 'data-region'), on ? 'add' : 'remove');
  }); }); });
  function clearAll(){
    [typeChips, regionChips].forEach(function(list){ list.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); });
    searchTerm = ''; if (searchInput) searchInput.value = '';
    apply('push');
  }
  function clearAllByVisitor(){ var had = activeFilterCount(); clearAll(); if (had) trackFilterChange('all', 'all', 'clear_all'); }
  if (allChip) allChip.addEventListener('click', function(){ var had = pressed(typeChips, 'data-lf-type').length; typeChips.forEach(function(c){ c.setAttribute('aria-pressed', 'false'); }); apply('push'); if (had) trackFilterChange('type', 'all', 'clear_all'); });
  if (searchInput) {
    var timer = null;
    searchInput.addEventListener('input', function(){ clearTimeout(timer); timer = setTimeout(function(){ searchTerm = searchInput.value.trim().toLowerCase(); apply('none'); }, 120); });
  }
  if (searchClear) searchClear.addEventListener('click', function(){ searchTerm = ''; if (searchInput) { searchInput.value = ''; searchInput.focus(); } apply('none'); });
  if (selectedBox) selectedBox.addEventListener('click', function(e){
    var t = e.target.closest ? e.target.closest('button') : null; if (!t) return;
    if (t.id === 'lfSelectedClear') { clearAllByVisitor(); return; }
    var map = [['data-lf-remove-type', typeChips, 'data-lf-type', 'type'], ['data-lf-remove-region', regionChips, 'data-region', 'region']];
    for (var i = 0; i < map.length; i++) {
      var v = t.getAttribute(map[i][0]);
      if (v) { map[i][1].forEach(function(c){ if (c.getAttribute(map[i][2]) === v) c.setAttribute('aria-pressed', 'false'); }); apply('push'); trackFilterChange(map[i][3], v, 'remove'); return; }
    }
  });
  var emptyClear = document.getElementById('lfNoResultsClear');
  if (emptyClear) emptyClear.addEventListener('click', function(e){ e.preventDefault(); clearAllByVisitor(); });
  var popsRoot = document.querySelector('.fd-controls');
  var pops = Array.prototype.slice.call(document.querySelectorAll('.fd-pop'));
  if (popsRoot) popsRoot.classList.add('js');
  function closePops(except){
    pops.forEach(function(pop){
      if (pop === except) return;
      var b = pop.querySelector('.fd-pop-btn'), pnl = pop.querySelector('.fd-pop-panel');
      if (b) b.setAttribute('aria-expanded', 'false');
      if (pnl) pnl.hidden = true;
    });
  }
  pops.forEach(function(pop){
    var b = pop.querySelector('.fd-pop-btn'), pnl = pop.querySelector('.fd-pop-panel');
    if (!b || !pnl) return;
    b.addEventListener('click', function(e){
      e.stopPropagation();
      var open = b.getAttribute('aria-expanded') === 'true';
      closePops(pop);
      b.setAttribute('aria-expanded', open ? 'false' : 'true');
      pnl.hidden = open;
    });
    pnl.addEventListener('click', function(e){ e.stopPropagation(); });
  });
  applyBtns.forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); closePops(null); }); });
  if (pops.length) {
    document.addEventListener('click', function(){ closePops(null); });
    document.addEventListener('keydown', function(e){ if (e.key === 'Escape') closePops(null); });
  }
  function readUrlIntoChips(){
    try {
      var params = new URLSearchParams(window.location.search);
      var pre = { t: (params.get('types') || '').split(',').filter(Boolean), r: (params.get('regions') || '').split(',').filter(Boolean) };
      typeChips.forEach(function(c){ c.setAttribute('aria-pressed', pre.t.indexOf(c.getAttribute('data-lf-type')) !== -1 ? 'true' : 'false'); });
      regionChips.forEach(function(c){ c.setAttribute('aria-pressed', pre.r.indexOf(c.getAttribute('data-region')) !== -1 ? 'true' : 'false'); });
    } catch (e) {}
  }
  function openGroupsForSelection(){
    groups.forEach(function(block){
      var isDefault = block.getAttribute('data-region-group') === '${OUTDOOR_REGION_GROUP_DEFAULT_OPEN}';
      var n = block.querySelectorAll('.outdoor-filter-chip[aria-pressed="true"]').length;
      setGroupOpen(block, (mobileQuery && mobileQuery.matches) ? groupShouldOpen(isDefault, n) : true);
    });
  }
  window.addEventListener('popstate', function(){ readUrlIntoChips(); openGroupsForSelection(); apply('none'); });
  readUrlIntoChips();
  openGroupsForSelection();
  apply('replace');
})();
</script>`;
}
