    const a = `<a class="lang-toggle" id="langToggle" href="${href}" hreflang="${lang === 'fr' ? 'en' : 'fr'}" aria-label="${lang === 'fr' ? 'Voir cette page en anglais' : 'View this page in French'}" data-i18n-aria="nav.switchLanguage">${label}</a>`;
